(window.ST=window.ST||{}).stories=[{"id":"atlab_aang","name":"Aang","chapters":[{"id":"atlab_aang_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"atlab_aang","t":"Baksana, Appa iyice dinlendi!"},{"a":"atlab_aang","t":"Sanırım veda vakti geldi..."},{"a":"atlab_sokka","t":"Hey, neşelen biraz! İstediğimiz zaman geri gelebiliriz!"},{"a":"atlab_aang","t":"Haklısın! Yolu hatırlıyor musun Sokka?"},{"a":"atlab_sokka","t":"Şey... Pek dikkat etmiyordum..."},{"a":"atlab_sokka","t":"Neyse, geri dönüp halletmemiz gereken çok önemli Avatar işleri var!"},{"a":"atlab_sokka","t":"Haydi gel Momo! Gidiyoruz!"},{"a":"atlab_aang","t":"Momo! Momo?"},{"a":"atlab_aang","t":"Burayı sevdin demek. Öyle olsun."},{"a":"atlab_aang","t":"Acaba bir süre Momo'ya göz kulak olabilir misin?"},{"a":"atlab_aang","t":"Daha sonra senin için geri geleceğim Momo, söz veriyorum!"},{"a":"atlab_aang","t":"Gidelim Sokka. Her şey için teşekkürler!"},{"a":"atlab_sokka","t":"Hoşça kal!"},{"a":"atlab_aang","t":"Haydi Appa! Yip yip!"}]},{"id":"atlab_aang_01","i":1,"title":"Kaderin Cilvesi","req":"atlab_aang:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Şans Jetonları"},"side":false,"lines":[{"a":"inn","t":"Üzgünüm evlat, tam anlayamadım. Hikâyeni baştan anlatabilir misin?"},{"a":"atlab_aang","t":"Pardon! Dur baştan anlatayım!"},{"a":"atlab_aang","t":"Ben, Avatar Aang."},{"a":"atlab_aang","t":"Arkadaşlarımla birlikte uçan bizonumla seyahat ediyorduk..."},{"a":"atlab_aang","t":"Uçarken yanlış bir yöne sapmış olmalıyız çünkü kendimizi burada bulduk!"},{"a":"inn","t":"Dışarıdaki o koca bizonu mu diyorsun? O uçabiliyor mu?"},{"a":"atlab_aang","t":"Evet! Adı Appa. Çok dost canlısıdır!"},{"a":"inn","t":"Çok da yorgun görünüyor. Sizi birileri kovalıyordu, değil mi?"},{"a":"atlab_aang","t":"Şey..."},{"a":"inn","t":"Merak etme. Evime misafir ettiğim kimsenin zarar görmesine izin vermem. Sana Oscar sözü!"},{"a":"inn","t":"Bak ne diyeceğim. Burada ücretsiz kalmaya ne dersiniz?"},{"a":"atlab_aang","t":"Ücretsiz mi? Gerçekten mi?"},{"a":"inn","t":"Yani zaten yanındaki o tuhaf para burada geçmez."},{"a":"inn","t":"Sonuçta çocukları sokakta bırakacak hâlim yok, değil mi?"},{"a":"atlab_aang","t":"Teşekkürler Bay Oscar!"},{"a":"inn","t":"Elinden iş gelen birine benziyorsun. Karşılığında tüccar dostuma yardım etmeye ne dersin?"},{"a":"atlab_aang","t":"Elbette! Çok teşekkür ederim!"}]},{"id":"atlab_aang_02","i":2,"title":"Ateş bükme mi?","req":"atlab_aang:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Şans Jetonları"},"side":false,"lines":[{"a":"inn","t":"Lilu! Gel de yeni dostumla tanış!"},{"a":"lilu","t":"Merhaba! Hiç sendekiler gibi dövmeler görmemiştim..."},{"a":"atlab_aang","t":"Ben Aang! Ben de hiç seninki gibi bir şapka görmemiştim!"},{"a":"inn","t":"Haydi Aang, ona neler yapabildiğini göster!"},{"a":"atlab_aang","t":"Bunu mu demek istiyorsun?"},{"a":"lilu","t":"Bunu nasıl yaptın? Hiç büyü sezmedim!"},{"a":"atlab_aang","t":"Hava bükerek! Toprak ve su da bükebilirim!"},{"a":"lilu","t":"Muhteşem! Dur bunları not alayım..."},{"a":"lilu","t":"Chi olabilir mi bu? Daha önce kimsenin böyle bir şey yaptığını görmemiştim..."},{"a":"atlab_aang","t":"Doğru! Ama herkesin yapabileceği bir şey değildir. Hem bu beceriyle doğmalı hem de bu konuda uzmanlaşmalısın!"},{"a":"lilu","t":"Havayı, toprağı ve suyu bükebildiğini söyledin. Peki ya ateş?"},{"a":"atlab_aang","t":"Şey... Henüz ateş bükme konusunda uzmanlaşamadım..."},{"a":"atlab_aang","t":"Açıkçası bana ders verecek bir ateş bükme ustası bulmakta zorlanıyorum."},{"a":"lilu","t":"Öyle mi? Bildiğim bazı ateş büyüleri var!"},{"a":"lilu","t":"Tam olarak aynı değil ama belki nasıl çalıştığını görmek isteyebilirsin!"},{"a":"atlab_aang","t":"Şey... Tabii. Teşekkürler Lilu."}]},{"id":"atlab_aang_03","i":3,"title":"Son Hava Bükücü","req":"atlab_aang:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Şans Jetonları"},"side":false,"lines":[{"a":"elderowen","t":"Aang, evlat. Şehir hayatını nasıl buldun?"},{"a":"atlab_aang","t":"İhtiyar Owen! Çok hoşuma gitti! Konukseverliğiniz için çok teşekkürler!"},{"a":"elderowen","t":"Rica ederim. Peki ama ailen nerede evlat?"},{"a":"atlab_aang","t":"Şey... Ailem... Artık hayatta değil."},{"a":"atlab_aang","t":"Ailem ve tüm Hava Gezginleri Ateş Ulusu tarafından öldürüldü."},{"a":"atlab_aang","t":"Bir tek ben kaldım."},{"a":"elderowen","t":"Tanrım! Çok üzüldüm evlat..."},{"a":"elderowen","t":"Dönecek bir evin yoksa arkadaşlarınla burada kalmaya ne dersin?"},{"a":"elderowen","t":"Eminim şehirdeki herkes sizin varlığınızdan memnun olacaktır. Şimdiden popüler oldunuz bile!"},{"a":"atlab_aang","t":"Bu cömert teklifinizden dolayı çok teşekkürler ama bunu kabul edemem."},{"a":"atlab_aang","t":"Biz konuşurken bile Ateş Ulusu'nun Kralı Ozai bir sonraki hamlesini planlıyor."},{"a":"atlab_aang","t":"Sozin Kuyruklu Yıldızı gökyüzünü tekrar aydınlattığında Ateş Ulusu benim dünyamı ele geçirecek..."},{"a":"atlab_aang","t":"Toprak Krallığı, Su Kabileleri... Hepsi Hava Gezginleri'nin kötü kaderini paylaşacak."},{"a":"atlab_aang","t":"Avatar olarak onu durdurabilecek tek kişi benim ama ben de hazır değilim."},{"a":"elderowen","t":"Bir çocuk için ne büyük bir yük..."},{"a":"elderowen","t":"Ne olursa olsun, şehrimizin seni desteklediğini bil."},{"a":"atlab_aang","t":"Teşekkür ederim. Bizim için şimdiden çok şey yaptınız!"},{"a":"atlab_aang","t":"Tüm bu işler bittiğinde kesinlikle tekrar geleceğiz!"}]},{"id":"atlab_aang_04","i":4,"title":"Sozin'in Kehaneti","req":"atlab_aang:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Şans Jetonları"},"side":false,"lines":[{"a":"mana","t":"Sonunda yolumuz kesişti Avatar."},{"a":"atlab_aang","t":"Sen de kimsin? Beni nereden tanıyorsun?"},{"a":"mana","t":"Avatar'ın varlığı, Üçüncü Gözü olanlar için ışıltılı bir fener gibidir."},{"a":"atlab_aang","t":"Ah, falcılık yani. Almayayım!"},{"a":"mana","t":"Birden çok kişi var içinde, ama henüz bir bütünlük yok derinde..."},{"a":"mana","t":"Önünde acımasız bir savaş var Ateş Kralı ile."},{"a":"atlab_aang","t":"Ateş Ulusu'nun Kralı Ozai... Onu tanıyor musun?"},{"a":"mana","t":"Kuyruklu Yıldızın altında toprak paramparça olacak ve tarlalar küle dönecek!"},{"a":"atlab_aang","t":"Bunu zaten biliyorum! Peki ne yapmalıyım?"},{"a":"mana","t":"Kaderin akışı değiştirilemez."},{"a":"atlab_aang","t":"..."},{"a":"mana","t":"Ama yine de cesur olanlar kaderin ağlarına asılıp yönünü değiştirebilir."},{"a":"mana","t":"Beklenmedik bir müttefik ve kırılgan bir ittifak başarının anahtarı olabilir."},{"a":"atlab_aang","t":"Teşekkür ederim falcı... Bunu düşüneceğim."},{"a":"mana","t":"..."},{"a":"mana","t":"Cesur ol Avatar. Kendine karşı dürüst olursan tüm zorlukların üstesinden gelebilirsin."}]}]},{"id":"argon","name":"Argon","chapters":[{"id":"argon_01","i":1,"title":"Kral'ın Gölgesi","req":"argon:1","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"argon","t":"İşte Belalı'yı kılıcımla böyle dilimledim! Bum!"},{"a":"elderowen","t":"Ha ha ha! Ne hikâye ama Argon!"},{"a":"elderowen","t":"Ah, gençlik ateşi..."},{"a":"elderowen","t":"Bu ihtiyara sabah yürüyüşünde eşlik etmen çok nazik bir davranış."},{"a":"argon","t":"Lafı bile olmaz! Bir gün şövalye olacaksam ihtiyacı olanlara yardım etmem gerek!"},{"a":"elderowen","t":"Aynı baban gibi desene! Eminim çok başarılı bir şövalye olacaksın evladım."},{"a":"elderowen","t":"Belki bir gün kraliyet muhafızı olarak bile görev alabilirsin!"},{"a":"elderowen","t":"İyi insan lafının üstüne gelirmiş! Kendisi pazar yerinde işte! Gidip sorsana!"},{"a":"argon","t":"EKSELANSLARI! Bir şövalye olarak size hizmetimi sunmak istiyorum!"},{"a":"king","t":"Bu da ne demek oluyor? Sia, şu avam parçasıyla ilgileniver!"},{"a":"sia","t":"Derhal majesteleri."},{"a":"sia","t":"Ee, genç adam? Ne istiyordun?"},{"a":"argon","t":"Vay! Ben, şey..."},{"a":"argon","t":"Ben bir şövalyeyim! Argon olmak istiyorum!"},{"a":"argon","t":"Ne? Dur bir saniye..."},{"a":"sia","t":"Yürekli çocuksun!"},{"a":"sia","t":"O kadar istekliysen gelecek hafta kalenin bahçesinde beni bul."},{"a":"sia","t":"O zamana kadar da sıkı talim yap! Kralın şövalyelerinin arasında miskin birini istemem..."}]},{"id":"argon_02","i":2,"title":"Sıkı Eğitim","req":"argon:2","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"Argon, ne yapıyorsun burada?"},{"a":"argon","t":"Sıkı çalışıyorum! Nihayet Kralın şövalyelerinden biri olma şansı elde ettim!"},{"a":"lilu","t":"Kralın mı, yoksa gizemli danışmanı Sia'nın mı?"},{"a":"argon","t":"Adı Sia mıymış? Çok da güzel ayrıca!"},{"a":"lilu","t":"..."},{"a":"argon","t":"Yok! Öyle demek istemedim! Önemli olan tek kişi Kral!"},{"a":"argon","t":"Bir şövalye olmam gerek! Gerisinin önemi yok!"},{"a":"lilu","t":"Doğru... Gel, yaralarını iyileştireyim."},{"a":"argon","t":"Teşekkü-aman! Bu büyü acıtıyormuş!"}]},{"id":"argon_03","i":3,"title":"Madalyonun İki Yüzü","req":"argon:3","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"argon","t":"Pekâlâ! Sia her an gelebilir!"},{"a":"argon","t":"Sonunda aldığım eğitim işe yaradı, hazırım!"},{"a":"argon","t":"Ancak hâlâ çok gerginim..."},{"a":"argon","t":"Hey! Merhaba! Sen, çalıların oradaki!"},{"a":"yami","t":"..."},{"a":"argon","t":"Sen de mi şövalye olmak için geldin?"},{"a":"argon","t":"Sia yakında burada olur! Saklanmana gerek yok, çok nazik biridir!"},{"a":"yami","t":"Sia!"},{"a":"yami","t":"Gitmem gerek. Görüşürüz."},{"a":"argon","t":"Dur, bekle!"},{"a":"argon","t":"Vay! Sis bombası mı o?"},{"a":"argon","t":"Ne tuhaf bir kızdı"},{"a":"sia","t":"Kiminle konuşuyorsun genç adam?"},{"a":"argon","t":"A, Sia! Sadece buradan geçen utangaç biri! Önemli bir şey değil!"},{"a":"sia","t":"Peki. Öyle olsun... Görünüşe göre kararından dönmemişsin."},{"a":"sia","t":"Kral'ın şövalyelerinden biri olarak hayatını riske atmaya hazır mısın?"},{"a":"argon","t":"Hay hay! Yani tabii ki! Babam benimle gurur duyacak!"},{"a":"sia","t":"Güzel. İlk görevin olarak, senin için elimde ne varmış bakalım..."}]},{"id":"argon_04","i":4,"title":"Elde Var Sıfır","req":"yami:4","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"argon","t":"..."},{"a":"sia","t":"Şaka yapıyor olmalısın!"},{"a":"sia","t":"Suikastçıyı köşeye sıkıştırdın... Ancak onu durdurmayı beceremedin."},{"a":"sia","t":"Sadece o da değil; sırf iyi birisi olduğuna inandın diye onun gitmesine izin verdin demek!"},{"a":"argon","t":"..."},{"a":"sia","t":"Bu nasıl bir saçmalık?"},{"a":"sia","t":"O suikastçının Kralımızı, yani korumaya ant içtiğin adamı öldürmeye çalıştığının farkındasındır umarım?"},{"a":"sia","t":"Bu durum, o kuş kadar aklının idrak edebileceğinden çok daha büyük bir tehlike arz ediyor."},{"a":"sia","t":"Öff... Sanırım şövalyelerinin akıbeti hakkında son sözü söylemek Krala kalmış."},{"a":"sia","t":"Yine de benden senin adına methiyeler düzmemi bekleme. Çekilebilirsin."},{"a":"argon","t":"..."},{"a":"argon","t":"Of..."},{"a":"argon","t":"Çok üzgünüm baba."}]},{"id":"argon_a","i":4,"title":"Titan Kulesi","req":"argon:4","reward":{"k":"tokens","id":"tokens","q":3,"n":"Şans Jetonları"},"side":true,"lines":[{"a":"elderowen","t":"Titan Kulesi demek?"},{"a":"lilu","t":"Lütfen bize her şeyi anlat!"},{"a":"argon","t":"Bu konudan bahseden bazı Kahramanlar olduğunu duymuştum ama kuleyi daha önce kimse görmemiş..."},{"a":"elderowen","t":"Titan Kulesi aslında efsanevi bir yer. Gerçekten var olup olmadığını kimse bilmiyor."},{"a":"elderowen","t":"Hikâyelere göre, birden ortaya çıkarak en yüce Kahramanlara katlarını tırmanmaları için meydan okurmuş..."},{"a":"elderowen","t":"Aniden ortadan kaybolmadan önce de onu görmüş olabilecek herkesin hafızasını silermiş."},{"a":"argon","t":"Ha-Hafızasını silmek mi?"},{"a":"lilu","t":"Bu tuhaf... O zaman efsane nereden geliyor?"},{"a":"argon","t":"Haklısın! Bazı kişilerin olanları hatırlıyor olması gerekir!"},{"a":"elderowen","t":"Söylenene göre Titan mücadelesinin üstesinden gelebilenler Kule tarafından özel muamele görürmüş."},{"a":"elderowen","t":"Bu Kahramanlar yaşadıkları deneyimle değişmiş ve hafızaları silinmemiş olarak dönerlermiş..."},{"a":"elderowen","t":"Daha doğrusu, onların bir parçaları Kulede ve Kulenin bir parçası da onlarda kalırmış."},{"a":"elderowen","t":"Bugünlük bu kadar hikâye yeter. Bu yaşlı adamın hikâyelerini dinlediğin için teşekkürler."},{"a":"lilu","t":"Vay canına! Acaba kule gerçekten var mı?"},{"a":"argon","t":"Evet! Böylesi bir zindanı keşfetmeyi çok isterim!"},{"a":"lilu","t":"Ama bana tuhaf gelen bir şey var... İhtiyar Owen tüm bunları nereden biliyor?"},{"a":"argon","t":"..."}]},{"id":"argon_05","i":5,"title":"Maceracı Şövalye","req":"argon:5","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"argon","t":"İç çeker..."},{"a":"steel","t":"Argon, yüzünü gören cennetlik! Nasılsın bakalım bugün?"},{"a":"argon","t":"Ah, merhaba Brohm... Bana uygun bir işin var mı?"},{"a":"steel","t":"Şimdilik yok Şövalye hazretleri! Canını sıkan nedir?"},{"a":"argon","t":"Artık bana yalnızca Argon diyebilirsin. Unvanım elimden alındı."},{"a":"steel","t":"Ah, büyük talihsizlik..."},{"a":"steel","t":"Ne olursa olsun olumlu şeyler düşün! Bunu da atlatacaksın!"},{"a":"steel","t":"Şansının çok yakında döneceğine eminim!"},{"a":"argon","t":"Haklısın... Teşekkürler Brohm."},{"a":"argon","t":"İşler yoluna girene dek şehir merkezinde olacağım."},{"a":"argon","t":"İç çeker..."}]},{"id":"argon_b","i":5,"title":"Biz Titan mıyız?","req":"argon:5","reward":{"k":"tokens","id":"tokens","q":3,"n":"Şans Jetonları"},"side":true,"lines":[{"a":"lilu","t":"Günaydın... Argon..."},{"a":"argon","t":"(Esneyerek...) Sana da."},{"a":"lilu","t":"Sen de hissediyorsun, değil mi?"},{"a":"argon","t":"Evet, çok yorgunum! Tüm gece görev yapmış gibiyim!"},{"a":"lilu","t":"Bak, kalkanının da kenarı parçalanmış!"},{"a":"argon","t":"Ha? Haklısın! Dün parıl parıl parladığına yemin edebilirim..."},{"a":"lilu","t":"Argon... Sence?"},{"a":"polonia","t":"Rast gele! Siz acemi denizcilerden biri, birkaç <c1>Ezici Gücün Tekmeliği</c1> karşılığında çalışır mı acaba?"},{"a":"lilu","t":"Hayır... Özellikle de 20 tanesi için hiç değil! Bütün bunları nereden buldun?"},{"a":"polonia","t":"Hah! Bunu sorman komik. Hiçbir fikrim yok."},{"a":"polonia","t":"Sanırım uykumda yağma yapıyorum. Korsan ruhum harekete geçiyor, rrr."},{"a":"lilu","t":"Bu tuhaf korsan kadın da öyle..."},{"a":"lilu","t":"Yoksa hepimiz Kuleye meydan okuduk da hafızamız mı silindi?"},{"a":"argon","t":"O zaman yeterince güçlü değiliz demektir..."},{"a":"argon","t":"Gelecek sefere daha sıkı çalışacağım! İzle ve gör!"}]},{"id":"argon_06","i":6,"title":"İkinci Işık","req":"argon:6","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"sia","t":"Yani, suikastçınız şu... \"Şövalyenin\" insafına kalmıştı..."},{"a":"sia","t":"Ama şövalye onun iyi biri olduğuna inandı ve gitmesine izin verdi demek!"},{"a":"king","t":"Büyüleyici bir hikâye! Bu yeni şövalye yetenekli biri gibi duruyor!"},{"a":"sia","t":"Saygısızlık etmek istemem ama, Kralım..."},{"a":"sia","t":"Bu adam yalnızca altıncı hissine güvenerek size suikast düzenlemeye yeltenen birini serbest bıraktı."},{"a":"king","t":"Tam bir <c1>Paladin</c1> alâmeti, sence de öyle değil mi?"},{"a":"sia","t":"Anlamadım?"},{"a":"king","t":"Düşmanın senin merhametine kaldığında bile salt mücadelenin ve çatışmanın ötesini görebilmek..."},{"a":"king","t":"Sonra da kefaretinden şüphe bile etmeden, kendi unvanını tehlikeye atma pasına gitmesine izin verebilmek."},{"a":"king","t":"İşte bu muazzam bir gözü karalık ve hayırseverliktir!"},{"a":"sia","t":"Kabul etmeliyim ki hiç bu açıdan düşünmemiştim Kralım."},{"a":"sia","t":"Yine de Krallıkta on yıllardır gelecek vadeden bir Paladin yetişmiyor..."},{"a":"sia","t":"Meseleyi görüşmek üzere şövalye konseyini toplayayım mı?"},{"a":"king","t":"Saçmalık! Bu formaliteleri kendim halledeceğim."},{"a":"sia","t":"Nasıl arzu ederseniz Kralım. Refakatçinizi hemen hazır edeceğim."},{"a":"king","t":"Gerek yok. Fare misali fark edilmeden gidip gelirim!"}]},{"id":"argon_07","i":7,"title":"Kral Tebdili Kıyafet","req":"argon:7","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"king","t":"Yol verin köylüler! Sıradan bir emekçi geçiyor!"},{"a":"tavern","t":"Ah Kral Reinhold! Sizi bir süredir görmemiştik. Sizin için bir fıçı Ambrosia açayım mı?"},{"a":"king","t":"Şşt! Bugün kılık değiştirdim! Beni tanımamış gibi yap!"},{"a":"tavern","t":"Evet, elbette! Ne kadar da aptalım!"},{"a":"king","t":"Hey sen! Tezgâhın ardında saklanan!"},{"a":"argon","t":"Ah! Aa, affedersiniz Ekselansları. Yolunuzdan çekileyim..."},{"a":"king","t":"Saçmalık! Paladin olacak kişi, göz alıcı şahsımın yanında oturmaya fazlasıyla layıktır!"},{"a":"argon","t":"Yanınızda mı? Paladin mi?"},{"a":"king","t":"Çok doğru! Sonsuz bilgeliğim sağ olsun içinde muhteşem bir potansiyel olduğunu sezdim!"},{"a":"king","t":"Olağan dışı yöntemlerine rağmen... Saf bir kalbin var ve adalet duygun ise... Takdire şayan!"},{"a":"king","t":"Bu yüzden krallık sana Paladinlik İmtihanına girme fırsatı lütfediyor!"},{"a":"argon","t":"Paladinlik İmtihanı mı?.. Vay canına!"},{"a":"argon","t":"Bu imtihanları biliyorum! Her biri daha önce yapılmamış ve bizzat Paladin tarafından seçilen görevler..."},{"a":"argon","t":"Tehlikeli bir görev olmalı, mesela bir ejderha öldürmek... Veya tehlikeli bir antik eseri yok etmek gibi..."},{"a":"king","t":"Aslında! Krallık uğruna yapılan yeterince cesur ve özverili herhangi bir görev iş görür!"},{"a":"argon","t":"Anladım! Teşekkür ederim Ekselansları! Pişman olmayacaksınız!"},{"a":"king","t":"Tabii ki olmayacağım, ben her zaman haklıyım!"},{"a":"king","t":"Şimdi, madem ki kılık değiştirdim..."},{"a":"king","t":"Hey sen! Yaşlı adam! Bana biraz kart oyunu öğret bakalım!"},{"a":"master","t":"Kart oyunu, ha? Yaşlı Theodore yalnızca yüksek miktarlar için oynar..."}]},{"id":"argon_08","i":8,"title":"Yeni Baştan","req":"argon:8","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"Argon! Bu acele de ne?"},{"a":"argon","t":"Lilu, sonunda Paladin olacağım!"},{"a":"lilu","t":"Paladin mi? Bu-Bu harika Argon! Ama nasıl?"},{"a":"argon","t":"Kral bir imtihandan geçmem gerektiğini söyledi! Paladin unvanına gerçekten layık olmanın tek yolu bu."},{"a":"lilu","t":"İmtihan mı? Ne yapacağını biliyor musun?"},{"a":"argon","t":"..."},{"a":"argon","t":"Yok, hayır! Hiçbir fikrim yok!"},{"a":"argon","t":"Destansı ve görkemli boyutlarda bir şey olmalı..."},{"a":"lilu","t":"Ama Argon sen zaten görkemlisin! Diyarın dört bir yanında canavarları yendin..."},{"a":"argon","t":"Elbette ama daha büyük bir şey olmalı..."},{"a":"argon","t":"Kasvetli Tepe'de tüylü iblisler olduğunu duymuştum, belki de onlardır..."},{"a":"lilu","t":"Her ne olursa olsun buna hazır olduğuna eminim!"},{"a":"argon","t":"Teşekkürler Lilu... Bir şövalye değilken bile bana inanmaya devam ettin..."},{"a":"lilu","t":"Ah! Ne demek!"},{"a":"lilu","t":"Her neyse! Görevinde yardıma ihtiyaç duyacaksın! Sana birkaç iyileştirme parşömeni hazırlayayım!"},{"a":"argon","t":"Harika! İşe koyulalım!"}]},{"id":"argon_09","i":9,"title":"Kasvetli Çatışma (Argon)","req":"argon:9","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"argon","t":"Öf... Burası berbat bir yer!"},{"a":"argon","t":"O kadar yolu tırmandım ama ortalıkta bir tane bile Harpia yok... Suikastçılar tarafından pusuya bile düşürüldüm!"},{"a":"argon","t":"...Biraz şu Ninja kızı andırıyorlardı sanki, değil mi?"},{"a":"argon","t":"İyi ki Lilu bana bu şifalı parşömenleri vermiş, oh be!"},{"a":"argon","t":"Galiba burada biraz soluklanacağım."},{"a":"argon","t":"...Ha?"},{"a":"yami","t":"Yine mi sen?"},{"a":"argon","t":"K-Kralın suikastçısı!"},{"a":"argon","t":"Kader dedikleri bu olsa gerek. Bir Harpia'dan bile daha büyük bir ödül!"},{"a":"yami","t":"Göster kendini. Seni şuracıkta öldürürüm."}]},{"id":"argon_10a","i":10,"title":"Zafer Dönüşü","req":"yami:9","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"argon","t":"Kral Reinhold! Görev tamamlandı!"},{"a":"king","t":"Harika! Hangi iğrenç canavarı katlettin?"},{"a":"argon","t":"Hımm... Şu mesele."},{"a":"yami","t":"...Selam."},{"a":"king","t":"B-bu-bu da ne demek oluyor şimdi!?"},{"a":"sia","t":"Muhafızlar! İkisini de yakalayın!"},{"a":"argon","t":"Hey! Bekle! Kız yeni bir sayfa açtı!"},{"a":"king","t":"Ö-öyle mi gerçekten?"},{"a":"yami","t":"Şey... Özür dilemeye geldim."},{"a":"sia","t":"Kralım, kesinlikle inanmayacaksınız..."},{"a":"argon","t":"Ona kefil olabilirim! Şövalye şerefim üzerine!"},{"a":"king","t":"Pekâla! Mazeretini dinleyeceğim!"},{"a":"sia","t":"Öf... Bunun olacağından korkuyordum."},{"a":"sia","t":"Muhafızlar! Destek güçlerini toplayın ve her adımını takip edin!"},{"a":"sia","t":"Argon, biz bu... Davetsiz misafirle görüşürken dışarıda bekle lütfen."},{"a":"argon","t":"Derhâl!"},{"a":"argon","t":"(...Büyük bir hata mı yaptım?)"}]},{"id":"argon_10b","i":11,"title":"Kurtarıcı","req":"yami:10","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"sia","t":"Ahh... Bu baş ağrısını bugün hiç çekemem."},{"a":"argon","t":"Leydi Sia! Nasıl geçti?"},{"a":"sia","t":"...Her şeye rağmen, Kral Reinhold sözde suikastçısını affetmeye hazır."},{"a":"sia","t":"O kadar güvenilir olmadığım hâlde benimle Azuman Birliği'ne dair önemli bilgileri paylaştı."},{"a":"argon","t":"O hâlde bu demek oluyor ki!.."},{"a":"sia","t":"Evet, teslim olmasını ve özrünü kabul edeceğiz."},{"a":"sia","t":"Şu anda açlık nedeniyle tedavi görüyor ve tamamen iyileşmesi gerekli."},{"a":"sia","t":"Sana gelince Paladin Argon..."},{"a":"argon","t":"P-paladin!"},{"a":"sia","t":"Tamam, tehdit oluşturanı ortadan kaldırmak önemli, ama bunu krallığın ezeli düşmanını kurtarmak için yapmak..."},{"a":"sia","t":"Görünüşe göre Kral Reinhold senin hakkında haklıymış."},{"a":"sia","t":"Şimdi git ve kutla Paladin. Eminim çok yakında fazlasıyla meşgul olacaksın!"},{"a":"argon","t":"Öyle yapacağım! Teşekkür ederim!"},{"a":"argon","t":"Baba... Umarım gurur duyuyorsundur."}]},{"id":"argon_epilogue","i":12,"title":"Son Söz","req":"argon:10","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"P-paladin mi? Başardın Argon!"},{"a":"argon","t":"Bir an gerçekten orada her şeyi mahvettiğimi sandım..."},{"a":"argon","t":"Ama babam haklıydı. Tek yapmam gereken kalbimin sesine kulak vermek!"},{"a":"lilu","t":"Şey... Peki bu, denizaşırı bir sefere gönderileceğin anlamına mı geliyor?"},{"a":"argon","t":"Daha değil. Leydi Sia, Kahramanlara Paladin olmayı öğretebileceğimi umuyor."},{"a":"lilu","t":"Oh! İçim rahatladı! Gerçi seni bir öğretmen olarak hayal etmekte zorlanıyorum."},{"a":"lilu","t":"Çok önemli Paladin görevleriyle meşgul olmayacak mısın?"},{"a":"argon","t":"Elimden geleni yapacağım! Krallık bana güveniyor!"},{"a":"tavern","t":"Merhaba, asil Paladin!"},{"a":"tavern","t":"Brohm bana biraz daha eritme eldiveni aradığını söyledi!"},{"a":"argon","t":"Tabii! Derhâl!"},{"a":"lilu","t":"Bazı şeyler hiç değişmiyor, öyle değil mi?"},{"a":"tavern","t":"Bizim Argon'un öyle olmadığı kesin."}]},{"id":"argon_c","i":13,"title":"Taşa Kazınmış","req":"malady:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Şans Jetonları"},"side":true,"lines":[{"a":"argon_stone","t":"..."},{"a":"lilu","t":"İksir... işe yaramadı değil mi?"},{"a":"lilu","t":"Of... O kadar da uğraşmıştık hâlbuki..."},{"a":"lilu","t":"Özür dilerim Argon. Beceremedim... Umarım çok rahatsız değilsindir orada."},{"a":"elderowen","t":"Hımm... Gerçekten de üzücü bir haber bu."},{"a":"lilu","t":"Daha seçeneklerimiz tükenmedi ama..."},{"a":"lilu","t":"O yanımızda değilken çok zor oluyor."},{"a":"elderowen","t":"O yokken şehir gerçekten de çok boş geliyor, değil mi?"},{"a":"lilu","t":"Sanki arkadaşlarının olmadığı bir doğum günü partisi gibi..."},{"a":"lilu","t":"... Neyse, böyle üzülmek onu geri getirmeyecek. İşime dönsem iyi olur."},{"a":"lilu","t":"Donovan'a sorarsak bize yardım eder belki!"},{"a":"lilu","t":"Biraz pahalıya patlar ama paralarımızı birleştiririz artık!"},{"a":"lilu","t":"Bir yere gidemiyorsun zaten, farkındayım ama... azıcık dişini sık! Seni kurtaracağız!"},{"a":"argon_stone","t":"..."}]}]},{"id":"ashley","name":"Ashley","chapters":[{"id":"ashley_01","i":1,"title":"Tuhaf Samuray","req":"ashley:1","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"argon","t":"Gerçek bir Samuray! Sabırsızlanıyorum!"},{"a":"argon","t":"Leydi Samuray! Ben Argon, eğitimi devam eden bir şövalyeyim."},{"a":"ashley","t":"Selam sana. Ben Ashley. Ne var ne yok?"},{"a":"argon","t":"Se-selam mı?"},{"a":"tavern","t":"Ayaklarını masadan indir lütfen!"},{"a":"ashley","t":"Öff peki."},{"a":"ashley","t":"Eee? Neye ihtiyacın var?"},{"a":"argon","t":"Samuraylar genelde daha tertipli, düzenli değil midir?"},{"a":"ashley","t":"Ha? Evet, memleketimdekiler bu mevzuda oldukça eski kafalıydı."},{"a":"ashley","t":"Artık özgürüm. Sadece bir Ronin'im. Lordu olmayan bir Samurayım."},{"a":"argon","t":"Anladım. Peki!"},{"a":"argon","t":"Perili Şato'da Lilu'yle birlikte bir göreve gitmem gerekiyordu ama..."},{"a":"argon","t":"Eğitim Salonu'nda bir sorun çıktı! Yerime bakabilir misin?"},{"a":"ashley","t":"Elbette. Ama bana borçlandın, şövalye çocuk."}]},{"id":"ashley_02","i":2,"title":"Silahlı ve Hazır","req":"ashley:2","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"ashley","t":"Sen Lilu'sun, değil mi?"},{"a":"lilu","t":"Evet! Tanıştığıma memnun oldum!"},{"a":"ashley","t":"Tamam öyleyse, işe koyulalım."},{"a":"lilu","t":"Dur biraz! Bekle!"},{"a":"lilu","t":"Daha hazırlık yapmadık! İksirler, erzaklar ve..."},{"a":"ashley","t":"Salla gitsin, hiçbirine ihtiyacımız yok."},{"a":"ashley","t":"Yaşarız ya da ölürüz. Bu işin ortası yok."},{"a":"lilu","t":"Bu... Olamaz! Çok sorumsuzca!"},{"a":"ashley","t":"Ben gidiyorum. Bu taraftan, değil mi?"},{"a":"lilu","t":"Hayır! Orası Uluyan Orman'a çıkar."},{"a":"argon","t":"Hımm... Bol şans!"}]},{"id":"ashley_03","i":3,"title":"Yaşamın Kıyısında","req":"ashley:3","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"ashley","t":"Siz canavarların elinden gelenin en iyisi bu mu? HADİ BAKALIM!"},{"a":"lilu","t":"Ashley! Ne olur yavaşla! Yeterince hızlı iyileşemiyorum!"},{"a":"ashley","t":"Bu... Bu... HİÇBİR ŞEY!"},{"a":"ashley","t":"Vay be... Güzel hurda, değil mi?"},{"a":"lilu","t":"Dalga mı geçiyorsun? Az kalsın ölüyordun!"},{"a":"lilu","t":"Şüphesiz ki böyle davrandığın için kolunu kaybetmişsin!"},{"a":"ashley","t":"Oy. Bu kez farklıydı."},{"a":"ashley","t":"Bu hatayı... Tekrarlamayacağım."},{"a":"lilu","t":"Bu şifa için ağrı kesici kullanmıyorum."},{"a":"lilu","t":"Bu senin hatan. Kendine gel."},{"a":"ashley","t":"Haha... hah... Dayanabilirim..."},{"a":"ashley","t":"Off! Ay ay ay..."}]},{"id":"ashley_a","i":4,"title":"Büyülü Hayvan Hissiyatı","req":"ashley:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Şans Jetonları"},"side":true,"lines":[{"a":"ashley","t":"Selam. Etraftaki tüm bu küçük canavarlar da neyin nesi?"},{"a":"elven","t":"Bunlar benim sevgili büyülü hayvanlarım. Hoş geldiniz."},{"a":"elven","t":"Değerli Şampiyonlar gelip içlerinden birini sadık yoldaşları olarak sahiplenebilir."},{"a":"ashley","t":"Oh. Evcil hayvanlar, öyle mi? Anladım."},{"a":"ashley","t":"Tamam. Sen, yeşilli. Sana <c1>Kurnaz</c1> diyeceğim. Benimle gel."},{"a":"ashley","t":"Sen şirinsin, <c1>Kartopu</c1>. Seni yanımda taşıyacağım."},{"a":"elven","t":"Ah... Korkarım ki..."},{"a":"ashley","t":"Iyy, ne kadar çirkin bir kuş!"},{"a":"ashley","t":"Sana <c1>Serçe</c1> diyeceğim. Sen de gelebilirsin."},{"a":"elven","t":"Anladım. Hepinize iyi eğlenceler."}]},{"id":"ashley_04","i":5,"title":"Görev Başarıyla Başarısız Oldu","req":"ashley:4","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"argon","t":"Dünkü görev nasıl gitti? Lilu oldukça üzgündü..."},{"a":"ashley","t":"Tek parça halinde döndüm. Ne yazık ki."},{"a":"argon","t":"Nasıl yani? Bu iyi değil mi?"},{"a":"king","t":"Merhabalar halkım! İhtişamıma tanık olmanıza izin veriyorum!"},{"a":"ashley","t":"Lordum Kralım efendim! Ben Ashley, göreve hazırım!"},{"a":"king","t":"İşte asker dediğin böyle olmalı! Aferin, sıkı çalışmaya devam et!"},{"a":"ashley","t":"Tamam efendim! Teşekkürler efendim!"},{"a":"tavern","t":"Üzgünüm Reinhold, siparişin daha gelmedi."},{"a":"king","t":"Pekâlâ! Yarın tekrar geleceğim!"},{"a":"argon","t":"O da neydi?"},{"a":"ashley","t":"O, şey. Eskiden bir lorda hizmet ederdim. Eski alışkanlıklardan."},{"a":"argon","t":"Harika! Biraz anlatsana!"},{"a":"ashley","t":"Hayır."}]},{"id":"ashley_05","i":6,"title":"Dönüm Hikayesi","req":"ashley:5","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"ashley","t":"Sonra da dedim ki..."},{"a":"ashley","t":"\"Donanmış ve hazır mı? Hazır olduğumu söyleyebiliriz!\""},{"a":"argon","t":"Hahaha!"},{"a":"argon","t":"Ama Ashley, daha önce bahsettiğin lord..."},{"a":"ashley","t":"Offfff... Gerçekten peşini bırakmayacaksın değil mi? Peki."},{"a":"ashley","t":"Samurayların bir lordu vardır, bir Daimyo. Ona hizmet ederiz ve onu canımız pahasına koruruz."},{"a":"argon","t":"Ne kadar da onurlu!"},{"a":"ashley","t":"Sıradan bir gün, her zamanki gibi öğle yemeğini yerken..."},{"a":"ashley","t":"Bir anda bom. Ninjalar. Odanın her yerinde. Hepsi... Hepsi efendimin kellesinin peşinde."},{"a":"ashley","t":"Şiddetli bir savaş oldu. İlk defa yaşanmıyordu. Ama..."},{"a":"ashley","t":"Feci bir yara aldım. Kolumu kaybettim."},{"a":"ashley","t":"Sonrasında ben... Ben kaçtım. Onu ölümüne terk ettim."},{"a":"argon","t":"Ashley..."},{"a":"ashley","t":"AAAAAAAAAAA!!! Orada ölmeliydim!"},{"a":"ashley","t":"Doldur be Naya, boş kalmasın kadehim."},{"a":"tavern","t":"Bugün yeterince içtin Ashley."},{"a":"ashley","t":"Peki. Sorun değil. Yeterince içtim."},{"a":"ashley","t":"Tamam o halde. Argon, git Lilu'ya Ashley'nin çok tehlikeli bir göreve çıkacağını söyle."},{"a":"argon","t":"Ne? Hemen şimdi mi?"},{"a":"ashley","t":"Ne sandın? Gideceğim yer... Aurora Mağaraları diyelim. Acele et!"}]},{"id":"ashley_06","i":7,"title":"Göze Ben","req":"ashley:6","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"ashley","t":"Ninja kız. Sen bizi mi dinliyordun?"},{"a":"yami","t":"Birazını. Dışarı çıkmaya ne dersin?"},{"a":"ashley","t":"Hah! Dövüşecek günümde değilim."},{"a":"yami","t":"Lord Kusunoki'ye bunu benim klanım yaptı. Ben önemsiz biriyim ama yine de özür..."},{"a":"ashley","t":"Teşekkürler, ama buna gerek yok. Nefret ettiğim şey sen değilsin, benim."},{"a":"yami","t":"Anlıyorum... Hatta tahmin ettiğinden bile iyi anlıyorum."},{"a":"yami","t":"Ama onurun yerle bir olmuşken bile uğruna yaşaman gereken birçok şey var."},{"a":"yami","t":"Burada arkadaşların var. Ailen sayılacak bir şehir. Önemsediğin evcil hayvanların."},{"a":"yami","t":"Tüm bunlar yeterli değilse sana onurlu bir ölümüne dövüş teklif ediyorum."},{"a":"ashley","t":"Bir Ninjadan bedava bir suikast mi? Beni şımartıyorsun."},{"a":"ashley","t":"Teşekkürler ama gerek yok. Yine de bu teklifini düşüneceğim."},{"a":"yami","t":"Nasıl istersen."}]},{"id":"ashley_07","i":8,"title":"Son Bir Dövüş","req":"ashley:7","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"Uff... Uff.. Ashley burada değil..."},{"a":"lilu","t":"Yine mi kayboldu?"},{"a":"lilu","t":"Hayır... Bekle. Kandırıldım mı?"},{"a":"ashley","t":"Külgölü Volkanı'na gidiyordum..."},{"a":"ashley","t":"Neyse, fena değil."},{"a":"ashley","t":"Tamamdııııır! Uyanın bakalım şapşallar! Ashley geldi!"},{"a":"monster_Grotto_Mob","t":"İnsan... Sarhoş mu?"},{"a":"ashley","t":"İşgüzar şifacı yok bugün, yalnızca ben ve ölme isteğim! Ölene kadar da durmayacağım!"},{"a":"ashley","t":"Ne olursa olsun kazanan benim! Hadi bakalım, ilk kim başlıyor?"},{"a":"monster_Ruins_Mob","t":"Aaah! Gönder gelsin!"},{"a":"ashley","t":"İşte böyle!"}]},{"id":"ashley_08","i":9,"title":"Deus Ex Asthea","req":"ashley:8","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"priest","t":"Aman Tanrıçam... Doğru yerde miyiz?"},{"a":"priest","t":"Amanın, ortalık kan gölüne dönmüş."},{"a":"monster_Grotto_Mob","t":"Hee hee hee."},{"a":"priest","t":"Üzgünüm canavarlar. İzninizle dostumu alacağım."},{"a":"monster_Grotto_Mob","t":"Hayır! HAYIR! Bizi mahvetti! O Samuray nalları çoktan dikti!"},{"a":"priest","t":"Hâlâ yaşıyor. Bildiğim Ashley bundan daha sağlamdır."},{"a":"monster_Ruins_Mob","t":"Ha? O zaman işini bitireyim!"},{"a":"priest","t":"Öyle bir şey yapmayacaksın."},{"a":"monster_Grotto_Mob","t":"Hee hee hah! Ya sen ne yapacaksın? Bizi iyileştirecek misin?"},{"a":"priest","t":"Bana başka seçenek bırakmadın. Tanrıça Asthea seni bağışlasın..."},{"a":"priest","t":"Çünkü ben bağışlamayacağım."}]},{"id":"ashley_09","i":10,"title":"Yatak İstirahati Baskısı","req":"ashley:9","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"ashley","t":"Ah..."},{"a":"priest","t":"Sonunda kendine geldin."},{"a":"ashley","t":"Ha? Lanet olsun... Sen de mi? Beni... nasıl buldun?"},{"a":"priest","t":"Görünüşe göre Tanrıça sana değer veriyor. Beni o yolladı."},{"a":"ashley","t":"Lanet... Hadi ama doktor, bırak da öleyim."},{"a":"priest","t":"Gerçekten dileğin buysa."},{"a":"ashley","t":"Ohh... Sonunda..."},{"a":"ashley","t":"..."},{"a":"ashley","t":"Neden beni İYİLEŞTİRMEYE devam ediyorsun?"},{"a":"priest","t":"Sözlerinin aksine hâlâ yaşamayı diliyorsun."},{"a":"priest","t":"Şifa büyüsü sadece yaşam gücünü hızlandırır. Gerçekten ölmeyi dileseydin seni kurtarmak için elimden bir şey gelmezdi."},{"a":"ashley","t":"Öyle mi?"},{"a":"priest","t":"Şimdilik dinlenmeye bak. Düşüneceğin çok şey var."}]},{"id":"ashley_10","i":11,"title":"Düşünme Zamanı","req":"ashley:10","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"argon","t":"Geri döndün! Lilu seni her yerde arıyordu!"},{"a":"argon","t":"...Sen de biraz hırpalanmış görünüyorsun."},{"a":"ashley","t":"Aldırma, beni yamaladılar. Bir de fırça yedim."},{"a":"argon","t":"Freyja'dan mı? Hayal etmesi güç."},{"a":"ashley","t":"Evet. Düşünmeye başla dedi. Ben de düşünüyorum."},{"a":"tavern","t":"Düşünüyor musun? Bu ilk oldu!"},{"a":"ashley","t":"Bırak şunu."},{"a":"ashley","t":"...bunu söylemek isterdim ama haklısın."},{"a":"ashley","t":"Geçmişe o kadar uzun süre takılı kaldım ki, düşünmeyi hepten unuttum."},{"a":"argon","t":"Neyi düşüneyim?"},{"a":"ashley","t":"Hmm. Bir sürü şey."},{"a":"ashley","t":"Ben fark etmeden, meğer önem verdiğim birçok şey edinmişim."},{"a":"ashley","t":"Şehir.\nHalk.\nTüccar.\nSana da, şövalye evlat."},{"a":"ashley","t":"Ancak birkaç kez ölümle burun buruna gelince fark ettim. Sanırım kafa biraz geç basıyor, heh."},{"a":"argon","t":"Şereflendim, Samuray Hanım!"},{"a":"ashley","t":"Burada hâlâ bir Ronin. Bunun yakın zamanda değişmesini bekleme."},{"a":"yami","t":"..."},{"a":"yami","t":"..."}]},{"id":"ashley_epilogue","i":12,"title":"Son Söz","req":"ashley:11","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"ashley","t":"Hey, Lilu. Başka bir göreve gidiyorum. Gelmek ister misin?"},{"a":"lilu","t":"Hıh! Yine beni yanlış konuma gönder diye mi?"},{"a":"lilu","t":"Ya da gözünü köreltip canavarlara öyle bir saldır ki her yerine yeniden dikiş atmam gereksin diye mi?"},{"a":"ashley","t":"Yok, artık değiştim. Sakin olacağım, bir elim arkamda."},{"a":"lilu","t":"Hımm... Demek öyle."},{"a":"lilu","t":"Bekle biraz..."},{"a":"ashley","t":"Hah hah! Şaka yaptıııım."},{"a":"ashley","t":"Arkamı kollarsan ben de senin arkanı kollarım."},{"a":"lilu","t":"Güzel! Ama bu sefer bana söz ver."},{"a":"lilu","t":"İşler sarpa sararsa... Geri çekileceğiz. SEN DE geri çekileceksin."},{"a":"ashley","t":"Ronin onurum üstüne söz veriyorum. Ne değeri kaldıysa artık."},{"a":"ashley","t":"Döneceğimiz bir evimiz var."}]}]},{"id":"bjorn","name":"Bjorn","chapters":[{"id":"bjorn_01","i":1,"title":"Baba Eve Dönünce","req":"bjorn:1","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"bjorn","t":"Çocuklar! Babanız geldi!"},{"a":"steel","t":"Baba!"},{"a":"wood","t":"Baba..."},{"a":"bjorn","t":"Neden yüzün düştü Gorza?"},{"a":"wood","t":"Aylardır ortada yoksun!"},{"a":"bjorn","t":"Koruculuk böyle bir şey! Evden çok uzaklarda, dağda bayırdayız hep..."},{"a":"wood","t":"Üff. Arada bir uğrasan ölmezsin."},{"a":"bjorn","t":"Keşke ama Külgölü Volkanı çok vakit alıyor!"},{"a":"wood","t":"Volkan mı? Kasvetli Tepeyi incelemeye gittiğini söylemiştin sanki..."},{"a":"bjorn","t":"Öyle mi?"},{"a":"bjorn","t":"Dilim sürçmüştür! Ha ha!"},{"a":"bjorn","t":"Size hatıralık eşyalar getirdim! Gelin, bakın!"},{"a":"steel","t":"Alev Yengeci Pelüşünü unutmadın umarım!"}]},{"id":"bjorn_a","i":1,"title":"Can Yoldaşım Bamham","req":"bjorn:1","reward":{"k":"tokens","id":"tokens","q":3,"n":"Şans Jetonları"},"side":true,"lines":[{"a":"bjorn","t":"Çocuklar benim için Bamham'a biraz göz kulak olur musunuz?"},{"a":"wood","t":"O pis yaban domuzuna mı? Hayatta olmaz. Seninle kalsın."},{"a":"steel","t":"Alınma baba ama... biraz deli gibi."},{"a":"bjorn","t":"Aa, deme öyle! Çok şirindir o!"},{"a":"wood","t":"Baba, ne zaman yere koysan öfkeden gözü dönüyor hayvanın."},{"a":"bjorn","t":"O sadece bir kazaydı. Biraz fazla heyecanlandı sadece."},{"a":"wood","t":"Diğerleri neydi peki?"},{"a":"bjorn","t":"Onlar da... kazaydı tabii. Bamham bebişim kimsenin kılına zarar vermez."},{"a":"wood","t":"Verir, hem de bayıla bayıla verir."},{"a":"wood","t":"Bak baba, şehirdeyken onu yanından ayırmasan iyi olur."},{"a":"steel","t":"En azından herkesin güvenliği için..."},{"a":"bjorn","t":"Peki, peki. Anladık. Sorun yok Bamham, ben seni seviyorum."},{"a":"bjorn","t":"Ho ho ho! Sakin ol Bamham!"}]},{"id":"bjorn_02","i":2,"title":"Bjorn'un Alışveriş Macerası","req":"bjorn:2","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"bjorn","t":"Bu hoş karşılama için herkese teşekkürler! Geri döndüğüme çok mutluyum!"},{"a":"elderowen","t":"Sağ salim döndüğüne biz de çok sevindik. Aylardır ortalarda olmayınca aklımıza en kötüsü gelmişti..."},{"a":"bjorn","t":"Kusuruma bakmayın! Koruculuk böyledir işte! Ha ha!"},{"a":"oils","t":"Seni tanıyorsam, şimdiden yeni keşif gezini planlamaya başlamışsındır!"},{"a":"bjorn","t":"Ha ha! Yakalandım! Hatta yarın sabah şafakta yola çıkıyoruz!"},{"a":"oils","t":"Hiç değişme Bjorn. Sen yokken Brohm ve Gorza bana emanet."},{"a":"oils","t":"Yoldan benim için birkaç tane Parlak Mantar da toplar mısın?"},{"a":"bjorn","t":"Hay hay! Hiç sorun olmaz!"},{"a":"elderowen","t":"Ah ya... Şu sıralar belim çok kötü. Biraz Buz İncisi bulabilirsen belki..."},{"a":"bjorn","t":"İşten bile sayılmaz. Gözümü dört açarım, İhtiyar."},{"a":"engineer","t":"Aa! Bjorn! Sıradaki deneyim için biraz Bakırejder Puluna ihtiyacım var. Mümkünse tabii!"},{"a":"bjorn","t":"Olur, olur. Aklımda!"},{"a":"bjorn","t":"Yanımıza fazladan birkaç çanta daha alsak iyi olur Bamham!"}]},{"id":"bjorn_03","i":3,"title":"Her Parlayan Altındır","req":"bjorn:3","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"bjorn","t":"Kokuyu sen de alıyor musun Bamham?"},{"a":"bjorn","t":"Haklısın, metal. Büyük ihtimalle hurda falandır. Hadi Bam, bul ve getir!"},{"a":"bjorn","t":"Aferin oğluma, bakalım neymiş..."},{"a":"bjorn","t":"Hıh. Ne tuhaf bir cihaz. Buraya yanlışlıkla bırakıldığını hiç sanmıyorum..."},{"a":"bjorn","t":"Bahse varım şu kolu çekince bir şeyler olacak..."},{"a":"bjorn","t":"Hımm... Tam da düşündüğüm gibi."},{"a":"bjorn","t":"Elimde kaldı. Pek bir şey öğrenemedik, değil mi? Ha ha!"},{"a":"bjorn","t":"Yine de bir ipucu yakaladık. Aylardır aranıyorduk ve geçen sefer geçtiğimizde bu şey burada değildi."},{"a":"bjorn","t":"Geri dönüp bu işten anlayan birine danışalım. Ben teknoloji konusunda iyi değilimdir."}]},{"id":"bjorn_04","i":4,"title":"Gizemli Fener","req":"bjorn:4","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"engineer","t":"Ne tuhaf şey! Bunun gibisini hiç görmedim."},{"a":"engineer","t":"Büyü ile bilimi birleştirerek sanki bir tür... fener ya da radar görevi görüyor."},{"a":"engineer","t":"Bulduğunda kırıktı demiştin, değil mi?"},{"a":"bjorn","t":"Evet. Talihsizlik işte. Ha ha!"},{"a":"engineer","t":"Çok yazık olmuş. Kesinlikler bir tür bilgi gönderiyor olması dışında söyleyebileceğim pek bir şey yok."},{"a":"engineer","t":"Baksana, bana birkaç dakika verirsen sana bu... \"Büyülü Fenerlerden\" bulmana yardımcı olacak bir cihaz yapabilirim."},{"a":"bjorn","t":"Harika! Oraya dönmeye hazır mısın Bamham?"},{"a":"bjorn","t":"Bunların ne olduğunu bilmiyoruz ama iyiye işaret olamazlar."},{"a":"bjorn","t":"Bunun ardındaki kişiyi bulmak bizim işimiz!"},{"a":"engineer","t":"İyi şanslar! O tuhaf teknolojik aleti kurcalarken de dikkatli ol!"}]}]},{"id":"donovan","name":"Donovan","chapters":[{"id":"donovan_01","i":1,"title":"Orijinal Tarif","req":"donovan:1","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"herbalist","t":"Maribel İksir Evi'ne hoş geldiniz! Size nasıl yardımcı olabilirim?"},{"a":"donovan","t":"Leydi Maribel değil mi? En son eserinize övgülerimi bizzat sunmak istedim."},{"a":"donovan","t":"Yenilenme İksiri'nin mucidi olarak, değiştirilmiş taslağınız tam anlamıyla dâhiyane!"},{"a":"donovan","t":"Sadece bir tutam Sisli Tepe Tomurcuğu eklemek müthiş bir geliştirme!"},{"a":"herbalist","t":"Durun bir dakika... Yani siz O Donovan mısınız? Olamaz!"},{"a":"herbalist","t":"Yenilenme İksiri taslağı yaklaşık 700 yıl önce icat edildi..."},{"a":"herbalist","t":"Bir elf olarak bile, 150'den bir gün fazla göstermiyorsunuz!"},{"a":"donovan","t":"Çok naziksiniz Leydi Maribel."},{"a":"donovan","t":"Şu kadarını söyleyeyim, taslaklarımın tümü satışa çıkarılmadı..."},{"a":"donovan","t":"Ancak eminim sizin gibi usta bir simyacı bunları öğrenmekte güçlük çekmeyecektir."},{"a":"donovan","t":"O hâlde şu Sisli Tepe Tomurcuğu'ndan biraz görebilir miyim?"}]},{"id":"donovan_02","i":2,"title":"Bolluk Ülkesi","req":"donovan:2","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"donovan","t":"Büyüleyici... Bu taraflarda yetişen sıradan elmalar bile çok lezzetli, tatları mükemmel."},{"a":"donovan","t":"Böyle bir şey nasıl mümkün olabilir?"},{"a":"lilu","t":"Bunu olsa olsa Juniper açıklayabilir!"},{"a":"lilu","t":"Ah, pardon! O ağaçla... Sohbetinizi bölmek istememiştin."},{"a":"donovan","t":"Ah, sadık baykuşunu yanından ayırmayan ve geniş kenarlı bir şapkası olan genç bir kadın..."},{"a":"donovan","t":"Siz Bayan Lilu olmalısınız kuşkusuz."},{"a":"lilu","t":"Evet! Siz de Bay Donovan olmalısınız, görünen o ki tanışma faslını atlayabiliriz!"},{"a":"donovan","t":"Ben de bu şehrin değerli genç öğrencisi hakkında çok şey duydum. Tanıştığımıza memnun oldum."},{"a":"donovan","t":"Şimdi Bayan Lilu. Ne diyordunuz?"},{"a":"lilu","t":"Ah, evet! Juniper her zaman şehrin çevresindeki topraktan nasıl hayat fışkırdığını anlatır."},{"a":"lilu","t":"Dediğine göre, bahçıvanlıktan bu kadar zevk almasının bir nedeni de buymuş."},{"a":"lilu","t":"Neyse işte, Aurora Mağaraları'na doğru gidiyorum ve sizinle tanıştığıma memnun oldum Bay Donovan!"},{"a":"donovan","t":"Tekrar görüşmek üzere."},{"a":"donovan","t":"Hımm... Bu genç hanım sanırım bir işler peşinde."},{"a":"donovan","t":"Kern... Tükenmiş olabilir mi? Bu krallıkta her şey çok daha canlı görünüyor."},{"a":"donovan","t":"Bu bahçıvanı ziyaret etmeliyim. Buradaki malzemeler daha tesirliyse..."},{"a":"donovan","t":"Bundan faydalanmalıyım."}]},{"id":"donovan_03","i":3,"title":"Maskenin Ardındaki","req":"donovan:3","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"Bayan Sia, beni mi çağırmıştınız?"},{"a":"sia","t":"Evet Lilu. Hemen geldiğin için çok teşekkür ederim."},{"a":"sia","t":"Sanırım Donovan'ı zaten tanıyorsun, değil mi?"},{"a":"lilu","t":"Evet, kendisi simyacılar arasında bir efsanedir! Onunla tanıştığıma çok sevindim!"},{"a":"sia","t":"O adama karşı çok dikkatli ol."},{"a":"lilu","t":"Hı, ne? Ama o tam bir beyefendi! Çok bilgili ve..."},{"a":"sia","t":"Dış görünüş yanıltıcı olabilir. O genç yüzün ardında bin yılın birikimine sahip kurnaz bir beyin var."},{"a":"lilu","t":"Bin yıl mı? Bu elfler arasında bile görülmedik bir durum! Yoksa..."},{"a":"sia","t":"Evet. Bazıları onun bir tür ölümsüzlük iksiri keşfettiğine inanıyor."},{"a":"lilu","t":"İnanılmaz! Bu iksirin tarifini de büyü kitabıma severek eklerim!"},{"a":"sia","t":"Pek çok hükümdarın yapacağı gibi. Ne yazık ki sanırım Kern imparatorunu da parmağında oynatıyor."},{"a":"lilu","t":"Politik dengeler çok karmaşık."},{"a":"lilu","t":"Uyardığın için teşekkürler! Onun yakınında daha dikkatli olacağım!"},{"a":"sia","t":"Anlayacağına emindim."},{"a":"sia","t":"Bana gelince, ben de kendisini kolaylıkla etki altında kalan kralımızdan uzak tutmaya çalışacağım."},{"a":"lilu","t":"Evet, sanırım herkes için en iyisi bu olur."}]},{"id":"donovan_a","i":3,"title":"On Altınlık Soygun","req":"donovan:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Şans Jetonları"},"side":true,"lines":[{"a":"leather","t":"Hey sen iksirci. Bir dakikan var mı?"},{"a":"donovan","t":"Peh... Serseriler."},{"a":"donovan","t":"Bu zevki kime borçluyum?"},{"a":"leather","t":"Ben Tamas, dericiyim."},{"a":"leather","t":"Dostum, duyduğuma göre müthiş bir ölümsüzlük iksiri varmış elinde. Bana da bir şişe var mı?"},{"a":"donovan","t":"Bu söylenti kulağına nasıl çalındı bilmiyorum."},{"a":"donovan","t":"Zaten doğru olsaydı bile böylesine değerli bir şeyi önüme gelene verecek değildim herhalde!"},{"a":"leather","t":"Sana on altın veririm."},{"a":"donovan","t":"Kesinlikle OLMAZ: Bu tarif için ne savaşlar yapıldı! Azıcık tatmak için dünyanın her yerinden imparatorlar sıraya girdi!"},{"a":"leather","t":"Sıkı pazarlık ediyorsun dostum. On beş altın, bu son teklifim."},{"a":"donovan","t":"Deri kokusundan beynin mi çürüdü serseri? Dünyanın tüm altınlarına bile değişmem bu tarifi!"},{"a":"donovan","t":"Şimdi gitmem gerek. Lütfen bir daha da benimle konuşma."},{"a":"leather","t":"Tüh be, az kalsın alıyordum."},{"a":"leather","t":"Sanırım şu koyunlar için başka bir ödül bulmam gerekecek."}]}]},{"id":"hemma","name":"Hemma","chapters":[{"id":"hemma_01","i":1,"title":"Beliren Gölge","req":"hemma:1","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"hemma","t":"... Ve böylece Belalı düştü ama ancak dostlarıma birkaç darbe indirdikten sonra."},{"a":"hemma","t":"Lütfen dostlarımın iyileştiklerinden emin ol."},{"a":"priest","t":"Elbette. Yaralarına ivedilikle bakacağım."},{"a":"lilu","t":"Selam! Duyduğuma göre şehirde yeni bir büyücü varmış."},{"a":"lilu","t":"Ben Lilu! Tanıştığımıza çok memnun oldum!"},{"a":"hemma","t":"Doğru söylüyorsun küçük Lilu. İsmimiz Hemma. "},{"a":"lilu","t":"\"İsmimiz\" mi?"},{"a":"hemma","t":"Evet. Ruh çağırma, bu büyüleri yapanlara büyük zarar verir..."},{"a":"hemma","t":"Senin bir parçan perdenin ardında kalırken diğer şeyler eşiği geçer..."},{"a":"hemma","t":"Bu güçler... Bizi değiştirdi. İyi yönde tabii."},{"a":"lilu","t":"Ruh çağırma mı dedin? Bu... Tehlikeli değil mi?"},{"a":"hemma","t":"İnanılmaz tehlikeli. Ama artık ufak numaralarla tatmin olmuyoruz."},{"a":"hemma","t":"Şimdi bize müsaade edersen başka bir yerde olmamız gerek. Elveda."},{"a":"lilu","t":"Bir ölüm büyücüsü... Bu oldukça karanlık bir büyü Pollux! Ama ilk defa bir ruh çağıranı kendi gözlerimle gördüm!"},{"a":"lilu","t":"Çok da kötü görünmüyordu... Değil mi?"}]},{"id":"hemma_02","i":2,"title":"Ne Pahasına Olursa Olsun","req":"hemma:2","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"elderowen","t":"Bir ölüm büyücüsü mü?"},{"a":"elderowen","t":"Buna ne cevap vereceğimi bilemiyorum..."},{"a":"hemma","t":"Endişelenmekte haklısın. Ruh çağırma zayıf varlıkları tüketen tehlikeli bir sanattır..."},{"a":"hemma","t":"Ama biz hiçbir şekilde zayıf değiliz."},{"a":"elderowen","t":"Peki ya seninle gelen maceracılar? Büyülerini güçlendirmek için onları enerjilerini emmiyor musun?"},{"a":"hemma","t":"Sadece kendi rızaları varsa. Bu işlemin etkileri kalıcı değildir."},{"a":"hemma","t":"Ve hizmetleri için de onlara yüklü miktarlarda ödeme yapıyoruz."},{"a":"elderowen","t":"Sanırım öyle ya da böyle nihayetinde iyilik yapmış oluyorsun..."},{"a":"elderowen","t":"Pekâlâ. Sanırım sen şehrimizin onaylı Şampiyonu olabilirsin."},{"a":"hemma","t":"Onayına ihtiyacımız yoktu... Ama teşekkür ederiz."},{"a":"elderowen","t":"Peki seni şehrimize getiren nedir?"},{"a":"hemma","t":"..."},{"a":"hemma","t":"Biz sadece bilgi ve güç arayışındayız. "},{"a":"hemma","t":"Tamamlamamız gereken... Bir görevimiz var."},{"a":"elderowen","t":"Ne kadar da anlaşılmaz laflar..."},{"a":"hemma","t":"Ve öyle de kalacak. Elveda."},{"a":"elderowen","t":"..."},{"a":"elderowen","t":"O gözlerde fazlasıyla hüzün saklı..."}]},{"id":"hemma_03","i":3,"title":"İçindeki Düşman","req":"hemma:3","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"herbalist","t":"Olgunlaşmamış Canlı Kökler ve ekstra büyük Ürperten Sihirli Ruh. Başka bir şey var mıydı?"},{"a":"hemma","t":"Hepsi bu kadar. Geri kalanı için tüccarı ziyaret etmeliyiz."},{"a":"herbalist","t":"Teşekkürler, yine beklerim!"},{"a":"hemma","t":"<c4>...Kaygılı pençeleri de unutmayalım.</c4>"},{"a":"hemma","t":"Ah, evet. Bir çift Kaygılı Pençe lütfen."},{"a":"herbalist","t":"O DA neyin nesiydi?"},{"a":"hemma","t":"Ona aldırış etmeyin. Altı üstü bir yolcu kendisi."},{"a":"hemma","t":"<c4>Beni çıkarın, beni çıkarın, beni çıkarın.</c4>"},{"a":"hemma","t":"Öff, biraz sakinleşsene sen!"},{"a":"hemma","t":"Üstü kalsın. Sağlıcakla."},{"a":"herbalist","t":"Bahşiş ve kâbuslar için teşekkürler."}]},{"id":"hemma_a","i":3,"title":"Ölümsüzler Arasında","req":"hemma:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Şans Jetonları"},"side":true,"lines":[{"a":"donovan","t":"Olgunlaşmamış Canlı Kök mü? İlginç bir seçim."},{"a":"hemma","t":"Ne olmuş?"},{"a":"donovan","t":"Canlı Kökler, gençlik ve yaşam süresiyle ilgili birçok büyü için güçlü reaktiflerdir."},{"a":"donovan","t":"Siz de mi bir simyacısınız? Ömrünüzü uzatmanın yollarını mı arıyorsunuz?"},{"a":"hemma","t":"Bir kadına yaşını mı soruyorsun? Hiç... Yakıştıramadım."},{"a":"hemma","t":"Biz simyacı değiliz. Kan kurbanları çok daha etkili oluyor."},{"a":"donovan","t":"Ah, ölüm büyüsü! Saygı duyulan ama kimsenin bilmediği bir alan."},{"a":"hemma","t":"Yaşımıza gelince... Yılları saymayı bırakalı çok oldu."},{"a":"donovan","t":"Çok iyi anlıyorum. İlk birkaç yüzyıldan sonra onca yıl su gibi akıp gidiyordur!"},{"a":"donovan","t":"Bu kadar haşeratın arasında yalnız hissediyorsunuz, değil mi?"},{"a":"hemma","t":"Biz yalnız değiliz. Bir ölüm büyücüsünün işine burnunu sokmasan iyi edersin."},{"a":"donovan","t":"Tabii ki. Ben sizi tutmayayım! Hoşça kalın!"},{"a":"donovan","t":"Tuhaf... Seninle daha önce tanışmış mıydık ölüm büyücüsü?"},{"a":"donovan","t":"Fairlyn?"}]},{"id":"hemma_04","i":4,"title":"Kış Kış Cinler","req":"hemma:4","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"Merak etme Hemma. Artık buradayım! Freyja'yı da getirdim!"},{"a":"priest","t":"Hemma'ydı değil mi? Rahat ol. Bırak lanet çıksın içinden."},{"a":"hemma","t":"Senden yardım istediğimizi hatırlamıyoruz."},{"a":"hemma","t":"<c4>Siz gidin veletler. Ben hiçbir yere gitmiyorum.</c4>"},{"a":"lilu","t":"Aaaah! Onu ele geçiriyorlar! Çabuk ol Freyja!"},{"a":"priest","t":"Ya... Yapamıyorum! Dualarım bir şekilde engelleniyor..."},{"a":"hemma","t":"Biz engelliyoruz. Dur artık."},{"a":"priest","t":"Bu kötücül ruhu kendi isteğinle mi içinde tutuyorsun?"},{"a":"hemma","t":"Zamanla iş çığırından çıktı, evet."},{"a":"hemma","t":"<c4>Burada kurban olan taraf benim! Çıkartın beni!</c4>"},{"a":"hemma","t":"Öff. Bu kötücül filan değil, kaba ruhun teki."},{"a":"hemma","t":"Bu seni ilgilendirmiyor. Lütfen karışma Freyja."},{"a":"priest","t":"Ölüm büyücüleri... Bilmedikleri güçleri kurcalayıp duruyorlar sürekli!"},{"a":"lilu","t":"Merak etme Freyja! Ne yaptığını bildiğinden eminim!"},{"a":"lilu","t":"Değil mi?"}]},{"id":"hemma_05","i":5,"title":"Gelgit Akıllı","req":"hemma:5","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"hemma","t":"<c4>Yine her şey açığa çıktı demek. Şehirden ayrılmaya hazır mısın?</c4>"},{"a":"hemma","t":"Bu SENİN suçun. Dilini tutsaydın her şey daha kolay olurdu."},{"a":"hemma","t":"Yine de buradan şimdi gitmiyoruz. Bu şehir umut vadediyor."},{"a":"hemma","t":"<c4>İyi. Beni bir kerecik salsan olmaz mı peki?</c4>"},{"a":"hemma","t":"Hayatta olmaz. Şimdi bile zor zapt ediyorum seni."},{"a":"hemma","t":"<c4>Beni çıkarın, beni çıkarın, beni çıkarın.</c4>"},{"a":"hemma","t":"Bunu iyiliğin için yapıyorum Claud."},{"a":"hemma","t":"Bunu unutma lütfen."}]},{"id":"hemma_06","i":6,"title":"Miras Kalmış Yalanlar","req":"hemma:6","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"Fairlyn!"},{"a":"hemma","t":"Efendim?"},{"a":"lilu","t":"Biliyordum işte! Hemma sahte bir isimmiş! Canavar senmişsin Fairlyn!"},{"a":"hemma","t":"Bak sen şu işe. Ne zekice dolaplar çeviriyormuşsun da haberimiz yokmuş."},{"a":"hemma","t":"Doğru bildin. Belli ki dersine çalışmışsın."},{"a":"hemma","t":"Belki Meczup Ariel'in hikâyesini de duymuşsundur. Hatta belki Mağlup Astrid'in hikâyesini de..."},{"a":"lilu","t":"Evet, okumuştum ama... Onlar uzun yıllar önce yok olup gitti! Mümkün değil..."},{"a":"hemma","t":"Hepsi biziz tabii ki. Maalesef bu yüzden çok zulüm çektik, eski isimlerimizden kurtulmamız lazımdı..."},{"a":"lilu","t":"Bir canavarsın sen! Durdurulman gerekiyor!"},{"a":"hemma","t":"Peki bunu nasıl yapacaksın? \"Hemma\" masum biri. Bu korkunç hikâyene kim inanır?"},{"a":"hemma","t":"Tabii beni bizzat sen durdurmaya çalışacaksan o başka..."},{"a":"lilu","t":"Hıh!"}]},{"id":"hemma_07","i":7,"title":"Ruh Bağlama","req":"hemma:7","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"hemma","t":"Hâlâ ortalıkta kös kös dolaşıyorsun demek."},{"a":"lilu","t":"Gözümü üzerinden ayırmayacağım. Tuhaf tuhaf şeyler söylüyorsun..."},{"a":"hemma","t":"Ah, doğru tabii. Eşimiz Claud ile tanışmış mıydın? Şu an pek formunda değil ama..."},{"a":"hemma","t":"<c4>Çıkmak istiyorum!</c4>"},{"a":"lilu","t":"Ona ne oldu böyle?"},{"a":"hemma","t":"Ruh çağırırken korkunç bir kaza geçirdi. Aptalca bir hata yüzünden ölümle burun buruna geldi."},{"a":"hemma","t":"Bu dünyada işlediğimiz günahları düşününce biz ölüm büyücüleri için öbür dünyaya gitme fikri bir hayli korkutucu..."},{"a":"hemma","t":"Bedenini kurtarmayı başaramadık fakat elimizden geleni yaptık... Sonunda ruhunu kurtarabildik."},{"a":"lilu","t":"Ruh Bağlama yöntemiyle mi? İyi ama o büyüyü kullanarak uygun bir beden hazırlamak için yıllarca araştırma yapmak lazım..."},{"a":"hemma","t":"Evet. Şartlar öyle gerektirdi, biz de doğaçlama yapmak zorunda kaldık."},{"a":"lilu","t":"Doğaçlama mı? Yani... Yani Claud'un ruhunu kendi bedenine mi bağladın?"},{"a":"lilu","t":"Bir beden iki ruh taşıyamaz ki! Bunun sonucu..."},{"a":"hemma","t":"Akıl almaz bir acı. Cinnet. Tahmin bile edemeyeceğin kadar büyük bir ızdırap."},{"a":"lilu","t":"Hemma... Neden... Nasıl..."},{"a":"hemma","t":"Cevabı çok basit küçük Lilu. Başarısız olmak gibi bir seçeneğimiz yok."}]},{"id":"hemma_08","i":8,"title":"Yüzyılın Görevi","req":"hemma:8","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"O kadar güçlü ki ruhunu kovamıyorum... Belki ruhunu başka bir şeye bağlayabiliriz."},{"a":"hemma","t":"Ne kadar da yardımseversin. Son zamanlarda ölüm büyülerine mi merak sardın yoksa?"},{"a":"lilu","t":"Hayır! Senden de tüm bu yaptıklarından da nefret ediyorum!"},{"a":"lilu","t":"Bana sorarsan Claud denen o adam serbest kalırsa buradaki herkesin başı belada demektir."},{"a":"lilu","t":"Ben yalnızca bu saçmalığı düzeltmen için sana yardım ediyorum, o kadar!"},{"a":"hemma","t":"Ne kadar düşüncelisin. Peki ama senin gibi bir çocuğun nasıl bir faydası olabilir ki?"},{"a":"lilu","t":"Uygun bir beden hazırlamak için gerekli araştırmayı yapmak ve malzemeleri toplamak yıllar sürer..."},{"a":"hemma","t":"Orası sorun değil. İzle de gör."},{"a":"lilu","t":"Tüm bunları nasıl topladın? Kara Elmasları bile bulmuşsun!"},{"a":"hemma","t":"Bunca vakti boş geçirmedim tabii. Vaktimiz daralıyor."},{"a":"hemma","t":"Şimdi yalnızca ayini gerçekleştirebileceğimiz uygun bir yer bulmak kaldı. Korkarım böyle bir yer olmayabilir."},{"a":"lilu","t":"Doğru. Ruhun bölgeye ruhani bir bağlantısı olmalı. Aksi takdirde bağlama başarısız olacak."},{"a":"hemma","t":"<c4>En iyisi siz bu ihtiyar Claud Favius'u serbest bırakın gitsin! Etrafta kendine bir sürü arkadaş bulur!</c4>"},{"a":"lilu","t":"Bir dakika... Favius mu dedin?"}]},{"id":"hemma_09","i":9,"title":"Perili Şato","req":"hemma:9","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"hemma","t":"Ne kadar da perili bir yer."},{"a":"lilu","t":"Burası korkunç bir yer. Aklı başında olan kimse buraya gelmemeli."},{"a":"lilu","t":"Yine de araştırmalarıma göre..."},{"a":"lilu","t":"Burada yüzyıllar önce Favius ailesinden meczup bir kral yaşar ve hüküm sürermiş."},{"a":"lilu","t":"Belki kendisi Claud'un uzaktan akrabasıdır. Umarım krallığın yok olmasında onun bir payı yoktur..."},{"a":"hemma","t":"Hissediyoruz. Burayla bir bağlantımız var. Doğru yeri bulduk."},{"a":"hemma","t":"Sana büyük bir iyilik borçluyuz Lilu. Ama şimdi bizi yalnız bırakmalısın."},{"a":"lilu","t":"Hemma... Bol şans."}]},{"id":"hemma_10","i":10,"title":"Ölüm Bizi Ayırana Dek","req":"hemma:10","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"hemma","t":"Karanlık, lanetli ve izbe bir yer. Ruhani enerjiyle dolup taşıyor..."},{"a":"hemma","t":"Bunca zamandır böyle bir yer arıyorduk."},{"a":"hemma","t":"Şimdi ise uygun bir beden bulmamız gerekiyor..."},{"a":"hemma","t":"Konuşmana gerek yok. Ne istediğini biliyoruz."},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"Meczup kralın sonsuza dek buraya bağlanmış zırhı..."},{"a":"hemma","t":"<c1>Ruhun Bağlansın!</c1>"},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"Off... Biz... Hayır, ben..."},{"a":"hemma","t":"Bu yalnızlık hissinin nasıl olduğunu unutmuşum."},{"a":"hemma","t":"Seni kurtarmak için bitmek bilmeyen bir acı çektim canım. Zira biliyorum ki sen de aynısını benim için yapardın."},{"a":"hemma","t":"Buraya cesur maceracılar gelecektir. Onlarla savaş, katliamdan beslen ve ızdırap içindeki varlığını iyileştir."},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"Hoşça kal sevgilim. Unutma ki bizi yalnızca ölüm ayırabilir."}]},{"id":"hemma_epilogue","i":11,"title":"Son Söz","req":"hemma:11","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"Castle_Boss","t":"<c4>APTALLAR SİZİ! NE CÜRRETLE BENİM TOPRAKLARIMA AYAK BASARSINIZ?</c4>"},{"a":"sia","t":"Azılı bir düşman!"},{"a":"Castle_Boss","t":"<c4>HAHAHAHA! ZAVALLI FÂNİLER!</c4>"},{"a":"argon","t":"Leydi Sia! Rudo! Geri çekilmeliyiz!"},{"a":"rudo","t":"Asla! Ona asla boyun eğmeyeceğim!"},{"a":"yami","t":"Bir çıkış buldum. Acele edin!"},{"a":"rudo","t":"Hah! Geri döneceğim seni koca teneke yığını! Duydun mu beni?"},{"a":"Castle_Boss","t":"<c4>DOĞRU DÜZGÜN DÖVÜŞEBİLDİĞİN ZAMAN GERİ GEL!</c4>"},{"a":"Castle_Boss","t":"<c4>EN GÜÇLÜ KAHRAMANLARINA DA SÖYLE, ZALİM KRAL BURADA BEKLİYOR!</c4>"}]}]},{"id":"lilu","name":"Lilu","chapters":[{"id":"lilu_01","i":1,"title":"Hünerli Çırak","req":"lilu:1","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"Ee Pollux? Bu yeni büyüye ne diyorsun? Mükemmel, değil mi?"},{"a":"lilu","t":"Evet, bu sefer kesin başarılı olacağız!"},{"a":"herbalist","t":"Günaydın Lilu. Haftalık Canlı Kök sevkiyatı için mi geldin?"},{"a":"lilu","t":"Evet, teşekkürler Maribel!"},{"a":"herbalist","t":"Bu hafta bayağı sipariş verdin! Ustan ne yapıyor ki bunlarla?"},{"a":"lilu","t":"Aslında yarısı kadarı benim. Ciddi bir çalışma yürütüyorum!"},{"a":"herbalist","t":"Yaa! Nasıl bir çalışma?"},{"a":"lilu","t":"İyileştirme büyüleri! Geçtiğimiz haftanın tümünü Eğitim Salonu'nda kesikleri ve morlukları tedavi ederek geçirdim!"},{"a":"herbalist","t":"Eminim Kahramanlar, orada olmandan memnundurlar."},{"a":"herbalist","t":"Argon da tabii!"},{"a":"lilu","t":"..."},{"a":"lilu","t":"Gi-Gitmem gerek! Teşekkürler!"}]},{"id":"lilu_02","i":2,"title":"Kara Haber","req":"lilu:2","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"İşte bu haftanın Canlı Kökleri, Usta Grimar."},{"a":"wizard","t":"Teşekkür ederim Lola. Bu da bugünün ödevi."},{"a":"lilu","t":"Ah! Bir büyü kitabı! İyileştirme ile mi ilgili?"},{"a":"lilu","t":"\"Zalimin Lanet Rehberi\"?"},{"a":"lilu","t":"Bu kitap çok ileri seviye! Lanetlere ayrılmış bir bölüm bile var!"},{"a":"wizard","t":"Lanetler mi?"},{"a":"wizard","t":"Hımm... Lanetler?"},{"a":"lilu","t":"Usta?"},{"a":"wizard","t":"35 sene önce bugün... Ben..."},{"a":"lilu","t":"Usta Grimar?"},{"a":"wizard","t":"Neyse unuttum. Sen kimsin yahu?"},{"a":"lilu","t":"Ben, çırağın Lilu. Ya da bazen dediğin gibi, Lola."},{"a":"lilu","t":"Ah, boş ver. Ben bu kitaba çalışayım. Teşekkürler Grim."}]},{"id":"lilu_03","i":3,"title":"Sersem Kafa","req":"lilu:3","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"Bir tutam da gümüş tozu ekledik mi... Tamamdır!"},{"a":"lilu","t":"Vay be, nasıl da parlıyor! Bence hiç fena değil, ne dersin Pollux?"},{"a":"lilu","t":"Zalim'in Lanet Rehberi'nde yazanlar doğruysa, o zaman bu iksir de..."},{"a":"wizard","t":"Bu patırtı da ne Lola? Uyumaya çalışıyorum şurada!"},{"a":"lilu","t":"Usta Grimar! Kitabın sayesinde çok ileri seviyede bir iksir yapmayı başardım. Bence..."},{"a":"wizard","t":"Ne yaptım dedin?"},{"a":"wizard","t":"Neyse, ver bakayım! Bir tadına bakalım!"},{"a":"wizard","t":"..."},{"a":"lilu","t":"Usta Grimar?"},{"a":"wizard","t":"Lilu! Be-beni kur-kurtarman gerek! Çıkar be-beni bu yarım akıl-akıllı ahmağın iç-içinden!"},{"a":"lilu","t":"Usta Grimar! İyi misin?"},{"a":"wizard","t":"..."},{"a":"wizard","t":"*Geğirti* Meyve tadı biraz ağır basmış!"},{"a":"wizard","t":"Fena değil Lola. Haydi, şimdi işinin başına."},{"a":"lilu","t":"Bu çok acayipti."}]},{"id":"lilu_a","i":3,"title":"Çağların İstifçisi","req":"lilu:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Şans Jetonları"},"side":true,"lines":[{"a":"lilu","t":"Grimar, bana ikinci bir <c1>Koleksiyon Albümün</c1> olduğunu söylememiştin!"},{"a":"wizard","t":"<c1>Koleksiyon Albümü</c1> mü? Bu, bir şeyler çağrıştırıyor..."},{"a":"lilu","t":"Vay be! Bunun içi muazzam bilgilerle dolu! <c1>Demokles</c1>... <c1>Kehribar Hisarı</c1>..."},{"a":"lilu","t":"<c1>Grimar'ın Büyük Asası</c1>? Buna sen mi isim verdin?"},{"a":"lilu","t":"Çok fazla sayfası var! Sen tam bir koleksiyoncu olmalısın!"},{"a":"sundragon","t":"Bir zamanlar kesinlikle öyleydi!"},{"a":"wizard","t":"Sondra, sen misin eski dostum?"},{"a":"lilu","t":"Vay be! Siz birbirinizi tanıyor musunuz?"},{"a":"sundragon","t":"Pek tabii. Genç Grimar Koleksiyon Albümü'ne tam anlamıyla hayrandı."},{"a":"sundragon","t":"Sanıyorum, bu da yaşıtları arasında ona prestijli bir lakap kazandırdı... \"İnek\", değil mi?"},{"a":"lilu","t":"Bu acıttı..."},{"a":"sundragon","t":"Nadir eşyalar peşinde koştuğu görev sırasında tanıştık ve birlikte <c1>Birleştirme Kazanını</c1> yarattık."},{"a":"sundragon","t":"Gece gündüz demeden birleştirmeyle yüzlerce eşya yaptı... Hele dolunay varsa daha da fazlasını!"},{"a":"lilu","t":"Onca çabaya rağmen koleksiyonunda halen eksikler var!"},{"a":"lilu","t":"Usta Grimar, andım olsun ki sizi iyileştireceğim! Hayatınızı adadığınız bu eseri bitirmelisiniz!"},{"a":"sundragon","t":"Zaman şüphesiz ki insana karşı acımasız. Görevin sırasında sana iyi şanslar dilerim genç dostum."}]},{"id":"lilu_04","i":4,"title":"Bir Soyun Sonu","req":"sia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"Usta Grimar'da bir terslik var..."},{"a":"lilu","t":"Yani sesi... Sanki içindeki biri konuşuyormuş gibiydi!"},{"a":"lilu","t":"Karmaşık bir dönüşüm büyüsüyle uğraşıyor olabilir miyiz?"},{"a":"lilu","t":"Hatta, belki de..."},{"a":"leather","t":"Lilu, dostum! Kralın verdiği ziyafet sırasında ters giden bir şeyler oldu!"},{"a":"lilu","t":"Tamas? Neler oldu?"},{"a":"leather","t":"Bir saldırgan gizlice kaleye girmiş, dostum. Bayağı ürkünç!"},{"a":"lilu","t":"Saldırgan mı? Olamaz, bugün Argon'un şövalyelikteki ilk günü!"},{"a":"lilu","t":"Teşekkürler Tamas! Gitmem lazım."},{"a":"lilu","t":"Olamaz! Neler oluyor burada?"},{"a":"lilu","t":"Argon, neredesin?"},{"a":"king","t":"Ahhh..."},{"a":"lilu","t":"KRAL REINHOLD! İyi misiniz?"},{"a":"king","t":"Aahh... Nadide hayatım... Ellerimden kayıp gidiyor..."},{"a":"lilu","t":"Bu hiç iyi değil!"},{"a":"lilu","t":"Odaklan Lilu! Bilgelik eğitimini hatırla!"},{"a":"lilu","t":"Kral Reinhold! Kımıldamayın! <c1>İyileş</c1>!"},{"a":"king","t":"Bir faydası yok... Lütfen... Canım naaşımı koruyun..."},{"a":"lilu","t":"Bir etkisi yok..."},{"a":"lilu","t":"Hayır... Yoksa... Bu zehir mi?"},{"a":"lilu","t":"Tıpkı annemle babama olan gibi... Bu sefer olmaz! Başarmalıyım!"},{"a":"lilu","t":"<c1>Muazzam Zehir Arındırması!</c1>"},{"a":"king","t":"Aaaah... Ha?"},{"a":"lilu","t":"Kral Reinhold? Nasılsınız?"},{"a":"lilu","t":"Bir saniye... Şuradaki kupa sizi ninja yıldızından korumuş! Hiçbir şeyiniz yok!"},{"a":"king","t":"Aa! Öyle mi gerçekten? Biraz fazla tepki verdim sanırım."},{"a":"king","t":"Bir kralın ölümü başlı başına dramatik bir olay zaten."},{"a":"lilu","t":"Öff! Reinhold!"}]},{"id":"lilu_05","i":5,"title":"Zehrini Seç","req":"lilu:5","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"Ahh... Çok yakındı... Yani sayılır."},{"a":"lilu","t":"Reinhold gerçekten zehirlenmiş olsaydı... Onu kurtaramazdım."},{"a":"lilu","t":"Çalışmalarıma tekrar odaklanmalıyım. Benim yaşadığım kaybı başkalarına yaşatmayacağım..."},{"a":"lilu","t":"Bayan Sia!"},{"a":"sia","t":"Ah, günün yıldızı! Davetsiz misafirle ilgilenmesi için bir şövalye gönderildi. İçin rahat olsun."},{"a":"lilu","t":"(Şövalye mi? Şansın bol olsun Argon!)"},{"a":"sia","t":"Her şeye rağmen... Kralımızı kurtardığın için teşekkürler."},{"a":"lilu","t":"Lafı bile olmaz! Ama tekrar olacak olursa yardım edebilir miyim bilmiyorum..."},{"a":"lilu","t":"Bayan Sia, zehirler hakkında bilginiz var mı?"},{"a":"sia","t":"Elbette. Kurtboğan olarak da bilinen boğan otu, son derece ölümcüldür."},{"a":"sia","t":"Ama benim kişisel favori zehrim risin. Sessiz, ölümcül ve kolay ulaşılabilir..."},{"a":"lilu","t":"Hımm... Peki ya tedavileri?"},{"a":"sia","t":"Ah. Bu konuda kafa yorduğumu pek söyleyemem."},{"a":"lilu","t":"Boş ver o zaman."}]},{"id":"lilu_06","i":6,"title":"Usta ve Öğrencisi","req":"lilu:6","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"Ben geldim Usta Grimar!"},{"a":"wizard","t":"Ah, hoş geldin Lola."},{"a":"lilu","t":"Düşünebiliyor musun? Kral neredeyse suikasta uğruyordu!"},{"a":"wizard","t":"Demek öyle..."},{"a":"lilu","t":"Aniden ortaya çıkan bir suikastçı ninja yıldızıyla krala saldırdı!"},{"a":"lilu","t":"Sonra hızla yardımına koştum, kral öylece yerde yatıyordu, son nefesini vermek üzereydi!"},{"a":"wizard","t":"Hımm... Sen kimdin, bir hatırlatsana?"},{"a":"lilu","t":"Ah, doğru. Sağlık durumun... Şimdi gitmem gerekiyor!"},{"a":"lilu","t":"Zehir de kullanılmış olabilirdi..."},{"a":"lilu","t":"Bir düşüneyim... Grimar çok yaşlı..."},{"a":"lilu","t":"Sen ne dersin Pollux?"},{"a":"lilu","t":"Evet, şehirde sorup soruştursak iyi olacak!"},{"a":"lilu","t":"Yaşlılardan bazıları gençken Grimar'ın nasıl biri olduğunu hatırlayabilir..."}]},{"id":"lilu_07","i":7,"title":"Antik Bilgiler","req":"lilu:7","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"Usta Theodore!"},{"a":"master","t":"Lilu, sen misin? Sana nasıl yardımcı olabilirim bugün?"},{"a":"lilu","t":"Bana Grimar'ın gençlik zamanlarından bahsedebilir misin diye soracaktım..."},{"a":"lilu","t":"Yani sen şey... Yaşlı olduğun için."},{"a":"master","t":"Ho ho ho! Tabii ki, tabii ki!."},{"a":"master","t":"Yaşlı Grimar her zaman biraz... Tuhaf olmuştur."},{"a":"master","t":"İkimizin de delikanlı olduğu zamanlar, çok daha zekiydi diye hatırlıyorum. Hatta satrançta rakibimdi."},{"a":"master","t":"Şimdi düşünüyorum da Kronos Harabeleri'ne yaptığı geziden sonra... Hep bir keyifsiz oldu."},{"a":"lilu","t":"Kronos Harabeleri mi? Ama çok tehlikeli bir yer orası!"},{"a":"lilu","t":"Zaman büyüsünü araştırırken harabeye dönen koca bir medeniyet..."},{"a":"lilu","t":"Orası büyülü garipliklerle dolu bir yer! Grimar böyle bir yere giderek ne elde etmeyi umdu acaba?"},{"a":"lilu","t":"Haklısın Pollux, elimizdeki tek ipucu bu. Gidip araştırmalıyız!"},{"a":"lilu","t":"Ama bize eşlik edecek birine ihtiyacımız var... Argon'a mı sorsak?"},{"a":"lilu","t":"Hayır! Ya zaman girdabı onu birden yaşlı bir adama dönüştürürse? Ya da Grimar gibi olursa..."},{"a":"lilu","t":"Aklıma bize yardım edebilecek tek bir kişi geliyor..."},{"a":"lilu","t":"Hiç kolay olmayacak Pollux! Ama denemek zorundayız!"},{"a":"lilu","t":"Teşekkürler Theodore! Çok yardımcı oldun!"},{"a":"master","t":"Rica ederim Lilu. Görüşürüz!"},{"a":"master","t":"..."},{"a":"master","t":"Bu baykuş ne kadar da zeki!"}]},{"id":"lilu_08","i":8,"title":"İşbirliği Vakti","req":"lilu:8","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"Bay Rudo lütfen! Lütfen gitmeyin, sizinle konuşmam gerek!"},{"a":"rudo","t":"Toz ol evlat, her ne diyeceksen duymak istemiyorum."},{"a":"rudo","t":"Baykuşun da sen de başka kapıya!"},{"a":"lilu","t":"Büyücüleri sevmediğinizi biliyorum ama gerçekten yardımınıza ihtiyacım var!"},{"a":"lilu","t":"Kronos Harabeleri'nin derinlerine inmem gerek ve bunu yalnız yapamam! "},{"a":"rudo","t":"Parlak zırhlı şövalyene, Argon denilen o gence neden sormuyorsun?"},{"a":"lilu","t":"O şey... Şu anda başka bir şeyle meşgul..."},{"a":"lilu","t":"Sanırım size sormamın da bir anlamı yok..."},{"a":"rudo","t":"Doğru anladın evlat."},{"a":"tavern","t":"Tatlım, gerçekten çok yazık."},{"a":"tavern","t":"Kronos Harabeleri'ndeki Tepegözlerin Efendisi'nin asla tek bir çarpışmayla alt edilemediğini duydum..."},{"a":"tavern","t":"Lilu'ya bu harabelerde ancak olağanüstü bir savaşçı eşlik edebilir!"},{"a":"rudo","t":"Hiç alt edilememiş mi dedin?"},{"a":"rudo","t":"Pekâlâ. Beni ikna ettin. Sağı solu epey kırıp dökmem gerekecek herhalde?"},{"a":"lilu","t":"Şüphesiz, fazlasıyla!"},{"a":"lilu","t":"Oraya vardığımızda çeşitli kristallerden gelen zaman akışının kaynağını bulup izole etmem..."},{"a":"rudo","t":"Lafı dolandırmadan kırıp dökme kısmına gel."},{"a":"lilu","t":"Kırıp dökeceğin büyü kristalleri ve tabii canavarlar da var."},{"a":"rudo","t":"Pekâlâ, geliyorum. Bana borçlusun evlat."},{"a":"lilu","t":"Muhteşem! Çok teşekkür ederim Bay Rudo!"},{"a":"rudo","t":"Teşekkürünü yolculuğumuzun sonuna sakla evlat. Bu iş parkta yürümeye benzemez."},{"a":"lilu","t":"Çok sayıda canavarla karşılaşırsan yaralarını iyileştirmek için yanında olacağım!"},{"a":"rudo","t":"Hıh. Hiç sanmıyorum."},{"a":"lilu","t":"Sana da teşekkür ederim Naya!"},{"a":"tavern","t":"Hiç sorun değil tatlım."}]},{"id":"lilu_09","i":9,"title":"Ayna Dünya","req":"lilu:9","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"rudo","t":"Ben Tepegözü oyalarım! Siz ilerleyin!"},{"a":"rudo","t":"Buraya gel yağ tulumu! Sana biraz yulaf vereyim!"},{"a":"lilu","t":"Anlaşıldı! Bol şans!"},{"a":"lilu","t":"İşte bu... Zaman Odası. Araştırmalarıma göre..."},{"a":"lilu","t":"Bu kuyu parçalanmış bir zaman akışına bağlı olmalı!"},{"a":"lilu","t":"Kronos Şehrinin gelişmeye devam ettiği bir paralel evren..."},{"a":"lilu","t":"Pollux baksana! Suya dikkatli bakınca bir şeyler görünüyor!"},{"a":"lilu","t":"Görünüşe göre Kronos halkı bir yerlerde hayatlarına normal bir şekilde devam ediyor..."},{"a":"lilu","t":"Hey... Şu adam bize mi el sallıyor ne?"},{"a":"lilu","t":"Grimar'a da çok benziyor!"}]},{"id":"lilu_10a","i":10,"title":"Bitmek Bilmeyen Yılların Laneti","req":"lilu:10","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"Grimar! Hadi iç şunu!"},{"a":"wizard","t":"Ne? Bu sanki... bir yerlerden tanıdık geliyor."},{"a":"lilu","t":"Kronos Suyundan yapılmış özel bir içecek..."},{"a":"wizard","t":"Kıvama getirildikten sonra Kaderin Ağı ile iki kez süzüldü..."},{"a":"lilu","t":"Damıtılmış Sihirli Ruh ile fiziksel bir forma getirildi."},{"a":"wizard","t":"Tadı için de bir tutam Derin Mercan kullanıldı!"},{"a":"wizard","t":"Harikasın Lilu. Ustanı gururlandırdın."},{"a":"lilu","t":"G-grimar... Normale döndün! İşe yaradı!"},{"a":"wizard","t":"Ne ilginç bir deneyimdi... Zihnimdeki sis dağıldı sanki..."},{"a":"lilu","t":"Bu iksirin nasıl çalıştığını az çok anlayabiliyorum ama... Mantıklı olmayan bir şeyler var."},{"a":"lilu","t":"Seni kuyunun orada görmüştük! Parçalanmış zaman akışında!"},{"a":"wizard","t":"Haha! Öyle mi dersin? Bu konuda bir tahminim var..."},{"a":"wizard","t":"Pollux, canım. İhtiyar Owen'ı buraya çağırabilir misin? Açıklanacak çok şey var..."}]},{"id":"lilu_10b","i":11,"title":"Zaman Yarılması Kuramı","req":"lilu:10","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"elderowen","t":"Ah, eski dostum! Bu oldukça iyi bir hikâye!"},{"a":"lilu","t":"Buna inanamıyorum... Grimar, Kronos Şehrinde hayatta kalanlardan biri miymiş?"},{"a":"wizard","t":"Zaman Büyüsü bozulduğunda şehir tamamen başka bir zaman akışına itilmiş."},{"a":"elderowen","t":"Dün gibi hatırlıyorum... Koskoca şehir bir anda yok olmuştu!"},{"a":"elderowen","t":"Harabelerin içinde bulabildiğimiz tek şey kendi başına dolaşan bir çocuktu..."},{"a":"lilu","t":"Grimar değil mi? İkinizi çocuk olarak düşünmek çok zor..."},{"a":"elderowen","t":"Haha! Hemen arkadaş olmuştuk değil mi?"},{"a":"wizard","t":"Evet. Ben büyücü olmak için eğitim aldım ve bu tuhaf olayı bizzat araştırdım."},{"a":"wizard","t":"Lilu'nun gördüğü şey doğruysa başka bir Grimar daha var demektir."},{"a":"lilu","t":"Gördüğümüz diğer Grimar... Yani sen başka bir zaman akışında da mı varsın?"},{"a":"wizard","t":"Öyle görünüyor. Başta bir etkisi yoktu ama..."},{"a":"wizard","t":"İki Grimar da büyüdükçe hayat tecrübelerimiz ve kişiliklerimiz ayrılmaya başladı."},{"a":"lilu","t":"Ve bu büyüyen sihirli paradoks zihnini yormaya başladı..."},{"a":"lilu","t":"Anladım! Kronos Harabelerinde o iksiri içtiğinde diğer zaman akışına bağlanmış olmalısın!"},{"a":"wizard","t":"Benim tahminim bu. Eminim diğer Grimar da bana hak verecektir."},{"a":"lilu","t":"Vay be... Üzerine düşünecek çok şey var. Sanırım biraz zamana ihtiyacım var. Geliyor musun Pollux?"},{"a":"elderowen","t":"Bizim de konuşacak çok şeyimiz var ihtiyar Grim!"},{"a":"wizard","t":"Kendi adına konuş bunak! Ben hâlâ çok gencim!"}]},{"id":"lilu_epilogue","i":12,"title":"Son Söz","req":"lilu:11","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"Merhaba Grimar! İşte yeni bir tarif. Bu daha uzun süre dayanacaktır."},{"a":"wizard","t":"Müthiş bir geliştirme bu! Anne ve baban seninle gurur duyardı."},{"a":"lilu","t":"Keşke simya eğitimime daha erken başlamış olsaydım..."},{"a":"wizard","t":"Ben de aynı şeyi düşünüyorum. Ben de keşke tüm yetilerime hâkim olsaydım..."},{"a":"lilu","t":"Mühim değil. Daha iyi olabilmek ve insanları bu kaderden kurtarabilmek için geleceğe odaklanmaya karar verdim."},{"a":"lilu","t":"Eminim anne ve babam da bunu isterdi."},{"a":"wizard","t":"Ne kadar çok büyümüşsün... Seni tanıyamadım."},{"a":"wizard","t":"Ciddiyim... Sen de kimsin?"},{"a":"lilu","t":"Hayır! Etkisi geçmeye başladı bile! Ben en iyisi..."},{"a":"wizard","t":"Haha! Şaka yapıyorum. Bu iksirden umutluyum."},{"a":"wizard","t":"Pekâlâ, zihnim hazır açıkken biraz büyü öğrenmeye ne dersin?"},{"a":"wizard","t":"Ustanın hâlâ gösterecek birkaç numarası var."},{"a":"lilu","t":"Şekil Değiştirme büyüsüne ne dersin? Çok heyecanlandım şimdi!"}]}]},{"id":"malady","name":"Malady","chapters":[{"id":"malady_01","i":1,"title":"Taşa Kazınmış","req":"malady:1","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"argon","t":"Görev tamamlandı! Kayıp çocuklar bulundu ve kurtarıldı!"},{"a":"argon","t":"Kronos Harabeleri oyun oynamak için güvenli bir yer değil."},{"a":"argon","t":"Ben de çıkış yolunu bulsam iyi olacak!"},{"a":"malady","t":"Umarım kötü Belalılar bugün peşime takılmaz."},{"a":"argon","t":"Pardon hanımefendi! Siz de mi kayboldunuz?"},{"a":"malady","t":"Dur... yaklaşma!"},{"a":"argon","t":"Ne?"},{"a":"argon_stone","t":"..."},{"a":"malady","t":"Medusa'nın laneti yüzünden gözlerimin içine bakarsan sonsuza dek bir taşa dönüşürsün."},{"a":"malady","t":"Her ne kadar... iyi birine benziyor olsan da."},{"a":"malady","t":"...Üzgünüm."}]},{"id":"malady_02","i":2,"title":"Mermer Adam","req":"malady:2","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"*Hnnng*... İhtiyar... Owen..."},{"a":"elderowen","t":"Lilu! Ne yapıyorsun, ne diye o heykeli sağa sola sürüklüyorsun?"},{"a":"elderowen","t":"Ne heykeliymiş o... Argon mu?"},{"a":"lilu","t":"Huff... Huff... Heykel değil bu. Argon'un ta KENDİSİ!"},{"a":"elderowen","t":"Ah canım. Taşlaşmış mı?"},{"a":"lilu","t":"Sanırım. Onu bu hâlde Kronos Harabeleri'nde buldum."},{"a":"lilu","t":"Yolun bir kısmında Rudo taşımama yardım etti neyse ki!"},{"a":"elderowen","t":"Bak sen şu işe. Onu iyileştirebilecek misin?"},{"a":"lilu","t":"Muhtemelen! Gerçi malzemeler çok nadir, yani kolay olacağını sanmıyorum."},{"a":"lilu","t":"Şehirlileri toplamaya gidiyorum! Argon sana emanet!"},{"a":"elderowen","t":"Tabii ki. Umarım bir süreliğine bahçe süsü olmak seni üzmez evlat."},{"a":"argon_stone","t":"..."},{"a":"elderowen","t":"Ah, lanet olası güvercinler! Gidin bakayım!"}]},{"id":"malady_03","i":3,"title":"Göze Göz","req":"malady:3","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"...Bu Aşırı Uzamış Sarmaşık yeterince olgun olmalı. Sayıları da oldukça azaldı..."},{"a":"lilu","t":"Sıradaki... Medusa kanı. Hiç kolay olmayacak."},{"a":"malady","t":"Şey..."},{"a":"lilu","t":"Ay! Canavar!"},{"a":"malady","t":"...Sen şu insanın arkadaşı mısın?"},{"a":"lilu","t":"Argon mu? Bir dakika onu SEN mi dönüştürdün?"},{"a":"lilu","t":"Bu işimi FAZLASIYLA kolaylaştırdı. Benim de tam biraz Medusa kanına ihtiyacım vardı..."},{"a":"malady","t":"Hayır! Dur! Amacım zarar vermek değil."},{"a":"lilu","t":"Ben de inandım! Onu taşa dönüştürdün!"},{"a":"malady","t":"...Özür dilerim. Korkmuştum, sonra da göz göze geldik."},{"a":"malady","t":"Ne yapacağımı bilemedim... Daha önce kimse bana nazik davranmamıştı."},{"a":"lilu","t":"...Aman, zor zamanlar geçirmişsin."},{"a":"malady","t":"Kana ihtiyacın varsa sana verebilirim."},{"a":"malady","t":"Karşılığında, lütfen... beni de yanında götür. Ondan özür dilemek istiyorum."},{"a":"lilu","t":"Hoşuma gitmiyor ama tamam. Yine de taşa dönüşürsem Donovan'ın bizi kurtaracağını sanmıyorum."},{"a":"lilu","t":"Ben sana göz kulak olacağım ama sen gözlerini benden uzak tut!"},{"a":"malady","t":"...Kabul. Teşekkür ederim."}]},{"id":"malady_04","i":4,"title":"Ete Dönüş","req":"malady:4","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"Tamamlandı! Bu iksir işe yaramalı. Şıpır Şupur!"},{"a":"argon","t":"...Aaaah! Esnemek çok iyi geldi!"},{"a":"argon","t":"Bekle. Ne oldu?"},{"a":"lilu","t":"Malady, seni yanlışlıkla taşlaştırdı ve onun için özür dilemek istiyor."},{"a":"malady","t":"Me-merhaba. Üzgünüm. İsteyerek olmadı..."},{"a":"argon","t":"Sıkıntı yok! Harika hissediyorum! Biraz tutulmuşum o kadar..."},{"a":"argon","t":"Adın Malady mi? Ben Argon, tanıştığıma memnun oldum!"},{"a":"argon","t":"Bandanan kaymış, dur yardım edeyim!"},{"a":"lilu","t":"Argon! Dur!"},{"a":"argon_stone","t":"..."},{"a":"lilu","t":"Argon... Ona Medusaları anlatmalıyım sanırım..."},{"a":"malady","t":"Olamaz! Çok üzgünüm!"},{"a":"lilu","t":"Üzülme. Bu onun hatası."},{"a":"malady","t":"Te-tekrar kanımı alabilirsin..."},{"a":"lilu","t":"Medusa fizyolojisine çok hakim değilim ama tekrar kan vermeden önce birkaç gün beklemelisin."},{"a":"lilu","t":"Bu süreçte burada kal. Zayıflamış halinde gezmen güvenli olmaz."},{"a":"lilu","t":"Güçlerini ele aldığımızda... İhtiyar Owen'a sorsak daha iyi olacak gibi."},{"a":"malady","t":"...Evet."}]},{"id":"malady_05","i":5,"title":"Evine Hoş Geldin","req":"malady:5","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"İhtiyar Owen, biz geldik!"},{"a":"elderowen","t":"Argon iyileşti mi? Harika haber!"},{"a":"lilu","t":"Tam olarak... değil..."},{"a":"malady","t":"..."},{"a":"elderowen","t":"Tanrıça adına! Bir Medusa, hem de burada!"},{"a":"lilu","t":"Adı Malady. Argon'u iyileştirmeme yardım etti!"},{"a":"lilu","t":"Argon'u yeniden iyileştirebilmemiz için birkaç gün burada kalmalı."},{"a":"elderowen","t":"Anladım... Senden pek bir kötülük hissetmiyorum. Verdiğim tepki için özür dilerim Malady."},{"a":"malady","t":"Lanetim yüzünden... herkes benden nefret ediyor, diğer canavarlar bile. O yüzden bu tepkilere alışığım."},{"a":"elderowen","t":"Şehrin kapıları toplumun iyiliği için çalışmak isteyenlere her zaman açıktır."},{"a":"malady","t":"...Gerçekten mi?"},{"a":"elderowen","t":"Gözlerini kapalı tuttuğun sürece, herhangi bir sorun çıkacağını sanmıyorum."},{"a":"elderowen","t":"Malady... Umarım buradaki günlerin kendi türünün yanında geçirdiğin günlerden daha iyi olur."},{"a":"malady","t":"Teşekkür ederim... Daha önce hiçbir yerde hoş karşılanmamıştım."},{"a":"elderowen","t":"Yakında dükkâna gidebilirsin. Orada senin gibi gençler için her zaman yapılacak bir iş bulunur."},{"a":"lilu","t":"Doğru! Bizimle görevlere gelebilirsin!"},{"a":"malady","t":"Tamamdır... Teşekkür ederim Lilu ve Owen."}]}]},{"id":"polonia","name":"Polonia","chapters":[{"id":"polonia_01","i":1,"title":"Yetenekli Acemi Denizci","req":"polonia:1","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"polonia","t":"Acemi denizciler, demir alıyoruz!"},{"a":"polonia","t":"Hiç açık denizlere yelken açıp macera dolu korsan masallarının kahramanı olmayı hayal ettiniz mi?"},{"a":"polonia","t":"Ben, Kaptan Polonia Del Monte, gemime mürettebat topluyorum!"},{"a":"polonia","t":"Efsanelere konu olmuş korsan Baross Del Monte'nin kızı olarak size ganimet ve macera dolu bir yolculuğun garantisini veriyorum!"},{"a":"argon","t":"Kaptan Polonia, değil mi?"},{"a":"polonia","t":"Aynen. İlgileniyor musun? Senin gibi enfes lokmalara kapımız açık."},{"a":"argon","t":"Lo-lokma mı?"},{"a":"argon","t":"Şey, bu işle ilgilendiğim söylenemez! Ben Argon, eğitimi devam eden bir şövalyeyim!"},{"a":"argon","t":"Korsanlık yasa dışı bir faaliyet... Senden kendi rızanla teslim olmanı rica ediyorum!"},{"a":"polonia","t":"Hay canına yandığım! Kahrolası bir şövalye..."},{"a":"polonia","t":"Yanlışın var, ben yasal bir korsanım... Hani şu Robin Hood misali."},{"a":"polonia","t":"Zenginden alıp fakire veriyorum."},{"a":"argon","t":"Vay! Oldukça asil bir vazife! Yolun açık olsun!"},{"a":"polonia","t":"Yırttık desene."},{"a":"tavern","t":"Bugün de şansın yaver gitmedi demek?"},{"a":"polonia","t":"Bilirsin, açık denizlerde yaşam çetindir."}]},{"id":"polonia_02","i":2,"title":"Del Monte Masalı","req":"polonia:2","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"tavern","t":"Bugünlük mürettebat toplama işini sonlandırdın mı Polonia?"},{"a":"polonia","t":"Boşa kürek çekiyorum. Benden korsan kaptanı falan olmaz, Del Monte adına bile layık değilim..."},{"a":"tavern","t":"Şu Baross Del Monte denen adam, büyükbaban öyle mi?"},{"a":"polonia","t":"Aynen! Efsanelerin efsanesi! Günümüzde korsan olarak ekmek parası kazanmak zor..."},{"a":"polonia","t":"Artık tüm tüccar gemilerinde bizim gibi deniz kurtlarını şıp diye atlatmaya yarayan büyülü tespit araçları var."},{"a":"polonia","t":"Tabi Baross'u atlatamazlardı! Büyülüymüş, büyüsüzmüş demez, sislerin arasından fark edilmeden vurgun yapardı!"},{"a":"polonia","t":"Değerli neleri var neleri yok yağmalar geriye de akıllardan çıkmayacak o çınlayan kahkahasını bırakırdı..."},{"a":"polonia","t":"Onca korsan elini ayağını çekse de o, yıllarca denizlerde korku salmaya devam etti!"},{"a":"tavern","t":"Böylesine büyük bir mirası yaşatmak gerek!"},{"a":"polonia","t":"Aynen! Her seyahatinden sonra da minik torununa ayıracak vakti hep olurdu, serüvenlerini anlatarak onu eğlendirirdi..."},{"a":"polonia","t":"Siyah bayrak göndere! Topları ateşleyin! Herkes sağ tarafa, yağmalamaya hazırlanın!"},{"a":"tavern","t":"Sağ taraf mı? Sancak değil miydi o?"},{"a":"polonia","t":"Of! Lanet olsun! Şu havalı kostümüm dışında korsan gibi konuşmaya çabalayan acemi bir denizciyim."},{"a":"polonia","t":"Zaten gemisi olmayan korsan mı olur?"},{"a":"tavern","t":"Gemin yok mu? Belki de işe bir gemi edinerek başlayabilirsin."},{"a":"polonia","t":"Ha?"},{"a":"tavern","t":"Gemisiz bir kaptanın kolay kolay mürettebat toplayabileceğini sanmıyorum!"},{"a":"tavern","t":"İhtiyacın varsa, sanırım o gemiye sahip olmanı sağlayacak doğru kişiyi biliyorum."},{"a":"polonia","t":"Cidden mi?"},{"a":"polonia","t":"Korsan Bayrağı adına, teşekkürü borç bilirim tavernanın hanımı! Kaptan Polonia yapılan iyiliği unutmaz!"},{"a":"tavern","t":"İnan bana, ben de hatırlatmasını bilirim."}]},{"id":"polonia_03","i":3,"title":"Gerçek Gemi Yapımcısı","req":"polonia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"carpenter","t":"Benden koca bir gemi mi inşa etmemi istiyorsun?"},{"a":"polonia","t":"Aynen. Yapabilir misin?"},{"a":"carpenter","t":"Şüphen olmasın! Bu gemi başyapıtım olacak! Önce şu planlara bir bakayım."},{"a":"carpenter","t":"Hımm... Epey özenli çizilmiş. Peki şu karalamalar da nesi?"},{"a":"polonia","t":"Kendi el yazım. Okuyamıyorum."},{"a":"carpenter","t":"Şimdi anlaşıldı. Yine de, bu planlar yeter de artar."},{"a":"polonia","t":"Yelkenler fora! Baross ve Bonaventura'dan beri bu denizlerin gördüğü en görkemli gemi olacak!"},{"a":"carpenter","t":"Gerçi para mevzusunu konuşmadık. Tüm bu masrafları karşılayabilecek misin?"},{"a":"polonia","t":"Aynen, korsan altını konusunda derdin olmasın. Gemiyi yap, seni ganimete boğayım."}]},{"id":"polonia_a","i":3,"title":"Destek Arayışı","req":"polonia:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Şans Jetonları"},"side":true,"lines":[{"a":"polonia","t":"Rast gele güzel leydim. Şifacı olduğunu duydum, doğru mudur?"},{"a":"priest","t":"Ah, evet! Ben Freyja, bu tapınakta rahibe..."},{"a":"polonia","t":"Bacağımı kes."},{"a":"priest","t":"Anlamadım?"},{"a":"polonia","t":"Senden bacağımı kesmeni istedim!"},{"a":"priest","t":"Aman yarabbi, olmaz! Kim böyle bir şey ister ki?"},{"a":"polonia","t":"Korsan olacağım! Kahrolası tahta bacağı olmayan korsan kaptanı mı olur?"},{"a":"polonia","t":"Bacağımı kesip büyülü ellerinle diksen yeter!"},{"a":"priest","t":"Hayatta olmaz. Hiçbir insanın kılına zarar vermeyeceğime dair Tanrıça'ya ant içtim!"},{"a":"polonia","t":"Of! İşe yaramazlar sürüsü! Öyle olsun! Ama sana zırnık koklatmayacağımı bilesin!"},{"a":"priest","t":"Ne tuhaf bir kız."}]},{"id":"polonia_04","i":4,"title":"Kaptanın Payı","req":"polonia:4","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"polonia","t":"Şu yetilerin yaşadığı bölge ganimetle dolup taşıyor! Vakit kaybetmeden geminin ödemesini yapacağım!"},{"a":"leather","t":"Pekâlâ dostum, geldim. Benim görevim nedir?"},{"a":"polonia","t":"Karşında Kaptan Polonia var bahriyeli!"},{"a":"leather","t":"Ayıpsın kaptan dostum. Ne yapmamı istiyorsun?"},{"a":"polonia","t":"Bana araban lazım. Ben şu yetileri soyup soğana çevireceğim, sen de ganimeti taşıyacaksın."},{"a":"leather","t":"Vay be kaptan dostum, şu güzelim, kürklü yaratıkları mı soyacaksın?"},{"a":"polonia","t":"Aynen. Nedense ellerinde Savaş Çekici ve Makaralı Yay gibi bir sürü değerli eşya var."},{"a":"leather","t":"Peki kaptan dostum, postlarını ne yapacaksın? Onları ben alabilir miyim?"},{"a":"polonia","t":"Haddini bil bahriyeli! Korsanlar kimseyi öldürmez, yalnızca yağmalar!"},{"a":"leather","t":"Çok yazık."},{"a":"polonia","t":"Hiç de değil. Kurbanlarını hayatta bırakırsan, zamanla tekrar ganimet toplarlar, sen de gidip tekrar yağmalarsın. Ekonomiye giriş 101!"},{"a":"polonia","t":"Payını istiyorsan hareket zamanı bahriyeli!"},{"a":"leather","t":"Hayhay kaptan dostum."}]},{"id":"polonia_05","i":5,"title":"Geminin İlk Seferi","req":"polonia:5","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"carpenter","t":"İşte, hayatımın işi, başyapıtım!"},{"a":"polonia","t":"Bu... Bu çok güzel. Bu deniz kurdunu sevinç gözyaşlarına boğdun."},{"a":"carpenter","t":"Gerçekten güzel değil mi? Birkaç yere müdahale etmek zorunda kaldım, özellikle topların çanaklığın üstüne yerleştirilmesi konusundaki ısrarın yüzünden..."},{"a":"carpenter","t":"Ama gayet iyi olmuş, öyle değil mi?"},{"a":"polonia","t":"Gayet iyi olmuş ahbap! İşte sonuna kadar hak ettiğin korsan altınları."},{"a":"carpenter","t":"Kesinlikle hak ettim! Son bir şey. Usta bir marangoz olsam da kıyafet ve kumaş işi beni aşıyor."},{"a":"carpenter","t":"Yelkenin olmadan da limandan kolay kolay ayrılamazsın!"},{"a":"polonia","t":"Kaptanın olarak göğsümü yeterince kabarttığını söylemeliyim ahbap. Ama yelkenim hazır."},{"a":"carpenter","t":"Vay canına! İşte ben buna sanat eseri derim! Hem de büyülü! Bunu nerede buldun?"},{"a":"polonia","t":"Büyükbabam Baross'un yadigârı. Bir zamanlar gemisi Bonaventura'da dalgalanan yelkenin ta kendisi!"},{"a":"carpenter","t":"Olağanüstü yelkenliye olağanüstü bir son dokunuş!"},{"a":"carpenter","t":"Pekâlâ, Kaptan Polonia, Muhteşem Allan emrine amade!"},{"a":"polonia","t":"Gemime Muhteşem Allan adını mı koydun? Orada bir dur..."},{"a":"polonia","t":"Şu gemi başı süsü... O sen misin? Hem de çıplak!"},{"a":"carpenter","t":"Ha ha ha! Bu denli mükemmel bir gemiye cuk oturacak kusursuz bir süs!"}]},{"id":"polonia_b","i":5,"title":"Sıvışma!","req":"polonia:5","reward":{"k":"tokens","id":"tokens","q":3,"n":"Şans Jetonları"},"side":true,"lines":[{"a":"polonia","t":"Rast gele, işte buradasın."},{"a":"wood","t":"Evet, ne vardı?"},{"a":"polonia","t":"Bacağımı kes."},{"a":"wood","t":"Hayhay."},{"a":"polonia","t":"Dedim ki... Bir dakika, kabul ediyor musun?"},{"a":"wood","t":"Evet, tabii. Bacağını bu şekilde sabit tut, sonra da kadim baltamın marifetine nail ol."},{"a":"polonia","t":"Şey, dur bir dakika!"},{"a":"wood","t":"Biraz acı çekeceksin ama sen dayanıklı bir kızsın, değil mi?"},{"a":"wood","t":"Turnikeyi iyi yaptığından emin ol. Kan kaybetmeni istemeyiz."},{"a":"polonia","t":"Dur ahbap! Ağır ol!"},{"a":"polonia","t":"Ben... Yani gemim çok yakında yelken açıyor! Ben-benim gidip onu yakalamam lazım! Görüşmek üzere ahbap!"},{"a":"wood","t":"Bak sen şu işe! Bu insanlarla da bir dakikam bile sıkıcı geçmiyor."}]},{"id":"polonia_06","i":6,"title":"Denizlerin Mirası","req":"polonia:6","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"sia","t":"Kralım, size kötü bir haberim var."},{"a":"king","t":"Yo hayır! Kayıp Altın Şehir'deki altınlar mı tükendi yoksa?"},{"a":"sia","t":"Neyse ki o kadar kötü değil."},{"a":"sia","t":"Ama korkarım ki işgüzar bir korsan sizin kişisel ticari filonuzu yağmalıyor."},{"a":"sia","t":"Hırsızlığın 100 trilyon altın kadar olduğunu tahmin ediyoruz."},{"a":"king","t":"Tanrıça aşkına! Peki ya filomun son teknoloji büyülü korsan tespit sistemi ne durumda?"},{"a":"sia","t":"Görünüşe bakılırsa son derece verimsiz. Aynı muhteşem Baross'un kendisi gibi, bu gemi en iyi büyülerimizi bile atlatıyor..."},{"a":"sia","t":"Denizde kaybolmadan önce altınlarınızı yağmaladılar."},{"a":"king","t":"Kesinlikle barbarca! Peki ya mürettebat?"},{"a":"sia","t":"Bağışlandı Kralım. Direnç göstermemeyi kabul ettikleri sürece."},{"a":"king","t":"O hâlde altın ufak bir bedel. Servetim eski haline gelene kadar köylülerle aynı yemeği yiyeceğim!"},{"a":"king","t":"Peki ne kadar sürer bu iş?"},{"a":"sia","t":"Yaklaşık 2 gün Kralım."},{"a":"king","t":"Gerçekten de karanlık zamanlar..."}]},{"id":"polonia_07","i":7,"title":"Kıyıdan Ayrılış","req":"polonia:7","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"polonia","t":"Yo ho ho! Kaptan Polonia karaya çıkıyor! İçecekler benden!"},{"a":"tavern","t":"Polonia! Yoksa şey mi demeliyim... Kaptan Polonia! \"İşler\" tıkırında gidiyor galiba?"},{"a":"polonia","t":"Siz kara insanları buna emin olun! Bu denizler tam yağmalanmalık!"},{"a":"polonia","t":"Benim gemi nereye giderse, büyükbabamın yelkenleri de görmediğim bir hızla rüzgârı yakalar!"},{"a":"tavern","t":"Eminim Baross gurur duyardı. Peki ya bu... Yasa dışı malları nasıl harcamayı planlıyorsun?"},{"a":"polonia","t":"Her iyi korsan gibi. Mürettebatımla birlikte oraya buraya gömerek."},{"a":"tavern","t":"Aaah! Hazine haritaları! Ne kadar heyecan verici!"},{"a":"polonia","t":"Aynen, korsan dediğin böyle olur. Sincaplar gibi soğuk kış ayları için birazını kenarda tutarsın."},{"a":"tavern","t":"Peki ya gerisi?"},{"a":"polonia","t":"Tapınaktaki güzel bir hanıma verdim."},{"a":"tavern","t":"Yetimhaneye bağış mı yaptın? Seni hiç hayırsever bir tip olarak düşünmemiştim."},{"a":"polonia","t":"Yeti ne?"},{"a":"tavern","t":"Ah, boş ver. Sana ne getirmemi istersin Kaptan?"},{"a":"polonia","t":"Deniz Kurdu Birası, en sevdiğim! Ve onu kaldırabileceğini düşünen tüm acemi denizcilere de bir tane..."},{"a":"polonia","t":"Sonraki tur benden! Baross ailesi denize döndü! Yelkenler fora!"}]},{"id":"polonia_08","i":8,"title":"Geçmişten Gelen Fısıltılar","req":"polonia:8","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"polonia","t":"Bir sonraki dalışına hazır mısın denizci?"},{"a":"baker","t":"Tabii ki kaptan! Ama demeden geçemeyeceğim..."},{"a":"baker","t":"Su altı keşiflerinde sana her zaman seve seve yardımcı olurum ama buraya korsanlık yapmaya gelmedim!"},{"a":"polonia","t":"Endişelenme ya ahbap. Görevimiz keşif. Kaptanın mıntıkasını genişletiyor."},{"a":"polonia","t":"Bugün korsanlık yok ama şansımız yaver giderse karşımıza yağmalayacak bir batık gemi çıkar belki! Yelkenler fora!"},{"a":"baker","t":"Kaptan? Şu ufuktaki ne gemisi?"},{"a":"polonia","t":"Bakayım. Telaşlanma denizci. Bonaventura o! Büyükbabamın gemisi."},{"a":"baker","t":"Emin misin? Çok yıkık dökük görünüyor..."},{"a":"polonia","t":"Neptün'ün sakalı adına! Bonaventura bu ya! Ama bu imkânsız! Benim büyükbabam çoktan öldü!"},{"a":"polonia","t":"Dostlar! Planda bir değişiklik oldu! BU GEMİNİN PEŞİNDEN GİDİYORUZ!"}]},{"id":"polonia_09","i":9,"title":"Akıntıya Kapılmış Bir Efsane","req":"polonia:9","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"baker","t":"Bir gün terk edilmiş bir gemiye bineceğimi hiç düşünmezdim."},{"a":"polonia","t":"Bastığın yere dikkat et denizci. Gemi kötü durumda."},{"a":"baker","t":"Açıkçası ben yüzmeyi tercih ederdim! Bu gemide ne işimiz var ki zaten?"},{"a":"polonia","t":"Ne demek ne işimiz var? Bu Baross'un Bonaventura'sı!"},{"a":"polonia","t":"Burada ne olduğunu çözmem gerek... Bu terk edilmiş gemi denizde olmamalı..."},{"a":"baker","t":"Hayalet gemi desene şuna."},{"a":"polonia","t":"Korkutma beni! Hayalet diye bir şey yok!"},{"a":"baker","t":"Şeye ne demeli peki? Zo..."},{"a":"polonia","t":"Kapat bakayım çeneni ahbap. İpucu bulmaya çalışıyorum."},{"a":"baker","t":"Şuradaki defter biraz ürpertici gözüküyor..."},{"a":"polonia","t":"Ah, kaptanın seyir defteri!"},{"a":"baker","t":"Sanki gözünü dikmiş de sana bakıyor gibi... Değil mi?"},{"a":"polonia","t":"Sen benimle geliyorsun deftercik. Gözünüzü başka şeyler için de dört açın korsanlar."},{"a":"polonia","t":"Saçıma dokunup durmasan olur mu ahbap?"},{"a":"baker","t":"Ben ta buradayım kaptan."},{"a":"polonia","t":"AAAA! Gemiyi terk edin!"}]},{"id":"polonia_10","i":10,"title":"Korsan Mirası","req":"polonia:10","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"polonia","t":"Kaptanınız tekrar gemide tayfam. Yelkenleri açın, gidiyoruz."},{"a":"baker","t":"Baksana kaptan! Bonaventura batıyor!"},{"a":"polonia","t":"Üstüme iyilik sağlık! Nasıl olur? Bunca zamandan sonra hem de? Gemiyi suda tutan defter miydi yoksa?"},{"a":"baker","t":"Belki de defter görevini tamamlamıştır."},{"a":"polonia","t":"Ah Baross, seni gidi deniz kurdu... Nasıl bilebildin bunu?"},{"a":"baker","t":"Seyir defteri ne diyor Polonia?"},{"a":"polonia","t":"Doğru ya, bir bakayım..."},{"a":"polonia","t":"..."},{"a":"polonia","t":"Senden bir iyilik daha isteyeceğim denizci."},{"a":"baker","t":"Ah tabii, ben senin için okuyayım defteri."},{"a":"baker","t":"Hımm... Burada su altındaki bir yerin konumu tarif ediliyor gibi."},{"a":"polonia","t":"Su Altı Tapınağı mı? Orayı biliyoruz zaten."},{"a":"baker","t":"Yok, oradan çok daha uzakta... Kayıp Altın Şehir diye bir yer..."},{"a":"baker","t":"Kayıp Altın Şehir su altında değil gerçi..."},{"a":"polonia","t":"Yani sadece bir hikâye değil miymiş? Gerçek miymiş orası?"},{"a":"polonia","t":"Sen yüzmeyi biliyorsun denizci. Kader bu."},{"a":"polonia","t":"Hikâyeler gerçekse... beni oraya götürdüğüne pişman olmayacaksın."}]},{"id":"polonia_11","i":11,"title":"Batık Altın Şehir","req":"polonia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"baker","t":"Oh be! Geldik! Nasılsın kaptan?"},{"a":"polonia","t":"Öhö, öhö..."},{"a":"polonia","t":"Of... Bir deniz insanı için bacakların pek kuvvetliymiş..."},{"a":"baker","t":"İyi ki öyle! Giriş çok derinde, hiçbir insan buraya ulaşamazdı bence."},{"a":"polonia","t":"Haklısın! Ben neredeyse boğuluyordum. Bir daha asla buraya dönmeyeceğim..."},{"a":"baker","t":"Tanrıça aşkına... Etrafına bir baksana Polonia!"},{"a":"polonia","t":"Sakallı midyeler aşkına... Batık Altın Şehir..."},{"a":"polonia","t":"Burası... Hiç böyle bir yer görmemiştim..."},{"a":"baker","t":"Burası hazine kaynıyor! Altınlar, inciler... Kayıp Altın Şehir buranın yanında solda sıfır kalır!"},{"a":"polonia","t":"Büyükbabam hayatı boyunca burayı aradı..."},{"a":"baker","t":"Sonunda karaya hiçbir şey taşıyamayınca da her şeyi en sevdiği torununa bıraktı."},{"a":"polonia","t":"Ühü... Gözlerim yaşardı..."},{"a":"baker","t":"Biraz soluklanmak ister misin kaptan?"},{"a":"polonia","t":"Dalga mı geçiyorsun? Yağmalanacak tonla ganimet var! Sen de az önce ikinci kaptanlığa terfi edildin. Biraz kulaç atmaya hazır mısın?"},{"a":"baker","t":"Hem çuvallarca ganimet hem de bir korsanı mı taşıyacağım? Biraz esneme hareketi yapayım en iyisi!"}]},{"id":"polonia_epilogue","i":12,"title":"Son Söz","req":"polonia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"polonia","t":"Hımm..."},{"a":"baker","t":"Yine mi yüzeceğiz Polonia?"},{"a":"polonia","t":"Yok ahbap. Büyük bir sorunum var."},{"a":"polonia","t":"Çok fazla param var! Yakında paramı gömecek sahil bulamayacağım."},{"a":"baker","t":"Açıkçası payıma düşen para beni de biraz bunaltıyor!"},{"a":"baker","t":"Ah, hazır lafı açılmışken..."},{"a":"baker","t":"Batık Bonaventura'nın orada yüzüyordum da..."},{"a":"baker","t":"Pek kayda değer bir şey yoktu ama bu göz bandını buldum. Tanıdık geldi mi?"},{"a":"polonia","t":"İkinci kaptan! Bu Baross'un göz bandı!"},{"a":"polonia","t":"Vay be! Çok sevindim, seni öpsem yeridir!"},{"a":"baker","t":"Asıl ben sevindim kaptan. Eminim büyükbaban da böyle olsun isterdi."},{"a":"polonia","t":"Ne diyeceğim... Su altını yağmalamayı bırakıyorum."},{"a":"polonia","t":"Korsanın evi denizdir, altın şehir falan değil! İçinde ne kadar ganimet olursa olsun..."},{"a":"polonia","t":"Büyük Baross'un \"torunu olarak Batık Altın Şehir ve kalan tüm ganimetleri benim sana hediyem."},{"a":"polonia","t":"Tüm yaptıkların için teşekkürler ikinci kaptan. Korsanlık hakkındaki fikirlerini değiştirirsen aramıza katılmana seviniriz."},{"a":"baker","t":"Teşekkür ederim kaptan. Birlikte atıldığımız maceraları hiç unutmayacağım!"},{"a":"baker","t":"Tutu Mano ile tatile çıkma işini bir daha konuşsam iyi olacak herhâlde!"}]}]},{"id":"king","name":"Reinhold","chapters":[{"id":"king_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"sia","t":"Kral Reinhold..."},{"a":"king","t":"Görünen o ki görev bir türlü yakamı bırakmıyor!"},{"a":"sia","t":"Yakanıza yapıştı demek daha doğru olur. Yabancı liderler sizi bekliyor."},{"a":"king","t":"Elveda dostum! Geri döneceğim!"},{"a":"sia","t":"Ben, pek sanmıyorum."}]},{"id":"king_01","i":1,"title":"Kralın Sarayı","req":"king:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Şans Jetonları"},"side":false,"lines":[{"a":"king","t":"Kralın sarayı açıldı! Talepte bulunmak isteyenler buyursun!"},{"a":"rudo","t":"Hıh."},{"a":"king","t":"Reinhold krallığı bugün halkı için ne yapabilir, büyük... ayı adam?"},{"a":"rudo","t":"Bence tüm büyüleri yasaklayıp büyücüleri de kovmalısınız."},{"a":"king","t":"Ah... O biraz... Yani..."},{"a":"king","t":"Biz... Bu önerini değerlendireceğiz! Sıradaki!"},{"a":"herbs","t":"Selaaam! Bence her günü PİNYATA GÜNÜ ilan etmeliyiz!"},{"a":"king","t":"Ne güzel bir fikir! Hatta bence..."},{"a":"sia","t":"..."},{"a":"king","t":"...bu konuyu uzun uzun tartışabiliriz! Geldiğin için teşekkürler!"},{"a":"king","t":"Sia, bugün görüşeceğimiz kaç kişi kaldı?"},{"a":"sia","t":"Elli beş, Majesteleri."},{"a":"king","t":"Eyvah."}]},{"id":"king_02","i":2,"title":"Altın Kalpli Ahmak","req":"king:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Şans Jetonları"},"side":false,"lines":[{"a":"donovan","t":"Affedersiniz, bu koltukta oturan biri var mı?"},{"a":"sia","t":"Günümü zehir etmeye mi geldin Donovan?"},{"a":"donovan","t":"Beni üzüyorsun Sia. İmparatorluğun bir vatandaşı olarak diğer bir vatandaşla sohbet etmeye geldim."},{"a":"donovan","t":"Ahmak Kralımız bugünlerde nasıl?"},{"a":"sia","t":"Casusluk becerilerin paslanıyor herhalde Donovan. Reinhold sandığının aksine ahmak biri değil."},{"a":"sia","t":"Yüzünde bir gülümseme olsa da halkı için çok fazla fedakârlık yapıyor."},{"a":"sia","t":"İmparatorun... BİZİM İmparatorumuzun da bunu öğrenmesi gerek."},{"a":"sia","t":"Şu ana dek görevim onun kendini halkı için harap etmesini engellemek oldu."},{"a":"donovan","t":"Demek öyle... Etkileyici."},{"a":"sia","t":"Evet, o altın kalpli bir ahmak. Ama onu küçük göreceksen dikkatli olmalısın."}]},{"id":"king_03","i":3,"title":"Sarayda Fazla Mesai","req":"king:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Şans Jetonları"},"side":false,"lines":[{"a":"king","t":"Of! Bu rapor yığını hiç küçülmüyor sanki, haksız mıyım?"},{"a":"sia","t":"Sanırım yine sabahlayacağız."},{"a":"king","t":"Bana yardım ettiğin için teşekkür ederim sevgili Sia!"},{"a":"sia","t":"Lafı bile olmaz Majesteleri. Şimdi, sıradaki raporda..."},{"a":"sia","t":"Southburg'deki çiftçiler hasat dönemi kötü geçtiği için vergilerin tamamını ödeyememişler."},{"a":"sia","t":"Hatırladığım kadarıyla bu iki oldu..."},{"a":"king","t":"Birkaç saray büyücüsünü araştırmaya gönder. Belki çiftçilerin topraklarına korkunç bir lanet musallat olmuştur."},{"a":"sia","t":"Muazzam bir çözüm."},{"a":"king","t":"Vergileri de tekrar affedilsin. Babam da böyle isterdi!"},{"a":"sia","t":"Elbette. Kral Keinan bence de böyle yapardı."},{"a":"king","t":"Ardında bıraktığı taç gerçekten de ağır..."},{"a":"king","t":"Sıradaki raporda ne var?"},{"a":"sia","t":"Komşu İmparatorlukla sınırda yaşanan gerginliklerden bahsediliyor..."}]},{"id":"king_04","i":4,"title":"Gölgelerden Korkmak","req":"king:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Şans Jetonları"},"side":false,"lines":[{"a":"king","t":"..."},{"a":"sia","t":"Majesteleri..."},{"a":"king","t":"Aman!"},{"a":"king","t":"Arkamda birden belireceksen lütfen önce geldiğini bildir!"},{"a":"sia","t":"Ah, o ninja saldırısını aklınızdan bir türlü çıkaramıyorsunuz, değil mi?"},{"a":"king","t":"Elbette! O gün kıl payı kurtulmuştum!"},{"a":"sia","t":"Muhafızları iki katına çıkarmamı ister misiniz?"},{"a":"king","t":"Bence... gerek yok. Ama artık lütfen bu kadar sessiz adımlarla yürüme!"},{"a":"sia","t":"Başüstüne Kralım."},{"a":"hemma","t":"Evim, güzel evim... Ha?"},{"a":"king","t":"AAAA! Ninjalar!"},{"a":"hemma","t":"Özür dileriz. Yanlış yere gelmişiz."},{"a":"hemma","t":"Gölge Translokasyonunda bazen hatalar olabiliyor."},{"a":"king","t":"L-lütfen benim taht odamda GÖLGE IŞINLANMANIZI kullanmayın!"},{"a":"sia","t":"Kral Reinhold? İyi misiniz?"},{"a":"king","t":"Evet! Lütfen bu... korkutucu ziyaretçimize çıkışı göster."},{"a":"sia","t":"Pekala. İleride böyle davetsiz misafirlere karşı kalenin güvenliğinin sağlandığından emin olacağım."},{"a":"hemma","t":"Burada çok eğlenceli bir Işınlanma Noktası bulduk. Buraya daha sonra tekrar gelelim."},{"a":"king","t":"Gelmeyin lütfen!"}]}]},{"id":"rudo","name":"Rudo","chapters":[{"id":"rudo_01","i":1,"title":"Yaşayan Dağ","req":"rudo:1","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"argon","t":"Uff... Soğuk havaya uygun giyinmedim ki! Neden tekrar geldik buraya?"},{"a":"lilu","t":"Buradaki cevherlerin olağanüstü özellikleri var çünkü! Grimar dedi ki..."},{"a":"argon","t":"Bir dakika Lilu! Baksana! Şurada bir Yeti ile kapışan bir adam var!"},{"a":"lilu","t":"Adam mı? Dağ kadar biri yahu!"},{"a":"lilu","t":"Yeti'yle güreşiyor mu o?"},{"a":"rudo","t":"Vay be. On üzerinden on."},{"a":"argon","t":"Nasıl savaştı ama! Harikaydınız bayım!"},{"a":"rudo","t":"Ha?"},{"a":"lilu","t":"Bayım, yaralanmışsınız! İyileştireyim sizi!"},{"a":"lilu","t":"<c1>İyil...</c1>!"},{"a":"rudo","t":"GERİ ÇEKİL!"},{"a":"rudo","t":"İyiyim ben. Kendi kendine iyileşir."},{"a":"rudo","t":"Böyle yerlere çoluk çocuğun gelmemesi lazım. Eve dönün."},{"a":"argon","t":"Vay be, adam büyüden cidden nefret ediyormuş."},{"a":"lilu","t":"Hayır... Gözlerinde gördüğüm şey korkunun ta kendisiydi."}]},{"id":"rudo_02","i":2,"title":"Tahliye İhtarı","req":"rudo:2","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"elderowen","t":"Sanırım anlayamadım..."},{"a":"rudo","t":"Meh! O moruk kulaklarını aç da anlamanı kolaylaştırayım!"},{"a":"rudo","t":"Bu şehirde yaşayan büyücü gözü dönmüş bir kaçık ve herkesin güvenliği için ondan kurtulmalıyız."},{"a":"elderowen","t":"Bunlar... Ne kadar ağır laflar..."},{"a":"rudo","t":"Daha dün bana Timotheus'a göz kulak olmamı söyledi..."},{"a":"rudo","t":"Hem de \"Tim\"in hayal dünyasında yaşadığını, kafasının karışık olduğunu ve gözetim altında tutulması gerektiğini iddia etti."},{"a":"rudo","t":"Bahsettiği *KİŞİ* Timotheus!"},{"a":"elderowen","t":"Hımm, evet. Anlıyorum."},{"a":"elderowen","t":"Sağlık \"durumuna\" rağmen, Timotheus Grimar bu şehrin ayrılmaz bir parçasıdır."},{"a":"elderowen","t":"Zararsız olduğu kadar yardımseverdir de. Korkulacak bir neden göremiyorum."},{"a":"lilu","t":"Usta Grimar'dan kurtulmak mı? O da nereden çıktı?"},{"a":"rudo","t":"Sen bu işe karışma kızım."},{"a":"lilu","t":"Olmaz! Usta Grimar güçlü bir büyücüdür ama asla kimseye zarar vermez!"},{"a":"rudo","t":"Yok ya! İyi! Bu kasabanın başına bir şey gelecek olursa uyarmadı demeyin."},{"a":"elderowen","t":"Tam bir baş belası."},{"a":"lilu","t":"Gözüm üstünde olacak..."}]},{"id":"rudo_03","i":3,"title":"Işıktan Doğan","req":"rudo:3","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"priest","t":"Affedersiniz... Bir şikâyetiniz mi vardı?"},{"a":"rudo","t":"Lanet olsun! Bu şehirde de kahrolası büyücülerden geçilmiyor..."},{"a":"priest","t":"Ah, Bay Rudo, değil mi?"},{"a":"rudo","t":"Bana dost ayakları yapma büyücü."},{"a":"priest","t":"Ben Tanrıçanın rahibelerinden biriyim, güçlerim bir büyücünün güçlerinden farklıdır."},{"a":"priest","t":"Hayatımı diğerlerini iyileştirmeye ve korumaya adayacağıma yemin ettim."},{"a":"rudo","t":"Boş laflara karnım tok. Siz Işıktan Doğanlar, hepiniz aynısınız."},{"a":"priest","t":"Işık meselesini biliyor musun?"},{"a":"rudo","t":"Öff. Unut gitsin. Ben gidiyorum."},{"a":"priest","t":"Konuştuklarımızı duydun mu Lilu?"},{"a":"lilu","t":"Evet, tamamını!"},{"a":"priest","t":"Derslerde Işık hakkında anlattıklarımı hatırlıyor musun?"},{"a":"lilu","t":"Elbette! Yalnızla Işıkla doğanlar büyü yapabilir ve bunları kontrol altında tutabilir."},{"a":"lilu","t":"Ancak bu olgu genelde halk tarafından pek bilinmez."},{"a":"priest","t":"Çok doğru! En parlak öğrencim olarak yine beni yanıltmadın!"},{"a":"priest","t":"İşte sorun da bu... Rudo bunu nereden öğrendi acaba?"},{"a":"lilu","t":"Hımm.. Sence?"}]},{"id":"rudo_04","i":4,"title":"Dükkân Soygunu","req":"rudo:4","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"polonia","t":"Heyamola! Kaptan Polonia bu sefer gerçekten turnayı gözünden vurdu!"},{"a":"polonia","t":"Bir kral mezarı tümüyle tarafınızdan yağmalanmaya hazır!"},{"a":"rudo","t":"Sessiz ol, denizci kız. İşim var."},{"a":"polonia","t":"Ya da hazır olabilirdi... TÜM GANİMETİ PARAMPARÇA EDEN eklem bacaklı vahşi bir savaşçı olmasaydı!"},{"a":"polonia","t":"Davy Jones adına derdin ne senin ahbap? Bunlar tonlarca korsan altını eder!"},{"a":"rudo","t":"Bu şey çok eski."},{"a":"rudo","t":"Sihirli."},{"a":"rudo","t":"Muhtemelen de lanetli."},{"a":"rudo","t":"Başkasına zahmet olmasın diye tümünü un ufak ediyorum."},{"a":"rudo","t":"Bu şehir sorunu göremeyecek kadar akılsızsa ben hallederim!"},{"a":"polonia","t":"Oy ahbap. Bu değnek GERÇEKTEN değerli görünüyor. Sakın..."},{"a":"rudo","t":"Hıh."},{"a":"rudo","t":"Ah."},{"a":"polonia","t":"Kraken aşkına! Sakın onu dizinle kırayım deme!"},{"a":"polonia","t":"Gerçi kırma işini değnek yapmış gibi görünüyor. Üzerinde bir çizik bile yok!"},{"a":"polonia","t":"Bacağın nasıl ahbap?"},{"a":"rudo","t":"İyi. Ama bu değnek göründüğünden daha sağlammış."},{"a":"rudo","t":"Nedense elimden de bırakamıyorum. Sanki... Elime yapışmış gibi."},{"a":"polonia","t":"Geminin cerrahı ben değilim ama adamakıllı lanetlenmiş görünüyorsun ahbap."},{"a":"polonia","t":"Şuna bir baktırsan iyi olur."},{"a":"rudo","t":"Tabii ki lanetli büyü. HER ZAMAN lanetli büyüdür zaten."},{"a":"rudo","t":"Pekâlâ. Ben kaçıyorum. Geri kalanını benim için sen kır."},{"a":"polonia","t":"Hayhay ahbap!"},{"a":"polonia","t":"Kırmak değil de kırıp geçmek diyelim. Bu korsan burayı bir güzel yağmalayacak."}]},{"id":"rudo_a","i":4,"title":"Aşk Acısı","req":"rudo:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Şans Jetonları"},"side":true,"lines":[{"a":"herbs","t":"Gorza!"},{"a":"gems","t":"Gorza!<sprite tint=1 name=Note2>"},{"a":"wood","t":"Selam Juniper. Maylee! Nasılsınız bakalım?"},{"a":"herbs","t":"Maylee ile gelecekteki beyaz atlı prensinden bahsediyorduk..."},{"a":"gems","t":"Ooo sabırsızlanıyorum!"},{"a":"herbs","t":"Merak ettik de... SEN beyaz atlı prensinle nasıl tanıştın?"},{"a":"wood","t":"Şu koca aptal Rudo hödüğüyle mi? Hıh!"},{"a":"wood","t":"Pek göstermese de bu adam bir hanımefendiyle nasıl konuşulacağını gerçekten biliyor."},{"a":"wood","t":"Dur bakayım... Şöyle oldu..."},{"a":"rudo","t":"Yola çıkmadan önce bir tane daha."},{"a":"tavern","t":"Peki... Rudo. Hiç yuva kurmayı düşündün mü?"},{"a":"rudo","t":"Sen işine bak Naya. Bunlara zamanım yok."},{"a":"tavern","t":"Aşk en beklemediğin anda kapıyı çalar! Kim bilir, hayallerinin kadını her an içeri girebilir..."},{"a":"rudo","t":"Yok canım! Beni yere seremeyecek bir kadınla işim olmaz."},{"a":"wood","t":"Bu bir meydan okuma mı koca adam?"},{"a":"rudo","t":"Şansını dene bakalım, sivri diş!"},{"a":"tavern","t":"Gorza lütfen sandalyeyi yerine bırak..."},{"a":"wood","t":"Buna ne dersin mankafa? Biraz daha ister misin?"},{"a":"rudo","t":"AAAAHH!!!"},{"a":"wood","t":"Vay!"},{"a":"wood","t":"Sonraki hafta evlendik. Gördüğüm en kanlı düğündü."},{"a":"herbs","t":"..."},{"a":"gems","t":"..."},{"a":"herbs","t":"Be-belki gidip başka birine sormalıyız."}]},{"id":"rudo_05","i":5,"title":"Lanetler ve Taşkınlıklar","req":"rudo:5","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"rudo","t":"Kıramam da ne demek?"},{"a":"master","t":"Ne dediysem onu kastettim sert arkadaşım, bu emaneti kıramam."},{"a":"rudo","t":"Bu cılız değneği kıramıyorsa çelik uçlu bir çekiç ne işe yarar!"},{"a":"master","t":"O kadar da güçsüz olmadığı kesin... Bence fazlasıyla şeytani görünüyor!"},{"a":"master","t":"Nereden baksan burada başka bir şey söz konusu, muhtemelen büyü..."},{"a":"rudo","t":"TABİİ Kİ büyü."},{"a":"rudo","t":"Her zaman lanetli büyüdür zaten."},{"a":"master","t":"Görünüşe göre bunu zaten biliyorsun! Neden benim yerime bu tür şeyleri bilen birine gitmiyorsun?"},{"a":"rudo","t":"Sihirbazlara güven olmaz... Azıcık bile."},{"a":"master","t":"Bu durumda bir seçeneğin olduğunu sanmıyorum çocuğum."},{"a":"master","t":"Üstelik, tatlı Lilu'ya nasıl olur da güvenmezsin? Çok sevimli biridir!"},{"a":"rudo","t":"O da sihirbaz, değil mi? Demek ki o da tıpkı diğerleri gibi."},{"a":"rudo","t":"Tehlikeli. Kötü. ALÇAK."},{"a":"master","t":"Nihayetinde bu değnekten kurtulmak istiyorsan sana yardım edebilecek tek kişi o."},{"a":"rudo","t":"Lanet olsun."}]},{"id":"rudo_06","i":6,"title":"Bihaber Büyücü","req":"rudo:6","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"rudo","t":"Selam Naya. Her zamankinden olsun."},{"a":"tavern","t":"Üzgünüm Rudo, içeriye silahla giremezsin. Kuralları biliyorsun."},{"a":"rudo","t":"Bu mu? Bu benim bastonum yahu."},{"a":"tavern","t":"Yok daha neler! Neyin büyülü değnek neyin baston olduğunu görünce anlıyoruz biz..."},{"a":"rudo","t":"Tamam, tamam... ama baksana, köküne kadar lanetli bu. Elimden bırakamıyorum."},{"a":"tavern","t":"Eyvah, eyvah! Hâl böyleyse ufak bir istisna yapalım madem. Sadece senin için tabii!"},{"a":"rudo","t":"Hıh. Teşekkürler."},{"a":"tavern","t":"Ee, ne yapacaksın peki bunu?"},{"a":"rudo","t":"Pek umurumda değil. Böyle yaşayıp gideceğim."},{"a":"tavern","t":"Cidden mi? Seni biraz huysuzlaştırmış bence. Mümkün olacağını düşünmezdim ama normalden de daha huysuzsun."},{"a":"tavern","t":"Hem gören senin bir tür sihirbaz olduğunu düşünür artık."},{"a":"rudo","t":"... Ne diyorsun sen? Sihirbaz mı?"},{"a":"tavern","t":"Tek eksiğin şöyle komik bir şapka! Ha, bir de tavırlarını düzeltsen tamamdır."},{"a":"rudo","t":"... Doğru diyorsun. Kurtulmam lazım bu değnekten. Hadi hoşça kal."},{"a":"tavern","t":"İyi günler. Bunu da hesabına yazıyorum!"}]},{"id":"rudo_07","i":7,"title":"Travmaya Bir Bakış","req":"rudo:7","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"rudo","t":"Önceki davranışlarım için özür dilerim. Bana yardım edebileceğini söylediler... Bu laneti kaldırmak istiyorum."},{"a":"lilu","t":"Şu değnek demek, ha... Çok fena görünüyor!"},{"a":"lilu","t":"Daha önce hiç lanet nötrleştirmeyi denememiştim ama yapabilirim herhâlde."},{"a":"lilu","t":"Hazır olduğuna emin misin? Çok gergin görünüyorsun."},{"a":"rudo","t":"... Evet."},{"a":"lilu","t":"Tamam! Odaklanmaya başlıyorum..."},{"a":"lilu","t":"Laneti görebiliyorum... Seni sarıp sarmalamış."},{"a":"lilu","t":"Dur, daha da derine gitmeliyim..."},{"a":"rudo","t":"... Ahh!"},{"a":"lilu","t":"Aa!"},{"a":"lilu","t":"Az önce bana yumruğu geçireceksin sandım ya!"},{"a":"rudo","t":"... Özür dilerim. Kasten yapmadım."},{"a":"lilu","t":"Yok, bu işe yaramayacak. Odaklanmam lazım sonuçta."},{"a":"rudo","t":"Peki, cidden kusura bakma. Başka bir yolunu bulurum artık."},{"a":"lilu","t":"Bir de Malady'ye sor istersen. Belki de o benim göremediğim bir şey görür."},{"a":"rudo","t":"Malady mi? Olabilir."},{"a":"lilu","t":"Yalnız tavırlarına dikkat et! Bilmen gereken... bazı özel durumlar var..."}]},{"id":"rudo_08","i":8,"title":"İki Kişilik Lanet","req":"rudo:8","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"rudo","t":"Malady Hanım, bir saniye bakabilir misin?"},{"a":"malady","t":"(Olamaz, Lilu beni onun hakkında uyarmıştı...)"},{"a":"malady","t":"Şey... üzgünüm. Bakabileceğimi sanmıyorum..."},{"a":"rudo","t":"Kusura bakma, korkutmak istemedim. Bu değnek hakkında bir şeyler biliyor musun?"},{"a":"malady","t":"Ben... büyüden nefret ettiğini sanıyordum."},{"a":"rudo","t":"Dünyada büyüden daha çok nefret ettiğim bir şey yok."},{"a":"rudo","t":"Ama sen de lanetli değil misin? Aynı benim gibi."},{"a":"rudo","t":"Büyüyü sen seçmedin. Senin suçun değil."},{"a":"malady","t":"...O hâlde değnek ile... konuşmayı deneyebilirim."},{"a":"malady","t":"..."},{"a":"malady","t":"...Bir tür parazit gibi. Senin kıvılcımından besleniyor."},{"a":"rudo","t":"O şey akıllı mı yani?"},{"a":"malady","t":"Bir bakıma öyle."},{"a":"malady","t":"Kıvılcımın son derece güçlü. Belki on yıllar sürebilir..."},{"a":"malady","t":"...ama bir ihtimal sendeki büyüyü alabilir..."},{"a":"rudo","t":"Hıh. Bundan emin olmazdım."},{"a":"rudo","t":"Yani tek istediği büyü emecek biri öyle mi?"},{"a":"malady","t":"Şey... evet. Aşağı yukarı öyle."},{"a":"malady","t":"Lütfen... Zaten lanetliyim..."},{"a":"rudo","t":"Hah! Aklından bile geçirme."},{"a":"rudo","t":"Yardımın için teşekkür ederim. Bir fikrim var..."}]},{"id":"rudo_09","i":9,"title":"Bir Askerin Geçmişi","req":"rudo:9","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"malady","t":"Şey... Gelebilir miyim?"},{"a":"veteran","t":"Ah, hakkında çok şey duyduğum Medusa."},{"a":"veteran","t":"İçeri gel çaylak. Kusura bakma, sana uygun bir sandalye yok."},{"a":"malady","t":"Sorun değil... Şu Rudo hakkında bir şeyler sormak istemiştim."},{"a":"veteran","t":"O koca ahmak mı? Sana zorbalık yapmadı, değil mi?"},{"a":"malady","t":"Hayır... Garip bir şekilde çok nazikti bana."},{"a":"veteran","t":"Gerçekten mi? Çok garip, büyüden nefret eder normalde."},{"a":"malady","t":"O yüzden geldim zaten. Nedenini... merak ettim."},{"a":"veteran","t":"Eskiden İmparatorluğun ordusunun birer parçasıydık. Eski silah arkadaşıyız."},{"a":"veteran","t":"Rudo \"gönüllü olarak\" bir deneye katıldı. Askerlere yapay olarak Işık eklemeye çalıştıkları bir deney yani."},{"a":"veteran","t":"Deney aşırı kötü sonuçlandı. O gün bugündür de bir daha eskisi gibi olmadı."},{"a":"malady","t":"Çok korkunç... "},{"a":"veteran","t":"Düşündüğünden çok daha kötüydü, öyle diyeyim sana. İlk fırsatta oradan kaçtık."},{"a":"malady","t":"Şey... İşe yaradı mı en azından? İçinde aşırı güçlü bir Işık olduğunu hissettim..."},{"a":"veteran","t":"Bilemiyorum. Nasıl olduğunu gördün. İmparatorun kendisi gelse en basit büyüleri bile yaptırtamaz ona."},{"a":"malady","t":"Şimdi de olanlar yüzünden üstünde korkunç bir lanet var demek... Ona nasıl yardım edebiliriz?"},{"a":"veteran","t":"Senin yanına geldi, değil mi? Yardım istemesi bile iyiye işaret! "},{"a":"veteran","t":"Çok akıllı olmasa da aşırı inatçıdır. Bir çözüm bulur elbet."}]},{"id":"rudo_10","i":10,"title":"Aidiyet Nakli","req":"rudo:10","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"rudo","t":"Pekâlâ seni pis sopa. Bir anlaşma yapalım."},{"a":"rudo","t":"Seni şu Belalıya vereceğim."},{"a":"monster_Forest_Blacksmith","t":"Ciyak! Bırak gideyim!"},{"a":"rudo","t":"Onla can ciğer dost ol ve tüm bu yaşananları unutalım."},{"a":"rudo","t":"Eğer bunu yapmak istemezsen..."},{"a":"rudo","t":"Lavların içine atlarım. O zaman hangimiz daha uzun süre dayanacak görürüz."},{"a":"rudo","t":"Seç bakalım. Bana sorarsan \"su\" çok iyi görünüyor!"},{"a":"monster_Forest_Blacksmith","t":"..."},{"a":"rudo","t":"İyi seçim. Eğlenmene bak Belalı."},{"a":"monster_Forest_Blacksmith","t":"Ah! Sıkışmış!"},{"a":"rudo","t":"Hah ha ha! Görüşürüz!"}]},{"id":"rudo_epilogue","i":11,"title":"Son Söz","req":"rudo:11","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"lilu","t":"Rudo! Geçen seferle ilgili..."},{"a":"rudo","t":"Hı?"},{"a":"lilu","t":"Ah! Değnekten kurtulmuşsun!"},{"a":"rudo","t":"Evet. Yeterince endişem vardı."},{"a":"rudo","t":"...Geçen seferle ilgili özür dilerim. Biraz gergindim."},{"a":"lilu","t":"...Sanırım seni affedebilirim. Ancak sihirbazlara karşı olan tavırlarını düzeltmelisin!"},{"a":"rudo","t":"Hah! Malady beklenmedik şekilde yardımcı oldu. Kim bilir belki bir gün fikirlerim değişir."},{"a":"lilu","t":"Laneti kaldırmayı başarabildi mi?"},{"a":"rudo","t":"Tam olarak değil. Ama onun sayesinde beklenmedik bir yardım eli uzatıldı."},{"a":"rudo","t":"Arada bir işbirliği yapmanın kimseye zararı olmaz. Hahaha!"},{"a":"argon","t":"Ashley, dikkat et! Bir şey daha geliyor!"},{"a":"ashley","t":"Her şeye hazırım! Gel bakalım yaratık!"},{"a":"monster_Forest_Blacksmith","t":"...Yardım..."},{"a":"argon","t":"Ha?"},{"a":"ashley","t":"Haaaaaa?"}]}]},{"id":"sia","name":"Sia","chapters":[{"id":"sia_01","i":1,"title":"Kralın İlk Adımları","req":"sia:1","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"king","t":"Sia! Kararımı verdim!"},{"a":"sia","t":"Buyurun majesteleri."},{"a":"king","t":"Bugün alışverişe çıkmak istiyorum!"},{"a":"sia","t":"Harika bir fikir majesteleri."},{"a":"sia","t":"Gelgelelim programınıza bakacak olursak bugün yabancı liderlerle buluşacaksınız..."},{"a":"king","t":"Ama çok sıkıcı! Onları göndersek olmaz mı?"},{"a":"sia","t":"Unutmayın Kralım, genç olsanız da Kral sizsiniz. Sözünüz kanun demektir."},{"a":"king","t":"Kesinlikle haklısın! O zaman alışverişe çıkıyoruz! Liderler bekleyebilir!"},{"a":"sia","t":"Kararlılığınız takdire şayan. Size eşlik edebilir miyim?"},{"a":"king","t":"Tabii ki! Hürmetli şahsımın koruması işinde başka kimselere güvenemem."}]},{"id":"sia_02","i":2,"title":"Alt Kesimden Dostlar","req":"sia:2","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"sia","t":"Bu yüzden Kralımızın hayatının tehlikede olabileceğini düşündüren bazı nedenlerim var."},{"a":"elderowen","t":"Anlıyorum. Kralın hayatına kastedilmesinden birkaç rakip krallık fayda sağlar tabii..."},{"a":"elderowen","t":"Hiç şüpheli bir tip görmedim ama eminim tavernadaki Naya bir şeyler biliyordur."},{"a":"sia","t":"Teşekkür ederim ihtiyar. Bilgeliğinin ve vatanseverliğin çok yardımcı oldu."},{"a":"elderowen","t":"Lafı bile olmaz. Krallığımızın refahını düşünmek bir vatandaş olarak benim görevim."},{"a":"elderowen","t":"Genç ve aptal olsa da eminim Reinhold zamanla çok iyi bir kral olacak."},{"a":"sia","t":"O yaşları gördüğünü görmek benim görevim!"},{"a":"tavern","t":"Vay vay vay, tavernada soyluları görmeye pek alışkın değiliz!"},{"a":"sia","t":"Zevzekliği kes Naya, kim olduğumu biliyorsun."},{"a":"tavern","t":"Bilmez miyim! Sia Leonel, Kern imparatorunun Kralımıza hediyesi..."},{"a":"tavern","t":"Hem danışmanı olmak hem de gözünü üzerinde tutmak için, doğru mu?"},{"a":"sia","t":"..."},{"a":"sia","t":"Çok meraklısın, değil mi?"},{"a":"sia","t":"Söyle bakalım meraklı Naya..."},{"a":"sia","t":"Son zamanlarda tavernaya gelen yabancılar gördün mü?"},{"a":"tavern","t":"Hah, buradan yabancı eksik olmaz ki! Çakırkeyif orklar, tüccarlar..."},{"a":"tavern","t":"Ama içlerinde en garibi de şu köşedeki kız sanırım."},{"a":"yami","t":"..."},{"a":"sia","t":"Kaçtı..."},{"a":"sia","t":"Bir Azuman casusuydu! Ya da suikastçısı..."},{"a":"sia","t":"Her zamankinden çok daha dikkatli olmam gerekiyor."}]},{"id":"sia_03","i":3,"title":"Davetsiz Misafir","req":"sia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"sia","t":"Bugün burada, Kralımızın olağanüstü cömertliğini kutlamak amacıyla toplanmış bulunuyoruz."},{"a":"sia","t":"Geçtiğimiz aylarda, kendileri hazineden birkaç milyon altını..."},{"a":"sia","t":"Çok sayıda yerel tapınak, okul ve yetimhaneye bağışladı."},{"a":"sia","t":"Herkes bu ziyafete davetlidir, dolayısıyla lütfen eş dost herkesi haberdar edin."},{"a":"sia","t":"Çok yaşa Kral Reinhold!"},{"a":"yami","t":"Zorba Kral Reinhold... Saltanatın artık sona eriyor!"},{"a":"king","t":"Ahhh..."},{"a":"sia","t":"Bir ninja yıldızı! Azuman casusu!"},{"a":"sia","t":"Muhafızlar! Kalenin etrafını sarın! Kimsenin kaçmasına izin vermeyin sakın!"},{"a":"sia","t":"Argon, suikastçının peşinden git!"},{"a":"argon","t":"Derhâl!"},{"a":"sia","t":"Sen! Soytarı kılıklı! Kralımız yaralandı! Hemen bir şifacı bul!"},{"a":"leather","t":"Bu ne kabalık yahu!"},{"a":"sia","t":"(Bütün giriş noktaları en üst düzeyde gözetleniyor...)"},{"a":"sia","t":"(Şu kız da kim?)"}]},{"id":"sia_04","i":4,"title":"Şantaj Mektupları","req":"sia:4","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"sia","t":"Meraklı Naya, bana bir açıklama borçlusun."},{"a":"tavern","t":"Ah, Bayan Leonel... Bence SEN bana bir açıklama borçlusun."},{"a":"sia","t":"Pardon?"},{"a":"tavern","t":"Bazı oldukça İLGİNÇ mektuplar geçti elime. Sanırım senin tarafından gönderilmişler."},{"a":"tavern","t":"Birlikte okuyalım mı?"},{"a":"sia","t":"!"},{"a":"tavern","t":"Bir bakalım... Kern mührü ha? Kern imparatoruna yazılmış bir mektup!"},{"a":"tavern","t":"Vah vah. Skandal bir aşk macerası bekliyordum oysa, ama vatan hainliği de iş görür."},{"a":"sia","t":"Na-Naya, dur lütfen!"},{"a":"tavern","t":"Aha! Can alıcı yeri geliyor!"},{"a":"tavern","t":"\"Kral Reinhold o kadar aptal ki, tahtta olması işinize gelir.\""},{"a":"tavern","t":"\"Hayatta kalması, krallığı için tahtın boş kalmasından çok daha az tehlike arz ediyor.\""},{"a":"sia","t":"..."},{"a":"tavern","t":"Bana kalırsa bu talihsiz sözler kralın danışmanına hiç yakışmıyor!"},{"a":"sia","t":"Meraklı... Naya... Bu yaptığını ödeyeceksin!"},{"a":"tavern","t":"O gün de gelir elbet. Ancak şimdi kimin kime ödeyeceği belli. Hem de ağır şekilde."},{"a":"sia","t":"Şantaj yapacak kadar düştün demek?"},{"a":"tavern","t":"Vatan hainliğinin yanında bu ne ki?"},{"a":"tavern","t":"Kralımıza zarar vermek gibi bir niyetin varsa şayet..."},{"a":"sia","t":"Öff... Tamam. Bana ne istediğini söyle. Dua et de casus ağım seninkini alt etmesin."},{"a":"tavern","t":"Öyle olmasını dört gözle bekliyorum!"}]},{"id":"sia_a","i":4,"title":"Kral'ın Kaprisi","req":"sia:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Şans Jetonları"},"side":true,"lines":[{"a":"sia","t":"Majesteleri."},{"a":"king","t":"Sevgili Sia! Sana nasıl yardımcı olabilirim?"},{"a":"sia","t":"Şans eseri son zamanlarda şu ufak çılgınlıklarınızdan birini yaşamış olabilir misiniz acaba?"},{"a":"king","t":"Ha-hayır! Tabii ki yaşamadım! Asla!"},{"a":"sia","t":"Tuhaf. Kayıtlarımıza göre 36 numaralı Kasanın ağzına kadar <c1>Kunai</c1> ile dolu olması gerekirdi."},{"a":"sia","t":"Majestelerine bunun aşırı derecede nadir bir eşya olduğunu hatırlatmama gerek yoktur herhalde."},{"a":"king","t":"E-eminim ki mantıklı bir..."},{"a":"sia","t":"Ayrıca, krallığın en nadir antikalarından pek çoğu bu aralar sıradan ahalinin ellerinde görüldü."},{"a":"sia","t":"Cömertliğiniz övgüye değer..."},{"a":"sia","t":"Ama lütfen ruh hâlinizdeki değişimleri finanse etmek için paha biçilemez eserleri sağa sola dağıtmaktan kaçının."},{"a":"king","t":"Öff. Pekâlâ! Bugünden itibaren ben farklı bir insanım!"},{"a":"sia","t":"Anlayışınız için teşekkürler. İzninizi rica ederim."},{"a":"king","t":"İrademi hiçbir şey sarsamaz! Dünyevi şeylere ihtiyacım yok benim!"},{"a":"king","t":"Tabii bu odadaki <c1>Kraliyet Kılıçlarından</c1> birkaçını kullanabilirim, değil mi?"}]},{"id":"sia_05","i":5,"title":"Ajan Kuğuboyun","req":"sia:5","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"sia","t":"Birtakım önemli gelişmeler oldu ve Kral Reinhold'a suikast girişiminde bulunuldu."},{"a":"sia","t":"Bu suikastın arkasında Azuma olabilir. İşin iç yüzünü Ajan Kuğuboyun araştıracak."},{"a":"king","t":"Sia! Ne yapıyorsun?"},{"a":"sia","t":"Ah, öylesine bir mektup yazıyordum. Siz kafanıza takmayın."},{"a":"sia","t":"(Kern imparatoruna raporum, şeyle ilgili...)"},{"a":"king","t":"Pekâlâ! Yabancı liderler varlığımla onurlandırılmayı bekliyor."},{"a":"king","t":"Sanki... Geçen seferki alışveriş gezintisinden gocunmuşlar gibi."},{"a":"king","t":"Tansiyonu düşürürsen yardımların karşısında hayli müteşekkir olurum!"},{"a":"sia","t":"Elbette. Hemen ilgileneceğim Kralım."},{"a":"sia","t":"Kern imparatorunun bu suikast girişimini öğrenmesini engellemezsem çok kötü şeyler olabilir..."},{"a":"sia","t":"Benim... Biraz daha düşünmem gerek. Bu krallık henüz Kern'le karşı karşıya gelmeye hazır değil."},{"a":"sia","t":"Herkesin güvenliği uğruna... Sanırım bu ayrıntıyı atlayabilirim..."},{"a":"sia","t":"Her şey planlandığı gibi gidiyor. Ajan Kuğuboyun'un bu ay rapor verecek herhangi bir şeyi yok."}]},{"id":"sia_06","i":6,"title":"Gül ve Diken","req":"sia:6","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"king","t":"Sia! Bir ziyaretçin var! Gerçekten de bir prense benzediğini söyleyebilirim."},{"a":"sia","t":"Prens mi Kralım? Hiç sanmam ki..."},{"a":"donovan","t":"Leydi Sia."},{"a":"sia","t":"Donovan."},{"a":"sia","t":"Kralım, hazinede acil bir mesele sizi bekliyor. Hemen ilgilenmenizi öneririm."},{"a":"king","t":"Ooo, son Saf Altın sevkiyatı nihayet geldi mi? Sabırsızlanıyorum!"},{"a":"donovan","t":"Bu kral hiç akıllanmıyor. Değil mi?"},{"a":"sia","t":"Hangi ters rüzgâr seni Reinhold'un krallığına attı simyacı?"},{"a":"donovan","t":"Her zamanki hemen sadede gelelim, değil mi Ajan Kuğuboyun."},{"a":"donovan","t":"Yalnızca kişisel izindeyim. Kern İmparatoru'nun müsaadesiyle elbette."},{"a":"donovan","t":"Çiçekleri kokluyor, iksirlerden tadıyorum... Simyacı tatili denebilir."},{"a":"sia","t":"Onca yer varken burayı mı seçtin?"},{"a":"donovan","t":"Bu kendi hâlindeki krallıkta ziyadesiyle yetenekli simyacı var gibi görünüyor."},{"a":"donovan","t":"Yani bir kuğu boyunlunun sadakatinden şüpheye düşülürse..."},{"a":"sia","t":"Maksadını açıkladın Donovan. Tatilinin... Tadını çıkarmaya gidebilirsin."},{"a":"donovan","t":"Nasıl isterseniz Leydi Sia. Her zamanki gibi benim için bir zevkti."},{"a":"sia","t":"Bir baş belası daha."}]},{"id":"sia_07","i":7,"title":"Altın Şehrin Yabancısı","req":"sia:7","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"sia","t":"Donovan? Umarım... Casusluk sırasında seni bölmüyorumdur."},{"a":"donovan","t":"Ah! Leydi Sia."},{"a":"donovan","t":"Hayır, hiç de değil! Öyle bakınıyordum."},{"a":"sia","t":"Bu kadar gizli saklı olmaya gerek yok. Kayıp Altın Şehir'de herkese kapımız açık."},{"a":"sia","t":"Ancak Krallık kanunlarına göre burada bulunan her bir <c1>Saf Altının</c1> Kral Reinhold'a ait olduğunu unutma."},{"a":"sia","t":"Bunun karşılığında, cesur maceracılar katkılarından dolayı ödüllendirilirler."},{"a":"donovan","t":"Anlıyorum. Son derece... Cömert bir hükümdar."},{"a":"donovan","t":"Daha sonra <c1>Saf Altın</c1> sikkelere dönüştürülür ve para biriminde ani bir enflasyona sebep olur..."},{"a":"sia","t":"Doğru. İmparatora gönderdiğim postaları ele geçirmişsin bakıyorum."},{"a":"donovan","t":"Bilgi sahibi olmak beni mutlu ediyor."},{"a":"sia","t":"Burada olduğuna göre bir işe yara da kaleye biraz <c1>Saf Altın</c1> taşıyıver."},{"a":"donovan","t":"Tabii ki. Leydim nasıl isterse."},{"a":"sia","t":"Dönüş yolunca bir tarafını kırmamaya çalış sevgili Donovan."}]},{"id":"sia_08","i":8,"title":"Kaderin Kesişme Noktasında","req":"sia:8","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"tavern","t":"Küçük Kuğuboyun'um geri dönmüş! Muhteşem yöneticimizden beklediğimiz kadar da dakiksin!"},{"a":"sia","t":"Çağırdın, ben de geldim Meraklı Naya. Çok havamda değilim. Lütfen çabuk olalım."},{"a":"tavern","t":"O zaman havan hepten bozulacak desene! Tanıdığımız bir Simyacının postasını ele geçirdim..."},{"a":"tavern","t":"Hızlandırılmış Sihirpostasıydı hem de! Onları ele geçirmek ne kadar zor bilir misin!"},{"a":"sia","t":"Yani..."},{"a":"tavern","t":"Donovan, küçük oyunumuzu fark etmiş sanırım."},{"a":"sia","t":"Ele geçirdiysen, o zaman..."},{"a":"tavern","t":"Evet, hiçbir yere gidemez! Parasını verirsen alırsın tabii..."},{"a":"sia","t":"Ben... Pekâlâ. Fiyatını söyle Naya. Öderim."},{"a":"tavern","t":"Biraz zam yaptım. Bu özel ödülün özel bir fiyatı var."},{"a":"sia","t":"Pekâlâ... Öderim..."},{"a":"tavern","t":"Tarafını seç Sia. Fiyatım bu."},{"a":"sia","t":"..."},{"a":"tavern","t":"Çift taraflı oynamak tehlikeli bir iş... Sen de bu işe iyice batmışsın gibi görünüyor."},{"a":"tavern","t":"Tabii vereceğin cevaba bağlı olarak yardımcı olabilirim."}]},{"id":"sia_09","i":9,"title":"İhanet Zinciri","req":"sia:9","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"sia","t":"Sevgili Donovan. Senden bir isteğim olacak."},{"a":"donovan","t":"Öyle mi? Söyle bakalım."},{"a":"sia","t":"İmparatora git. Ona Ajan Kuğuboyun'un öldüğünü, son anına kadar İmparatorluğa layıkıyla hizmet ettiğini, bunun onurlu ve trajik bir kayıp olduğunu söyle."},{"a":"donovan","t":"Nasıl yani?"},{"a":"sia","t":"Benden bu kadar Donovan. Taraf değiştiriyorum."},{"a":"sia","t":"Bu haberi ona sen vereceksin. Hikâyemi de biraz destekleyeceksin tabii."},{"a":"donovan","t":"İnanamıyorum! Bu çok ağır bir ihanet! Ben asla..."},{"a":"sia","t":"Bence bunu yapacaksın Donovan. Tabii tüm dünyanın ölümsüzlük iksirinin formülünü öğrenmesini istiyorsan o başka..."},{"a":"donovan","t":"Boş tehditlerinde bu kadar ileri gideceğini düşünmemiştim Sia. Ben bu tarifi kimseyle paylaşmadım. Kimse asla..."},{"a":"sia","t":"Nasıldı? Yüz yaşında bir mayıs sineğinden bir çift kanat... Styx suyu..."},{"a":"donovan","t":"Sen nasıl..."},{"a":"sia","t":"Çok fazla malzeme vardı... Bir de tat vermesi için biraz da şarap mı gerekiyordu sanki..."},{"a":"donovan","t":"S-sus! SESSİZ OL! Bunları hangi karanlık güçlerden öğrendin bilmiyorum ama..."},{"a":"sia","t":"Casuslarımı biraz hafife almışsın belli ki."},{"a":"donovan","t":"Bu küçük oyununu oynayacağım. Sadece bu seferlik."},{"a":"sia","t":"Kaybetmeye hiç gelemiyorsun gibi. Benim şartlarımın çok daha iyi olduğunu düşünüyorum."},{"a":"sia","t":"Hayatının işine karşılık küçük bir ihanetten ne çıkar?"}]},{"id":"sia_10","i":10,"title":"Vasiyete Yataklık","req":"sia:10","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"sia","t":"Ajan Fısıltı. Ben geldim."},{"a":"essence","t":"*Esner* Ne çabuk?"},{"a":"sia","t":"Verdiğin istihbarat doğruydu. Mükemmel bir iş çıkardın, tebrikler."},{"a":"essence","t":"Mühim... değil..."},{"a":"sia","t":"Donovan hep çok dikkatlidir ama hayaletten saklanmanın da peki yolu yok!"},{"a":"essence","t":"Aynen..."},{"a":"essence","t":"Çok... sinirliydi..."},{"a":"sia","t":"Anlaştığımız üzere ödemeni adak olarak mezarına bırakacağım."},{"a":"sia","t":"Küçük bir de ikramiye ekledim. Gidip benim için Donovan'la biraz daha uğraşmanı rica ediyorum."},{"a":"essence","t":"Hayaletlik yapıyor... üstüne de para alıyorum... Harika."}]},{"id":"sia_11","i":11,"title":"Özgürlüğe Uçan Kuğu","req":"sia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"king","t":"Sia! Kendimi zor tutuyorum! Kaprislerimi tüm dünyaya salmadan önce daha ne kadar beklemem gerekiyor?"},{"a":"sia","t":"Daha yalnızca birkaç gün oldu Majesteleri. Lütfen biraz daha sabredin."},{"a":"king","t":"Bu evrak işleri neyle ilgili?"},{"a":"sia","t":"Doğum belgeleri ve benimle ilgili diğer önemli yönetim evrakları."},{"a":"sia","t":"Görünüşe göre, bu krallıktaki hayatımla ilgili detayları içeren evrakların büyük bir kısmı tamamen şans eseri kaybolmuş."},{"a":"sia","t":"Ben de bu formları hafızamdaki bilgilerle dolduruyordum."},{"a":"king","t":"Tabii ki! En mühim danışmanımın Krallığımın tebaasından olmaması düşünülemez!"},{"a":"king","t":"Öyle olsun! Hepsini ivedilikle kraliyet mührümle mühürleyeceğim!"},{"a":"king","t":"Hepsi tamam! Her zamanki gibi gözünden hiçbir detay kaçmamış!"},{"a":"sia","t":"Teşekkürler Majesteleri. Onlarca yıl daha emrinize amadeyim."},{"a":"king","t":"Aksi düşünülemezdi zaten!"},{"a":"king","t":"Gözlerin mi yaşardı Sia? Evrak işleriyle uğraşırken mutluluktan ağlıyor musun yoksa?"},{"a":"sia","t":"Hayır... Aksine can sıkıntısından gözlerim yaşardı."},{"a":"sia","t":"Pekâlâ! Şimdi Kaprislerinden konuşalım mı?"},{"a":"king","t":"Olur! Bana kalırsa mevcut Kalkan durumu..."}]}]},{"id":"atlab_sokka","name":"Sokka","chapters":[{"id":"atlab_sokka_01","i":1,"title":"Büyük Savaşçı Sokka","req":"atlab_sokka:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Şans Jetonları"},"side":false,"lines":[{"a":"atlab_aang","t":"Peki... Buna ne demeli?"},{"a":"tavern","t":"Eh, hoş bir numaraymış!"},{"a":"atlab_sokka","t":"Öf. Bunu hep yapıyor!"},{"a":"argon","t":"Merhaba. Adın Sokka idi, değil mi? Ben Argon!"},{"a":"atlab_sokka","t":"Merhaba. Element bükme numaraları görmek istiyorsan o işe Aang bakıyor."},{"a":"argon","t":"Yok, ben büyüden ya da element bükmeden pek anlamam."},{"a":"argon","t":"Ekipmanlarından anladığım kadarıyla sen müthiş bir savaşçı olmalısın."},{"a":"atlab_sokka","t":"Müthiş bir savaşçı mı?"},{"a":"atlab_sokka","t":"Şey... Doğru anlamışsın! Ben Sokka! Avatar Takımı'nın Muhteşem Savaşçısıyım!"},{"a":"argon","t":"Biliyordum! Anlatacak bir sürü harika hikâyen olmalı!"},{"a":"atlab_sokka","t":"Olmaz mı? Mesela Agna Qel'a kuşatmasında..."},{"a":"atlab_sokka","t":"...ve böylece o zamanki sevgilim aya dönüştü."},{"a":"argon","t":"Ay mı dedin?"},{"a":"atlab_sokka","t":"Evet, ama sonra Ateş Ulusu donanması geldi ve..."},{"a":"atlab_sokka","t":"...ve pat diye kütüphanedeki o dev baykuşu bayılttım!"},{"a":"argon","t":"Vay canına! O baykuş güçlü bir ruh değil miydi peki?"},{"a":"atlab_sokka","t":"Öyleydi ama Sokka olduğu sürece Avatar Takımı her zaman kazanır!"},{"a":"atlab_sokka","t":"Avatar demişken, Aang nerede?"},{"a":"argon","t":"Şey, yaklaşık bir saat önce gitti."},{"a":"atlab_sokka","t":"Ne? Zamanın nasıl geçtiğini fark etmemişim. Üzgünüm Argon, gitmem gerek!"}]},{"id":"atlab_sokka_02","i":2,"title":"Büyük Demirci Sokka","req":"atlab_sokka:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Şans Jetonları"},"side":false,"lines":[{"a":"blacksmith","t":"İşin başından aşkın galiba Sokka."},{"a":"atlab_sokka","t":"Selam Wallace. Aletlerini kullanmama izin verdiğin için teşekkürler!"},{"a":"blacksmith","t":"Rica ederim! Bu genç yaşında bu kadar usta olacağını düşünmemiştim doğrusu!"},{"a":"atlab_sokka","t":"Grupta bükücü olmayan tek kişiysen her türlü beceriyi öğrenmen gerekiyor işte."},{"a":"atlab_sokka","t":"Zaten bunun gibi harika aletleri her gün kullanmıyorum..."},{"a":"atlab_sokka","t":"Bakım göz açıp kapayıncaya kadar bitecek!"},{"a":"blacksmith","t":"Bilediğin o kılıcı nereden aldın?"},{"a":"atlab_sokka","t":"Bu benim Uzay Kılıcım! Kendim dövdüm!"},{"a":"blacksmith","t":"Yıldız Metalinden, öyle mi? Hiç fena değil evlat!"},{"a":"blacksmith","t":"Resmen başka bir dünyadan gibi!"},{"a":"atlab_sokka","t":"Aynen öyle! Dünyada bunun gibi tek bir kılıç daha yoktur!"},{"a":"polonia","t":"Rast gele! Böldüğüm için kusura bakmayın ama siz gençlerden biri gemimi tamir etmeme yardım edebilir mi?"},{"a":"polonia","t":"Bugün biraz hırçın da. Altını tuhaf demir toplara çarptı ve karaya oturdu..."},{"a":"blacksmith","t":"Açıklarda sorun var gibi!"},{"a":"atlab_sokka","t":"Hiç dert değil, ben Su Kabilesi'ndenim! Ne yapabilirim bir bakayım. Üzgünüm Wallace, gitmem gerek!"},{"a":"blacksmith","t":"Ben de o sırada ekipmanının geri kalanını onarayım. İyi şanslar!"}]},{"id":"atlab_sokka_03","i":3,"title":"Büyük Denizci Sokka","req":"atlab_sokka:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Şans Jetonları"},"side":false,"lines":[{"a":"atlab_sokka","t":"İşte oldu. En azından artık güvenle limana çekebiliriz."},{"a":"polonia","t":"Çok güzel onardın. Sağlam oldu!"},{"a":"atlab_sokka","t":"Gerçi geminin dümenini bir arada tutan şey karaya vuran odunlar ve gömleğimden birkaç kumaş parçası."},{"a":"atlab_sokka","t":"\"Sağlam\" demeyelim de, Sokka çözümü diyelim."},{"a":"polonia","t":"Yelkenler fora o zaman! Peki senin gibi acemi bir denizci gemi onarımını nereden biliyor?"},{"a":"atlab_sokka","t":"Su Kabilesi'nde hayat tamamen tekneler ve balıkçılıkla ilgiliydi. Daha yürümeyi öğrenmeden denize açıldım ben."},{"a":"atlab_sokka","t":"Hatta geçenlerde su bükme gücüyle çalışan bir denizaltı tasarladım!"},{"a":"polonia","t":"Karacılar gibi konuşuyorsun, anlamıyorum. Denizaltı nedir?"},{"a":"atlab_sokka","t":"Şey... Suyun altından giden metal bir gemi."},{"a":"polonia","t":"Denizcileri denizin dibine şık bir metal kutuda gönderiyorsun yani."},{"a":"engineer","t":"\"Çok tehlikeli, test edilmemiş prototip\" mi dedin?"},{"a":"atlab_sokka","t":"Şey... Tam öyle demedim ama..."},{"a":"engineer","t":"Tarzını sevdim. Beni izle yeni çocuk."},{"a":"polonia","t":"Yelkenler fora, açık denize gidiyoruz! Ödül avcıları buraya gelmeden demir alıyoruz!"},{"a":"polonia","t":"Bu sefer şu yüzen demir toplara dikkat etsek iyi olacak."}]},{"id":"atlab_sokka_04","i":4,"title":"Büyük Mucit Sokka","req":"atlab_sokka:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Şans Jetonları"},"side":false,"lines":[{"a":"engineer","t":"Büyüleyici! Dürüst olmak gerekirse taslağın biraz uyduruk..."},{"a":"engineer","t":"Ama üzerinde biraz çalışırsak bu denizaltı iş görebilir!"},{"a":"atlab_sokka","t":"Dâhice, değil mi? Biliyordum!"},{"a":"atlab_sokka","t":"Yine de unutma ki bu denizaltı Su Bükücüler tarafından çalıştırılmak üzere tasarlanmıştı."},{"a":"engineer","t":"Orası işin teferruatı. Bir çaresini buluruz, merak etme."},{"a":"engineer","t":"Bir düşünsene! Bununla Su Altı Tapınağı'nı keşfedebiliriz!"},{"a":"atlab_sokka","t":"Bir de çok fazla oksijen depolayamıyor, o yüzden yolculuğu kısa tutman gerek."},{"a":"atlab_sokka","t":"Beni dinliyor musun sen?"},{"a":"engineer","t":"O büyük demir küreye yaslanma."},{"a":"atlab_sokka","t":"Ne? Aman! Neden ki?"},{"a":"engineer","t":"O benim deniz bombası prototipim. Son derece patlayıcıdır."},{"a":"atlab_sokka","t":"Ah, demek öyle."},{"a":"atlab_sokka","t":"Neyse o zaman, prototipin nasıl çalıştığını bana sonra anlatırsın."},{"a":"atlab_sokka","t":"Çalışırsa gelecekte bunu bir yerlerde kullanabiliriz."}]}]},{"id":"leather","name":"Tamas","chapters":[{"id":"leather_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"leather","t":"Hey, dostum. Sanırım Şampiyonlukla işim bitti."},{"a":"leather","t":"Meğer düşündüğümden çok daha fazla sorumluluk istiyormuş. Deri işlerime bile zar zor zaman ayırabiliyorum!"},{"a":"leather","t":"Belki seneye tekrar denerim dostum. Şehirde görüşürüz!"}]},{"id":"leather_01","i":1,"title":"Deri ve Ağaç","req":"leather:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Şans Jetonları"},"side":false,"lines":[{"a":"leather","t":"Yardımın için teşekkürler dostum."},{"a":"argon","t":"Önemli değil Tamas! O kadar çok deri var ki!"},{"a":"leather","t":"Bugün büyük vurgun yaptım. O yüzden attığın adıma dikkat et."},{"a":"argon","t":"Evet, ortalık biraz karışmış... Ahhh!"},{"a":"leather","t":"Ahh! Of!"},{"a":"argon","t":"Pardon Tamas! İyi misin?"},{"a":"leather","t":"Kafamı çarptım ama sanırım iyiyim."},{"a":"leather","t":"Dâhiyane bir fikrim var dostum."},{"a":"leather","t":"Gitmem gerek dostum. Bu çok önemli."},{"a":"argon","t":"Elbette! Yardım edebildiysem ne mutlu bana!"},{"a":"argon","t":"İyi de tüm bu deri parçalarıyla ne yapacağım?"}]},{"id":"leather_02","i":2,"title":"Kehanette Söylendiği Gibi","req":"leather:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Şans Jetonları"},"side":false,"lines":[{"a":"leather","t":"İşte kafamı da tam olarak böyle çarptım. Bak, şurası şişti."},{"a":"mana","t":"Seni dinler ama yardım edemez."},{"a":"mana","t":"Eter akışları ilahidir ve gerçekleri açığa çıkarır ancak iyileştirmez."},{"a":"leather","t":"İşin içinde yine büyü var ama, değil mi? Hadi dostum, sihirli ellerinle bir dokun."},{"a":"mana","t":"Burada hiç..."},{"a":"mana","t":"..."},{"a":"mana","t":"Bu... kader! Bunaltıcı!"},{"a":"leather","t":"Sence işe yaradı mı dostum? Başım hâlâ biraz dönüyor."},{"a":"mana","t":"Özür dilerim.Yeni bir önsezi seansı için meditasyon yapmam gerek."},{"a":"mana","t":"Yaraların için Tanrıçanın Lütfuna başvur. Benim hemen yola çıkmam gerekiyor."},{"a":"leather","t":"Tamamdır dostum. Galiba işi zamana bırakacağım, zaten kendimi daha iyi hissediyorum."}]},{"id":"leather_03","i":3,"title":"Şampiyonlar Birliği","req":"leather:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Şans Jetonları"},"side":false,"lines":[{"a":"argon","t":"Demek artık yeni bir Şampiyonumuz var."},{"a":"polonia","t":"Ooo! Umarım doğru dürüst bir tiptir!"},{"a":"leather","t":"Selam dostlar."},{"a":"polonia","t":"Patlayan sülükayaklılar mı? Şaka mı bu?"},{"a":"lilu","t":"Tamas! Sen ne zaman..."},{"a":"leather","t":"Bu Şampiyonluk işini bir denemeye karar verdim dostum. Çok zor görünmüyor."},{"a":"argon","t":"Tamas, yaptığın şeyi neden bize anlatmıyorsun?"},{"a":"leather","t":"Canavarları pataklıyorum dostum. Ayrıca kilometrelerce uzaktan kokusunu alarak deri eşyaları bulabilirim."},{"a":"polonia","t":"Bir şeyler çalmak BENİM işim! Sen kendi işine bak!"},{"a":"leather","t":"Buna çalmak denemez dostum. İnsanlar onları öylece ortalık yerde bırakıyor."},{"a":"lilu","t":"Burada ortalık fena karışacak gibi görünüyor!"},{"a":"polonia","t":"Evet, haklı olabilirsin..."}]},{"id":"leather_04","i":4,"title":"İsimsiz Kahraman","req":"leather:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Şans Jetonları"},"side":false,"lines":[{"a":"sia","t":"Majesteleri çok sıra dışı bir maruzatım var."},{"a":"king","t":"Her zamanki gibi seni dinliyorum! Anlat bakalım!"},{"a":"sia","t":"Kahramanlar ve kervanlar, yolların hiç olmadığı kadar güvenli olduğunu bildiriyorlar."},{"a":"sia","t":"Canavarlar ortalıkta gözükmedikleri gibi başkalarına saldırmaya bile korkuyorlar."},{"a":"king","t":"Muhteşem haber!"},{"a":"sia","t":"Fakat bu tuhaf davranışın asıl nedenini bilemiyoruz."},{"a":"sia","t":"Aynı şekilde pazar yerinde de Deri eşyalara karşı birden bir ilgi hasıl oldu."},{"a":"king","t":"Tesadüf olduğuna eminim. Bu güzel haberin şerefine ziyafet verip kutlama yapalım!"},{"a":"sia","t":"Belki de Majesteleri... belki de."}]}]},{"id":"yami","name":"Yami","chapters":[{"id":"yami_01","i":1,"title":"Azuman Gezgini","req":"yami:1","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"monster_forest_Boss","t":"Ha ha haa! Kimler varmış burada?"},{"a":"yami","t":"Hıh. Kaybol baş belası."},{"a":"monster_forest_Boss","t":"Çok kabasın genç bayan! Bir de rüküşsün!"},{"a":"yami","t":"..."},{"a":"monster_forest_Boss","t":"A ha! Aynı doğudaki insan krallığı Azuma gibi kokuyorsun!"},{"a":"monster_forest_Boss","t":"Evinden bu kadar uzaklarda ne yapıyorsun sen?"},{"a":"monster_forest_Boss","t":"Silahlarını kuşanmışsın, ağzını da bıçak açmıyor. Kesin suikastçısın sen, değil mi?"},{"a":"yami","t":"..."},{"a":"monster_forest_Boss","t":"Ha ha ha! Biliyordum! Aptal insanlar, sürekli birbirlerini öldürüyorlar!"},{"a":"yami","t":"Haklısın. Buralara kadar zorba bir kralı öldürmek için geldim."},{"a":"monster_forest_Boss","t":"Eee ama! Bunu herkese söylersen iyi bir suikastçı olamazsın ki! Bana neden söyledin?"},{"a":"yami","t":"Çünkü başkasına anlatacak kadar yaşamayacaksın. Elveda."},{"a":"monster_forest_Boss","t":"Aman!"},{"a":"yami","t":"Kral Reinhold, sırada sen varsın."}]},{"id":"yami_02","i":2,"title":"Avcı ya da Av ol","req":"yami:2","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"yami","t":"Kalenin güvenliği çok sıkı."},{"a":"yami","t":"Şifre sistemi her gün değişiyor."},{"a":"yami","t":"Muhafız devriyelerinin programı yok."},{"a":"yami","t":"Biraz daha..."},{"a":"argon","t":"Selamlar! Sen, çalılardaki!"},{"a":"yami","t":"!"},{"a":"argon","t":"Sen de mi şövalye olmak için geldin?"},{"a":"argon","t":"Sia yakında burada olur! Saklanmana gerek yok çok nazik biridir!"},{"a":"yami","t":"Sia!"},{"a":"yami","t":"Gitmem gerek. Görüşürüz."},{"a":"argon","t":"Dur, bekle!"},{"a":"argon","t":"Vay! Sis bombası mı?"},{"a":"yami","t":"Aptalın izini kaybettim."},{"a":"yami","t":"Sia buradayken işim zor olacak."},{"a":"yami","t":"Ama yapmam gerek. Başarısız olamam."},{"a":"yami","t":"Birlik için, kardeşim için."}]},{"id":"yami_03","i":3,"title":"Dönüm Noktası","req":"yami:3","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"king","t":"Krallığımın değerli insanları! Görkemli ziyafetime iştirak ettiğiniz için hepinize teşekkürler!"},{"a":"king","t":"Bu vesileyle ayrıca eşsiz güzellikteki zatımı da görme fırsatınız oldu! Kaçırmayın derim!"},{"a":"yami","t":"(Şımarık zorba. Şaşırmadım.)"},{"a":"sia","t":"Imm... Peki. Bu oldukça öğretici konuşmanız için teşekkür ederiz, Majesteleri."},{"a":"sia","t":"Bugün burada, Kralımızın olağanüstü cömertliğini kutlamak amacıyla toplanmış bulunuyoruz."},{"a":"sia","t":"Geçtiğimiz aylarda, kendileri hazineden birkaç milyon altını..."},{"a":"sia","t":"Çok sayıda yerel tapınak, okul ve yetimhaneye bağışladı."},{"a":"sia","t":"Herkes bunun bir parçası olmaya davetli, o yüzden herkesi haberdar edin."},{"a":"sia","t":"Çok yaşa Kral Reinhold!"},{"a":"yami","t":"(Bunlar bir zorbanın yapacağı şeyler değil.)"},{"a":"yami","t":"(Ama hayır, Birlik yalan söylemez. Bu bir hile olmalı.)"},{"a":"yami","t":"Zorba Kral Reinhold... Saltanatın artık sona eriyor!"},{"a":"sia","t":"Bir ninja yıldızı! Azuman casusu!"},{"a":"yami","t":"Iskaladım mı? Olamaz!"},{"a":"sia","t":"Muhafızlar! Tüm çıkışları kapatın! Yakalayın derhâl şu kadını!"}]},{"id":"yami_04","i":4,"title":"Derin Düşünceler","req":"yami:4","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"yami","t":"(Tereddüt ettim... Başarısız oldum.)"},{"a":"yami","t":"(Birlik'in söyledikleri yalan olabilir mi?)"},{"a":"yami","t":"(Önemi yok. Artık tek başımayım.)"},{"a":"argon","t":"Sonunda buldum seni!"},{"a":"yami","t":"Aptal şövalye!"},{"a":"argon","t":"Hey! Savaşmaya gelmedim buraya!"},{"a":"yami","t":"Ben bunları yutmam, Reinhold'un köpeği seni!"},{"a":"argon","t":"Bilerek ıskaladın, değil mi?"},{"a":"yami","t":"!"},{"a":"argon","t":"Ziyafette gördüm seni. O yıldızı attığına neredeyse pişman olmuştun."},{"a":"argon","t":"Biliyor musun, aslında Kral hiç de kötü birisi değil. Arada sırada tuhaflıkları tutar, ama yine de elinden geleni yapmaya çalışır!"},{"a":"argon","t":"Kim sana bunu yapman için para verdi bilmiyorum, ama iyi adamlar olmadıkları kesin..."},{"a":"argon","t":"Kaleye geri dönüp özür dilemeyi düşündün mü? Reinhold bence..."},{"a":"yami","t":"Özür mü dileyeyim? Çok salakça."},{"a":"yami","t":"Kafam çok dolu. Hayatını birazcık da olsa umursuyorsan beni takip etme."},{"a":"argon","t":"O kötü birisi değil. Bundan eminim."},{"a":"argon","t":"Şimdi gidip Sia'ya rapor vermem gerek..."},{"a":"argon","t":"Of ya, canıma okuyacak..."}]},{"id":"yami_05","i":5,"title":"Ay Işığına Karşı","req":"yami:5","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"fabric","t":"<sprite tint=1 name=Note1>Söğütlerin gölgesinden göğe yükselen güneş, geçmişin yaydığı parıltı<sprite tint=1 name=Note2>..."},{"a":"fabric","t":"<sprite tint=1 name=Note2>Elfağacı kayranında, biz-Ciiik!"},{"a":"yami","t":"Hissettiğin o soğuk ve sivri şey, boynuna dayadığım bıçağım."},{"a":"yami","t":"Birkaç sorum olacak. Dürüst cevaplar verirsen yaşamana müsaade edebilirim."},{"a":"fabric","t":"Ahhh! E-evet! Ne ister... Oy!"},{"a":"yami","t":"Sessiz ol."},{"a":"yami","t":"Kralımız dediğiniz şu aptal... Bana ondan bahset."},{"a":"fabric","t":"K-Kral Reinhold mu? O bu diyarların hükümdarıdır..."},{"a":"fabric","t":"Biraz acayip olsa da şüphesiz erdemli ve cömerttir."},{"a":"fabric","t":"Çok tecrübeli biri sayılmaz ama yeni danışmanı Sia bu eksikliğini fazlasıyla kapatıyor!"},{"a":"yami","t":"İmkânsız! Ağzından çıkan laflar korkaklıktan başka bir şey değil ama yine de bir haklılık payı var gibi."},{"a":"yami","t":"Bu şehir! Bu şehirde kâhin var mı?"},{"a":"fabric","t":"Ah! Evet! Elf Serene, şu tepede yaşıyor!"},{"a":"fabric","t":"Gizemli yabancı... Adını öğrenme şerefine nail olabilir mi- Oy!"},{"a":"yami","t":"Karşıma birkaç gün önce çıkmış olsaydın seni düşünmeden öldürürdüm. O yüzden şansını zorlama."},{"a":"yami","t":"Şimdi yavan hayatına dön ve burada yaşanan her şeyi unut."},{"a":"fabric","t":"Vay be! Ne heyecan verici bir karşılaşma!"},{"a":"fabric","t":"Siyahlı kadın... Acaba tekrar karşılaşma şansımız olur mu?"}]},{"id":"yami_06","i":6,"title":"Kırık Piyon","req":"yami:6","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"mana","t":"İz Süren Avcının varlığını kara bir rüzgâr ele veriyor."},{"a":"yami","t":"Nasıl?"},{"a":"mana","t":"İz Süren Avcı kadın adımlarını atarken bir tüy kadar hafif ama kalbindeki ağırlık üçüncü gözden kaçmıyor."},{"a":"yami","t":"Bu kadar zırvalık yeter. Sorularıma cevap arıyorum."},{"a":"yami","t":"Birlik... Yani ailem hakkındaki sorularıma."},{"a":"mana","t":"Ölüm taciri bir yol gösterici arayışında. Peki karşılığında ne verecek?"},{"a":"yami","t":"Hayatını bağışlayacak."},{"a":"mana","t":"Öyle olsun."},{"a":"mana","t":"<c1>Bir zamanlar yanlışları doğrulara çevirmekle ilgilenirdi Azuman Birliği...</c1>"},{"a":"mana","t":"<c1>Şimdiyse birliğin şampiyonları, en yüksek teklifi verenlere teslim edildi...</c1>"},{"a":"mana","t":"<c1>Başa çıkılamaz bir göreve piyon olarak kurban edildi...</c1>"},{"a":"mana","t":"<c1>İster başarılı olsun ister başarısız, Birlik ilan ediyor zaferini.</c1>"},{"a":"yami","t":"İmkânsız."},{"a":"mana","t":"Elçinin söyleyecekleri bu kadar."},{"a":"yami","t":"İMKÂNSIZ!"},{"a":"mana","t":"..."},{"a":"mana","t":"Gölgelerde iz süren avcının ayrıca zamanla ışıkla da anlaşması gerekecek."}]},{"id":"yami_07","i":7,"title":"Kırık Piyon","req":"yami:7","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"yami","t":"Eşyalarımı toplayıp bir an önce gitmem gerekecek."},{"a":"inn","t":"Merhaba, gizemli yabancı."},{"a":"yami","t":"Hancı. Sessiz olman için sana fazladan para ödedim."},{"a":"inn","t":"Endişelenmene gerek yok, Zümrüt Hanı'nda kimsenin işine burnumuzu sokmuyoruz!"},{"a":"inn","t":"Demişken, seni arıyormuş gibi duran bazı tekinsiz ziyaretçilerimiz olduğu söyleniyor."},{"a":"yami","t":"(Birlik İnfazcıları mı? Bu kadar çabuk mu?)"},{"a":"inn","t":"İsimlerini söylemediler. Gerçekten karanlık tipler. Arkadaşların falan mı?"},{"a":"yami","t":"Artık değiller. Onlara öldüğümü söyle. Her an ölebilirim zaten."},{"a":"inn","t":"Acelecisin demek? Gidebileceğini düşündüğümden senin için bazı malzemeler hazırladım."},{"a":"yami","t":"Teşekkür ederim hancı. Ama gittiğim yerde onlara ihtiyacım olmayacak."}]},{"id":"yami_08","i":8,"title":"Dönüşü Olmayan Yolculuk","req":"yami:8","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"sia","t":"Kasvetli Tepe'ye mi yani?"},{"a":"wood","t":"Evet, senin tarifine uyan ninja görünümlü bir kız gördüm. Acelesi varmış gibi görünüyordu."},{"a":"sia","t":"Harika. Sonunda suikastçının izini bulduk."},{"a":"sia","t":"Bir devriye kuracağım ve..."},{"a":"wood","t":"Bundan emin misin? Gerekli olduğunu sanmıyorum."},{"a":"sia","t":"Neden olmasın ki Gorza?"},{"a":"wood","t":"Kasvetli Tepe'ye tek başına keşfe çıkmak intihar olur. O kız da malzeme falan paketlemiyordu."},{"a":"wood","t":"Bunu bilmemesine imkân yok. Rudo bile oraya tek başına gidecek kadar aptal değil."},{"a":"sia","t":"Öyle mi? Teşekkürler Gorza, bunu dikkate alacağım."},{"a":"sia","t":"Bu sorun muhtemelen kendi kendine çözülecek ama..."},{"a":"sia","t":"İşler nahoş bir hâl alacak. Aklından ne geçiyor suikastçı?"}]},{"id":"yami_09","i":9,"title":"Kasvetli Çatışma (Yami)","req":"yami:9","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"argon","t":"Kader dedikleri bu olsa gerek. Bir Harpia'dan bile daha büyük bir ödül!"},{"a":"yami","t":"Göster kendini. Seni şuracıkta öldürürüm."},{"a":"argon","t":"Öyle diyorsun da pek ikna olmuş gibi görünmüyorsun..."},{"a":"yami","t":"Haklısın. Artık hiçbir şey umurumda değil."},{"a":"yami","t":"Eğer gerçekten ölmemi istiyorsan beni burada ölüme terk et."},{"a":"argon","t":"Asla birini ölüme terk etmem! Seni Kral Reinhold'a geri götüreceğim!"},{"a":"argon","t":"Kralın durumu anlayacağını biliyorum! Gerekirse seni geri taşırım!"},{"a":"yami","t":"..."},{"a":"argon","t":"Hadi artık, marş!"},{"a":"argon","t":"Durun biraz, bir deri bir kemik kalmışsınız! En son ne zaman bir şeyler yediniz?"},{"a":"yami","t":"..."},{"a":"argon","t":"Dönüşte bir şeyler atıştırın, engellerle dolu bir yolculuk olacak!"}]},{"id":"yami_10","i":10,"title":"Düşman Hattının Gerisinde","req":"argon:10","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"sia","t":"Muhafızlar! Destek güçlerini toplayın ve her adımını takip edin!"},{"a":"sia","t":"Argon, biz bu... Davetsiz misafirle görüşürken dışarıda bekle lütfen."},{"a":"argon","t":"Derhâl!"},{"a":"sia","t":"Pekala, konuş bakalım suikastçı."},{"a":"yami","t":"Evet, bu doğru... Zalim kralı öldürmek için tutuldum."},{"a":"yami","t":"Ya da ben öyle sanıyordum. Görünüşe göre o sadece iyi niyetli bir soytarı."},{"a":"king","t":"S-soytarı mı!?"},{"a":"sia","t":"İnsanlarının Kralımız ile derdi ne?"},{"a":"yami","t":"Birliğim sadece adalet adına saldırıya geçer..."},{"a":"yami","t":"Ama görünüşe bakılırsa bu bir yalandı. Başarısız olduğum anda benim de işimi bitirecekler."},{"a":"yami","t":"Ben... Özür dilerim. Doğru olana boyun eğeceğim... Cezaya..."},{"a":"yami","t":"Ahh..."},{"a":"king","t":"Kız yere yığıldı!"},{"a":"sia","t":"Yorgun ve aç..."},{"a":"sia","t":"Muhafızlar! En iyi hekimlerimiz hemen onunla ilgilenmeli!"},{"a":"sia","t":"Ona kraliyet konuklarına yaraşır bir şekilde davranın."}]},{"id":"yami_epilogue","i":11,"title":"Son Söz","req":"yami:10","reward":{"k":"gems","id":"gems","q":10,"n":"Mücevher"},"side":false,"lines":[{"a":"sia","t":"Off... Uff... Sana ulaşmak... Oldukça zorlu bir tırmanış..."},{"a":"yami","t":"Burası artık benim evim."},{"a":"sia","t":"Neden şehirde konaklamıyorsun? Bağışlandın."},{"a":"yami","t":"Klanım büyük ihtimalle öldüğümü sanıyor. Böyle kalmasını tercih ederim."},{"a":"sia","t":"Anladım. İhtiyaçlarının düzenli olarak tedarik edilmesini sağlayacağım."},{"a":"sia","t":"Pekâlâ, sıradaki görevine gelince..."},{"a":"yami","t":"İmparatorluktan daha fazla ahmak mı?"},{"a":"sia","t":"Aynen öyle. Bildiğin üzere, Majesteleri kıskanç gözlerin öfkesini artırıyor."},{"a":"sia","t":"Hedeflerin hakkında daha fazla bilgi için bu belgeye bak."},{"a":"yami","t":"Bu işi halledeceğim."},{"a":"sia","t":"Bunu söylemek bana acı veriyor ama sana inanıyorum."},{"a":"sia","t":"Geri dönmeliyim. Yolculuk için sabırsızlanmıyor olsam da..."},{"a":"yami","t":"Sia... Reinhold..."},{"a":"yami","t":"Teşekkürler. Gerçekten."}]}]}];
